window.HSK_TEXTS = [{"l": 1, "texts": [{"n": 1, "zh": "对话：阿玲和小雪聊阿玲的男朋友", "vi": "Hội thoại: A Linh và Tiểu Tuyết nói về bạn trai của A Linh", "en": "Dialogue: A Linh and Xiaoxue talk about A Linh's boyfriend", "kw": ["法律", "俩", "印象", "深", "熟悉", "不仅", "性格"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "阿玲，听说你男朋友周南跟你一个学校，他是你同学吗？", "p": ["ā", "líng", "", "tīng", "shuō", "nǐ", "nán", "péng", "you", "zhōu", "nán", "gēn", "nǐ", "yí", "gè", "xué", "xiào", "", "tā", "shì", "nǐ", "tóng", "xué", "ma", ""], "vi": "A Linh, nghe nói bạn trai cậu là Châu Nam học cùng trường với cậu, anh ấy là bạn cùng lớp à?", "en": "A Linh, I heard your boyfriend Zhou Nan goes to the same university as you. Is he in your class?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "他学的是法律，我学的是汉语。我们俩不是一个班的。", "p": ["tā", "xué", "de", "shì", "fǎ", "lǜ", "", "wǒ", "xué", "de", "shì", "hàn", "yǔ", "", "wǒ", "men", "liǎ", "bú", "shì", "yí", "gè", "bān", "de", ""], "vi": "Anh ấy học luật, mình học tiếng Trung. Hai đứa không cùng lớp.", "en": "He studies law, and I study Chinese. The two of us aren't in the same class."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你们是在什么场合认识的？", "p": ["nǐ", "men", "shì", "zài", "shén", "me", "chǎng", "hé", "rèn", "shí", "de", ""], "vi": "Hai người quen nhau trong hoàn cảnh nào?", "en": "Where did you two meet?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "上个月学校去郊外拍照，我的相机突然不能用了。他帮我弄了很久，我对他印象很深。后来我们常在图书馆见面，才慢慢熟悉起来。", "p": ["shàng", "gè", "yuè", "xué", "xiào", "qù", "jiāo", "wài", "pāi", "zhào", "", "wǒ", "de", "xiàng", "jī", "tū", "rán", "bù", "néng", "yòng", "le", "", "tā", "bāng", "wǒ", "nòng", "le", "hěn", "jiǔ", "", "wǒ", "duì", "tā", "yìn", "xiàng", "hěn", "shēn", "", "hòu", "lái", "wǒ", "men", "cháng", "zài", "tú", "shū", "guǎn", "jiàn", "miàn", "", "cái", "màn", "màn", "shú", "xī", "qǐ", "lái", ""], "vi": "Tháng trước trường tổ chức đi ngoại ô chụp ảnh, máy ảnh của mình đột nhiên hỏng. Anh ấy giúp mình sửa rất lâu, mình có ấn tượng rất sâu về anh ấy. Sau đó bọn mình thường gặp nhau ở thư viện, rồi mới dần quen thuộc.", "en": "Last month the school went to the countryside to take photos, and my camera suddenly stopped working. He spent a long time helping me with it, and that left a deep impression on me. After that we often met in the library, and slowly got to know each other."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你喜欢他，是因为这件事吗？", "p": ["nǐ", "xǐ", "huān", "tā", "", "shì", "yīn", "wèi", "zhè", "jiàn", "shì", "ma", ""], "vi": "Cậu thích anh ấy là vì chuyện đó sao?", "en": "Is that why you like him?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "不只是这样。他不仅能把很难的法律讲清楚，性格也很稳，跟他在一起我很放心。", "p": ["bù", "zhǐ", "shì", "zhè", "yàng", "", "tā", "bù", "jǐn", "néng", "bǎ", "hěn", "nán", "de", "fǎ", "lǜ", "jiǎng", "qīng", "chǔ", "", "xìng", "gé", "yě", "hěn", "wěn", "", "gēn", "tā", "zài", "yì", "qǐ", "wǒ", "hěn", "fàng", "xīn", ""], "vi": "Không chỉ vậy. Anh ấy không những giảng được luật khó một cách rõ ràng, tính cách cũng rất điềm tĩnh, ở bên anh ấy mình cảm thấy yên tâm.", "en": "It's not just that. He can not only explain difficult points of law clearly, he also has a steady character, and I feel at ease with him."}]}, {"n": 2, "zh": "对话：阿玲告诉小雪她准备结婚", "vi": "Hội thoại: A Linh nói với Tiểu Tuyết là mình định kết hôn", "en": "Dialogue: A Linh tells Xiaoxue she plans to get married", "kw": ["开玩笑", "从来", "最好", "共同", "适合", "幸福"], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "小雪，我想先告诉你一件事：我和周南准备今年冬天结婚。", "p": ["xiǎo", "xuě", "", "wǒ", "xiǎng", "xiān", "gào", "sù", "nǐ", "yí", "jiàn", "shì", "", "wǒ", "hé", "zhōu", "nán", "zhǔn", "bèi", "jīn", "nián", "dōng", "tiān", "jié", "hūn", ""], "vi": "Tiểu Tuyết, mình muốn nói trước với cậu một chuyện: mình và Châu Nam định kết hôn vào mùa đông năm nay.", "en": "Xiaoxue, I want to tell you something first: Zhou Nan and I are planning to get married this winter."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你别开玩笑了！才半年，就谈结婚？", "p": ["nǐ", "bié", "kāi", "wán", "xiào", "le", "", "cái", "bàn", "nián", "", "jiù", "tán", "jié", "hūn", ""], "vi": "Cậu đừng có nói đùa! Mới có nửa năm đã bàn đến chuyện kết hôn?", "en": "Don't joke around! You've only known each other half a year, and you're already talking about marriage?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我是认真的。认识的时间不长，可我从来没这么确定过。", "p": ["wǒ", "shì", "rèn", "zhēn", "de", "", "rèn", "shí", "de", "shí", "jiān", "bù", "cháng", "", "kě", "wǒ", "cóng", "lái", "méi", "zhè", "me", "què", "dìng", "guò", ""], "vi": "Mình nói nghiêm túc đó. Thời gian quen nhau chưa dài, nhưng mình chưa bao giờ chắc chắn như vậy.", "en": "I'm serious. We haven't known each other long, but I've never been this sure."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "要一起过一辈子，最好先看看有没有共同的习惯，不然以后会很累。", "p": ["yào", "yì", "qǐ", "guò", "yí", "bèi", "zi", "", "zuì", "hǎo", "xiān", "kàn", "kàn", "yǒu", "méi", "yǒu", "gòng", "tóng", "de", "xí", "guàn", "", "bù", "rán", "yǐ", "hòu", "huì", "hěn", "lèi", ""], "vi": "Muốn sống cùng nhau cả đời thì tốt nhất hãy xem đã có những thói quen chung chưa, nếu không sau này sẽ rất mệt.", "en": "If you want to spend a lifetime together, you'd better first see whether you share habits; otherwise it will be tiring later."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我们都喜欢一大早去湖边走路，也喜欢在旧书店里一站一下午。我觉得我们很适合对方。", "p": ["wǒ", "men", "dōu", "xǐ", "huān", "yí", "dà", "zǎo", "qù", "hú", "biān", "zǒu", "lù", "", "yě", "xǐ", "huān", "zài", "jiù", "shū", "diàn", "lǐ", "yí", "zhàn", "yí", "xià", "wǔ", "", "wǒ", "jué", "de", "wǒ", "men", "hěn", "shì", "hé", "duì", "fāng", ""], "vi": "Bọn mình đều thích sáng sớm ra hồ đi bộ, cũng thích đứng cả buổi chiều trong hiệu sách cũ. Mình thấy hai đứa rất hợp nhau.", "en": "We both like walking by the lake early in the morning, and we can stand in a second-hand bookshop all afternoon. I think we suit each other well."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "听你讲这些，我倒真替你高兴。希望你们一直这么幸福。", "p": ["tīng", "nǐ", "jiǎng", "zhè", "xiē", "", "wǒ", "dào", "zhēn", "tì", "nǐ", "gāo", "xìng", "", "xī", "wàng", "nǐ", "men", "yì", "zhí", "zhè", "me", "xìng", "fú", ""], "vi": "Nghe cậu kể vậy, mình đúng là mừng cho cậu. Mong hai người mãi hạnh phúc như vậy.", "en": "Hearing you say this, I'm genuinely happy for you. I hope you two stay this happy."}]}, {"n": 3, "zh": "对话：林阿姨和赵阿姨聊婚后的日子", "vi": "Hội thoại: Thím Lâm và thím Triệu nói về cuộc sống sau khi cưới", "en": "Dialogue: Aunt Lin and Aunt Zhao talk about married life", "kw": ["生活", "刚", "浪漫", "够", "缺点", "接受"], "lines": [{"s": "林阿姨", "sp": ["lín", "ā", "yí"], "t": "赵阿姨，听说您结婚快十五年了？", "p": ["zhào", "ā", "yí", "", "tīng", "shuō", "nín", "jié", "hūn", "kuài", "shí", "wǔ", "nián", "le", ""], "vi": "Thím Triệu, nghe nói thím kết hôn gần mười lăm năm rồi phải không?", "en": "Aunt Zhao, I heard you've been married for almost fifteen years?"}, {"s": "赵阿姨", "sp": ["zhào", "ā", "yí"], "t": "到春节就满十五年了。这些年生活不算热闹，可一直很踏实。", "p": ["dào", "chūn", "jié", "jiù", "mǎn", "shí", "wǔ", "nián", "le", "", "zhè", "xiē", "nián", "shēng", "huó", "bú", "suàn", "rè", "nào", "", "kě", "yì", "zhí", "hěn", "tā", "shi", ""], "vi": "Đến Tết là tròn mười lăm năm. Mấy năm nay cuộc sống không ồn ào, nhưng luôn rất vững vàng.", "en": "By Spring Festival it will be a full fifteen years. These years our life hasn't been lively, but it has always been steady."}, {"s": "林阿姨", "sp": ["lín", "ā", "yí"], "t": "我刚结婚那两年，周末总想换一条路走走，试试新的小馆。可最近工作一忙，回家只想休息，话也少了。", "p": ["wǒ", "gāng", "jié", "hūn", "nà", "liǎng", "nián", "", "zhōu", "mò", "zǒng", "xiǎng", "huàn", "yì", "tiáo", "lù", "zǒu", "zǒu", "", "shì", "shì", "xīn", "de", "xiǎo", "guǎn", "", "kě", "zuì", "jìn", "gōng", "zuò", "yì", "máng", "", "huí", "jiā", "zhǐ", "xiǎng", "xiū", "xī", "", "huà", "yě", "shǎo", "le", ""], "vi": "Hai năm mình vừa mới cưới, cuối tuần nào cũng muốn đổi đường đi dạo, thử quán nhỏ mới. Nhưng dạo này việc một bận, về nhà chỉ muốn nghỉ, nói chuyện cũng ít đi.", "en": "In the two years after I had just got married, at weekends I always wanted to try a new path for a walk, or a new little restaurant. But lately work has been busy, I only want to rest when I get home, and we talk less."}, {"s": "赵阿姨", "sp": ["zhào", "ā", "yí"], "t": "两个人过日子，不能只靠那一点浪漫，那是不够的。", "p": ["liǎng", "gè", "rén", "guò", "rì", "zi", "", "bù", "néng", "zhǐ", "kào", "nà", "yì", "diǎn", "làng", "màn", "", "nà", "shì", "bú", "gòu", "de", ""], "vi": "Hai người sống với nhau không thể chỉ dựa vào chút lãng mạn ấy, như thế là không đủ.", "en": "When two people share a life, you can't rely on that bit of romance alone — it isn't enough."}, {"s": "林阿姨", "sp": ["lín", "ā", "yí"], "t": "您说得对。我现在有时候会把他的缺点看得很重，然后自己也不痛快。", "p": ["nín", "shuō", "de", "duì", "", "wǒ", "xiàn", "zài", "yǒu", "shí", "hòu", "huì", "bǎ", "tā", "de", "quē", "diǎn", "kàn", "de", "hěn", "zhòng", "", "rán", "hòu", "zì", "jǐ", "yě", "bú", "tòng", "kuai", ""], "vi": "Thím nói đúng. Giờ đôi lúc mình nhìn khuyết điểm của anh ấy quá nặng, rồi bản thân cũng không vui.", "en": "You're right. Sometimes now I dwell on his shortcomings, and then I feel unhappy myself."}, {"s": "赵阿姨", "sp": ["zhào", "ā", "yí"], "t": "一起的时间长了，谁都会有让对方不舒服的地方。接受这些，把日子往平静里过，才会轻松一些。", "p": ["yì", "qǐ", "de", "shí", "jiān", "cháng", "le", "", "shéi", "dōu", "huì", "yǒu", "ràng", "duì", "fāng", "bù", "shū", "fú", "de", "dì", "fāng", "", "jiē", "shòu", "zhè", "xiē", "", "bǎ", "rì", "zi", "wǎng", "píng", "jìng", "lǐ", "guò", "", "cái", "huì", "qīng", "sōng", "yì", "xiē", ""], "vi": "Ở bên nhau lâu, ai cũng có chỗ làm đối phương không dễ chịu. Chấp nhận những điều đó, sống ngày tháng cho bình lặng, sẽ nhẹ nhàng hơn.", "en": "When you've been together a long time, everyone has something that makes the other uncomfortable. Accept that, and live the days more calmly, and it will feel easier."}]}, {"n": 4, "zh": "短文：生活里的小浪漫", "vi": "Đoạn văn: Chút lãng mạn trong đời thường", "en": "Passage: The small romances in everyday life", "kw": ["羡慕", "爱情", "星星", "即使", "加班", "亮", "感动"], "lines": [{"s": "", "sp": [], "t": "很多人羡慕电影里的爱情，总觉得那才够浪漫。可我现在慢慢发现，真正留下来的往往是很小的事。有一次停电，爸爸指着窗外的星星给弟弟讲故事；还有一天，我即使加班到很晚，回到家也还能看见桌上那碗热汤。最让我感动的，是父母晚饭后去散步，路灯已经亮了，他们还是走得很慢，像是要把一天里没说完的话，慢慢补回来。", "p": ["hěn", "duō", "rén", "xiàn", "mù", "diàn", "yǐng", "lǐ", "de", "ài", "qíng", "", "zǒng", "jué", "de", "nà", "cái", "gòu", "làng", "màn", "", "kě", "wǒ", "xiàn", "zài", "màn", "màn", "fā", "xiàn", "", "zhēn", "zhèng", "liú", "xià", "lái", "de", "wǎng", "wǎng", "shì", "hěn", "xiǎo", "de", "shì", "", "yǒu", "yí", "cì", "tíng", "diàn", "", "bà", "bà", "zhǐ", "zhe", "chuāng", "wài", "de", "xīng", "xīng", "gěi", "dì", "di", "jiǎng", "gù", "shì", "", "hái", "yǒu", "yì", "tiān", "", "wǒ", "jí", "shǐ", "jiā", "bān", "dào", "hěn", "wǎn", "", "huí", "dào", "jiā", "yě", "hái", "néng", "kàn", "jiàn", "zhuō", "shàng", "nà", "wǎn", "rè", "tāng", "", "zuì", "ràng", "wǒ", "gǎn", "dòng", "de", "", "shì", "fù", "mǔ", "wǎn", "fàn", "hòu", "qù", "sàn", "bù", "", "lù", "dēng", "yǐ", "jīng", "liàng", "le", "", "tā", "men", "hái", "shì", "zǒu", "de", "hěn", "màn", "", "xiàng", "shì", "yào", "bǎ", "yì", "tiān", "lǐ", "méi", "shuō", "wán", "de", "huà", "", "màn", "màn", "bǔ", "huí", "lái", ""], "vi": "Nhiều người ngưỡng mộ tình yêu trong phim, cứ nghĩ thế mới đủ lãng mạn. Nhưng giờ tôi dần nhận ra, những gì thật sự còn lại thường là chuyện rất nhỏ. Có lần mất điện, bố chỉ lên những ngôi sao ngoài cửa sổ kể chuyện cho em trai; còn có một ngày, dù tôi tăng ca đến rất muộn, về nhà vẫn thấy trên bàn bát canh nóng ấy. Điều khiến tôi cảm động nhất là bố mẹ đi dạo sau bữa tối, đèn đường đã sáng họ vẫn đi rất chậm, như muốn lấy lại những câu cả ngày chưa kịp nói.", "en": "Many people envy the love in films and always feel that is what counts as romance. But I have slowly come to see that what really lasts is often something very small. Once, during a power cut, Dad pointed at the stars outside the window and told my little brother a story; and one day, even though I worked late, I could still see that bowl of hot soup on the table when I got home. What moves me most is my parents' walk after dinner: the street lights are already on, yet they still walk very slowly, as if they want to slowly make up the words they had no time for during the day."}]}, {"n": 5, "zh": "短文：走进婚姻的理由", "vi": "Đoạn văn: Lý do bước vào hôn nhân", "en": "Passage: Reasons for walking into marriage", "kw": ["自然", "原因", "互相", "吸引", "幽默", "脾气"], "lines": [{"s": "", "sp": [], "t": "提起结婚，有人会想得很远，也有人觉得这件事很自然。在我看来，两个人走进婚姻，原因不只是喜欢，还要能在想法上互相吸引。我姐姐的丈夫是中学老师，上课很幽默，学生们都爱听。他脾气很软，家里意见不一样的时候，他总是先听完再慢慢说。看着他们，我才明白，这样的相处，比甜言蜜语更让人放心。", "p": ["tí", "qǐ", "jié", "hūn", "", "yǒu", "rén", "huì", "xiǎng", "de", "hěn", "yuǎn", "", "yě", "yǒu", "rén", "jué", "de", "zhè", "jiàn", "shì", "hěn", "zì", "rán", "", "zài", "wǒ", "kàn", "lái", "", "liǎng", "gè", "rén", "zǒu", "jìn", "hūn", "yīn", "", "yuán", "yīn", "bù", "zhǐ", "shì", "xǐ", "huān", "", "hái", "yào", "néng", "zài", "xiǎng", "fǎ", "shàng", "hù", "xiāng", "xī", "yǐn", "", "wǒ", "jiě", "jiě", "de", "zhàng", "fū", "shì", "zhōng", "xué", "lǎo", "shī", "", "shàng", "kè", "hěn", "yōu", "mò", "", "xué", "shēng", "men", "dōu", "ài", "tīng", "", "tā", "pí", "qì", "hěn", "ruǎn", "", "jiā", "lǐ", "yì", "jiàn", "bù", "yí", "yàng", "de", "shí", "hòu", "", "tā", "zǒng", "shì", "xiān", "tīng", "wán", "zài", "màn", "màn", "shuō", "", "kàn", "zhe", "tā", "men", "", "wǒ", "cái", "míng", "bái", "", "zhè", "yàng", "de", "xiāng", "chǔ", "", "bǐ", "tián", "yán", "mì", "yǔ", "gèng", "ràng", "rén", "fàng", "xīn", ""], "vi": "Nhắc đến kết hôn, có người nghĩ rất xa, cũng có người thấy việc ấy rất tự nhiên. Với tôi, hai người bước vào hôn nhân, lý do không chỉ là thích nhau, mà còn phải thu hút lẫn nhau về mặt suy nghĩ. Chồng chị gái tôi là giáo viên trung học, dạy học rất hài hước, học sinh nào cũng thích nghe. Tính khí anh ấy rất dịu, khi ở nhà có ý kiến khác nhau, anh ấy luôn nghe hết rồi mới nói chậm rãi. Nhìn họ, tôi mới hiểu, cách sống bên nhau như vậy khiến người ta yên tâm hơn những lời đường mật.", "en": "When people mention marriage, some think far ahead, while others feel it is a very natural step. To me, when two people enter marriage, the reason is not only that they like each other — they also need to attract each other in the way they think. My elder sister's husband is a secondary-school teacher. He is very humorous in class, and the students love listening to him. He has a gentle temper: when they disagree at home, he always listens to the end before speaking slowly. Watching them, I finally understand that this way of being together is more reassuring than sweet words."}]}]}, {"l": 2, "texts": [{"n": 1, "zh": "对话：阿玲和阮明聊刚到中国的日子", "vi": "Hội thoại: A Linh và Nguyễn Minh nói về những ngày mới đến Trung Quốc", "en": "Dialogue: A Linh and Nguyen Minh talk about his first days in China", "kw": ["适应", "逛", "交", "平时", "短信", "正好"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "阿玲，新来的同学阮明还习惯这儿吗？", "p": ["ā", "líng", "", "xīn", "lái", "de", "tóng", "xué", "ruǎn", "míng", "hái", "xí", "guàn", "zhè", "r", "ma", ""], "vi": "A Linh, bạn mới Nguyễn Minh đã quen ở đây chưa?", "en": "A Linh, has the new classmate Nguyen Minh got used to it here yet?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "他刚来的那两周，吃饭、坐车都不太适应。后来我带他去交了几个朋友，情况才好起来。", "p": ["tā", "gāng", "lái", "de", "nà", "liǎng", "zhōu", "", "chī", "fàn", "", "zuò", "chē", "dōu", "bú", "tài", "shì", "yìng", "", "hòu", "lái", "wǒ", "dài", "tā", "qù", "jiāo", "le", "jǐ", "gè", "péng", "you", "", "qíng", "kuàng", "cái", "hǎo", "qǐ", "lái", ""], "vi": "Hai tuần đầu anh ấy mới đến, ăn uống và đi xe đều không được thích nghi lắm. Sau đó mình đưa anh ấy đi kết thêm vài người bạn, mọi thứ mới khá hơn.", "en": "In the first two weeks after he arrived, meals and buses were hard to adapt to. Then I took him out to make a few friends, and things got better."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你们平时都做些什么？", "p": ["nǐ", "men", "píng", "shí", "dōu", "zuò", "xiē", "shén", "me", ""], "vi": "Bình thường các bạn làm gì?", "en": "What do you usually do?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "周末我们喜欢去逛附近的小市场，看看水果，听听大家说话。他有问题，也会给我发短信。", "p": ["zhōu", "mò", "wǒ", "men", "xǐ", "huān", "qù", "guàng", "fù", "jìn", "de", "xiǎo", "shì", "chǎng", "", "kàn", "kàn", "shuǐ", "guǒ", "", "tīng", "tīng", "dà", "jiā", "shuō", "huà", "", "tā", "yǒu", "wèn", "tí", "", "yě", "huì", "gěi", "wǒ", "fā", "duǎn", "xìn", ""], "vi": "Cuối tuần bọn mình thích đi dạo chợ nhỏ gần đó, xem trái cây, nghe mọi người nói chuyện. Có việc gì anh ấy cũng nhắn tin cho mình.", "en": "At weekends we like to stroll around the little market nearby, look at the fruit and listen to people talking. If he has a question, he also texts me."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "这个周六正好有个校园音乐会，要不要叫上他？", "p": ["zhè", "ge", "zhōu", "liù", "zhèng", "hǎo", "yǒu", "gè", "xiào", "yuán", "yīn", "yuè", "huì", "", "yào", "bú", "yào", "jiào", "shàng", "tā", ""], "vi": "Thứ bảy này đúng lúc có hòa nhạc trong trường, có gọi anh ấy không?", "en": "There's a campus concert this Saturday, as it happens — shall we ask him along?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "好啊。他正想多认识点儿人，去了一定高兴。", "p": ["hǎo", "a", "", "tā", "zhèng", "xiǎng", "duō", "rèn", "shí", "diǎn", "r", "rén", "", "qù", "le", "yí", "dìng", "gāo", "xìng", ""], "vi": "Được chứ. Anh ấy đang muốn quen thêm người, đi thì chắc vui.", "en": "Yes. He wants to meet more people, so he'll be glad to come."}]}, {"n": 2, "zh": "对话：小雪为同学聚会发愁", "vi": "Hội thoại: Tiểu Tuyết lo chuyện họp lớp", "en": "Dialogue: Xiaoxue worries about a class reunion", "kw": ["聚会", "毕业", "差不多", "联系", "专门", "麻烦"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "阿玲，下个月班里要办一场同学聚会，我有点儿发愁。", "p": ["ā", "líng", "", "xià", "gè", "yuè", "bān", "lǐ", "yào", "bàn", "yì", "cháng", "tóng", "xué", "jù", "huì", "", "wǒ", "yǒu", "diǎn", "r", "fā", "chóu", ""], "vi": "A Linh, tháng sau lớp mình tổ chức họp lớp, mình hơi lo.", "en": "A Linh, the class is holding a reunion next month, and I'm a bit worried."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "发愁什么？大家毕业才差不多一年，应该都还记得路吧？", "p": ["fā", "chóu", "shén", "me", "", "dà", "jiā", "bì", "yè", "cái", "chà", "bu", "duō", "yì", "nián", "", "yīng", "gāi", "dōu", "hái", "jì", "de", "lù", "ba", ""], "vi": "Lo gì? Mọi người tốt nghiệp mới được khoảng một năm, chắc vẫn nhớ đường chứ?", "en": "Why? It's only been about a year since everyone graduated — they should still remember the way, shouldn't they?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "问题是有几个人不太好联系。有的换了号码，我专门问了老师，还是没问到。", "p": ["wèn", "tí", "shì", "yǒu", "jǐ", "gè", "rén", "bú", "tài", "hǎo", "lián", "xì", "", "yǒu", "de", "huàn", "le", "hào", "mǎ", "", "wǒ", "zhuān", "mén", "wèn", "le", "lǎo", "shī", "", "hái", "shì", "méi", "wèn", "dào", ""], "vi": "Vấn đề là có vài người khá khó liên lạc. Có người đổi số, mình còn hỏi riêng giáo viên, vẫn chưa ra.", "en": "The problem is that a few people are hard to contact. Some have changed numbers. I even went out of my way to ask the teacher, and I still didn't get them."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "那就先请到的人来。你已经尽力了，别把这件事变成麻烦。", "p": ["nà", "jiù", "xiān", "qǐng", "dào", "de", "rén", "lái", "", "nǐ", "yǐ", "jīng", "jìn", "lì", "le", "", "bié", "bǎ", "zhè", "jiàn", "shì", "biàn", "chéng", "má", "fan", ""], "vi": "Vậy thì mời trước những người liên lạc được. Cậu đã cố rồi, đừng biến việc này thành chuyện phiền phức.", "en": "Then just invite the people you can reach first. You've already tried your best — don't turn it into a hassle."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "说得对。我今晚先把通知发给大家，地点还是那家常去的小馆。", "p": ["shuō", "de", "duì", "", "wǒ", "jīn", "wǎn", "xiān", "bǎ", "tōng", "zhī", "fā", "gěi", "dà", "jiā", "", "dì", "diǎn", "hái", "shì", "nà", "jiā", "cháng", "qù", "de", "xiǎo", "guǎn", ""], "vi": "Đúng đó. Tối nay mình gửi thông báo trước, địa điểm vẫn là quán nhỏ mọi người hay đến.", "en": "That's right. I'll send the notice out tonight. The place can still be that little restaurant we often go to."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "需要我帮忙联系谁，你就说一声。", "p": ["xū", "yào", "wǒ", "bāng", "máng", "lián", "xì", "shuí", "", "nǐ", "jiù", "shuō", "yì", "shēng", ""], "vi": "Cần mình giúp liên lạc ai thì cậu nói một tiếng.", "en": "If you need me to help contact anyone, just say."}]}, {"n": 3, "zh": "对话：阿玲和小雪翻看夏令营的照片", "vi": "Hội thoại: A Linh và Tiểu Tuyết xem ảnh trại hè", "en": "Dialogue: A Linh and Xiaoxue look through summer-camp photos", "kw": ["好像", "重新", "尽管", "真正", "友谊", "当"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你看这张，当我们在山里教孩子们写汉字的时候，你的帽子都歪了。", "p": ["nǐ", "kàn", "zhè", "zhāng", "", "dāng", "wǒ", "men", "zài", "shān", "lǐ", "jiào", "hái", "zi", "men", "xiě", "hàn", "zì", "de", "shí", "hòu", "", "nǐ", "de", "mào", "zi", "dōu", "wāi", "le", ""], "vi": "Cậu nhìn tấm này, khi chúng mình đang dạy bọn trẻ viết chữ Hán trên núi, mũ cậu còn lệch nữa.", "en": "Look at this one — when we were teaching the children to write characters in the mountains, your hat was even crooked."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "真的好像是昨天的事。我倒想重新再去一次，再听他们喊我们“老师”。", "p": ["zhēn", "de", "hǎo", "xiàng", "shì", "zuó", "tiān", "de", "shì", "", "wǒ", "dào", "xiǎng", "chóng", "xīn", "zài", "qù", "yí", "cì", "", "zài", "tīng", "tā", "men", "hǎn", "wǒ", "men", "", "lǎo", "shī", "", ""], "vi": "Thật giống như chuyện hôm qua. Mình lại muốn đi lại một lần nữa, nghe các em gọi mình bằng «cô giáo».", "en": "It really seems like yesterday. I'd love to go again, and hear them call us \"teacher\" once more."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "尽管现在各忙各的，我还是会想起那时大家一起做饭、一起笑的晚上。", "p": ["jǐn", "guǎn", "xiàn", "zài", "gè", "máng", "gè", "de", "", "wǒ", "hái", "shì", "huì", "xiǎng", "qǐ", "nà", "shí", "dà", "jiā", "yì", "qǐ", "zuò", "fàn", "", "yì", "qǐ", "xiào", "de", "wǎn", "shàng", ""], "vi": "Dù giờ ai cũng bận việc của mình, mình vẫn nhớ những tối cả nhóm cùng nấu ăn, cùng cười.", "en": "Even though we're each busy with our own things now, I still think of those evenings when we cooked and laughed together."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "所以我说，真正让人记得住的，不是风景，是那段友谊。", "p": ["suǒ", "yǐ", "wǒ", "shuō", "", "zhēn", "zhèng", "ràng", "rén", "jì", "de", "zhù", "de", "", "bú", "shì", "fēng", "jǐng", "", "shì", "nà", "duàn", "yǒu", "yì", ""], "vi": "Nên mình mới nói, điều thật sự khiến người ta nhớ không phải phong cảnh, mà là tình bạn ấy.", "en": "That's why I say what you really remember isn't the scenery, it's that friendship."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "明年要是再办这样的活动，咱们还去，当一回“大姐姐”。", "p": ["míng", "nián", "yào", "shi", "zài", "bàn", "zhè", "yàng", "de", "huó", "dòng", "", "zán", "men", "hái", "qù", "", "dāng", "yì", "huí", "", "dà", "jiě", "jiě", "", ""], "vi": "Năm sau nếu lại tổ chức hoạt động thế này, mình vẫn đi, làm một chuyến «chị lớn».", "en": "If they run something like this again next year, let's go and be \"big sisters\" once more."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "一言为定。到时候我把这些照片再翻出来给大家看。", "p": ["yī", "yán", "wéi", "dìng", "", "dào", "shí", "hòu", "wǒ", "bǎ", "zhè", "xiē", "zhào", "piān", "zài", "fān", "chū", "lái", "gěi", "dà", "jiā", "kàn", ""], "vi": "Được, nói trước đã. Lúc ấy mình sẽ lại lấy mấy tấm ảnh này ra cho mọi người xem.", "en": "It's a deal. When the time comes, I'll bring these photos out again to show everyone."}]}, {"n": 4, "zh": "短文：宿舍里的那一小时", "vi": "Đoạn văn: Một giờ trong ký túc xá", "en": "Passage: That one hour in the dorm", "kw": ["周围", "交", "丰富", "交流", "讨厌", "无聊", "却"], "lines": [{"s": "", "sp": [], "t": "我刚住进宿舍的时候，周围很安静，晚上只听得见楼下的车。那时我觉得日子有点儿无聊，也讨厌一个人吃饭。后来慢慢交了几个朋友，晚饭后大家坐在走廊里交流家乡的小吃和上课的笑话，晚上忽然变得丰富起来。可我却还给自己留出一小时：关上门，写写日记，听听自己喜欢的歌。有朋友在身边很好，有一段属于自己的时间，也同样重要。", "p": ["wǒ", "gāng", "zhù", "jìn", "sù", "shè", "de", "shí", "hòu", "", "zhōu", "wéi", "hěn", "ān", "jìng", "", "wǎn", "shàng", "zhǐ", "tīng", "de", "jiàn", "lóu", "xià", "de", "chē", "", "nà", "shí", "wǒ", "jué", "de", "rì", "zi", "yǒu", "diǎn", "r", "wú", "liáo", "", "yě", "tǎo", "yàn", "yí", "gè", "rén", "chī", "fàn", "", "hòu", "lái", "màn", "màn", "jiāo", "le", "jǐ", "gè", "péng", "you", "", "wǎn", "fàn", "hòu", "dà", "jiā", "zuò", "zài", "zǒu", "láng", "lǐ", "jiāo", "liú", "jiā", "xiāng", "de", "xiǎo", "chī", "hé", "shàng", "kè", "de", "xiào", "huà", "", "wǎn", "shàng", "hū", "rán", "biàn", "de", "fēng", "fù", "qǐ", "lái", "", "kě", "wǒ", "què", "huán", "gěi", "zì", "jǐ", "liú", "chū", "yì", "xiǎo", "shí", "", "guān", "shàng", "mén", "", "xiě", "xiě", "rì", "jì", "", "tīng", "tīng", "zì", "jǐ", "xǐ", "huān", "de", "gē", "", "yǒu", "péng", "you", "zài", "shēn", "biān", "hěn", "hǎo", "", "yǒu", "yí", "duàn", "shǔ", "yú", "zì", "jǐ", "de", "shí", "jiān", "", "yě", "tóng", "yàng", "zhòng", "yào", ""], "vi": "Lúc mới ở ký túc xá, xung quanh rất yên, tối chỉ nghe tiếng xe dưới phố. Khi ấy tôi thấy ngày tháng hơi buồn chán, cũng ghét phải ăn một mình. Sau dần kết được vài người bạn, sau bữa tối cả nhóm ngồi ở hành lang trao đổi về món quê và chuyện vui trên lớp, buổi tối bỗng trở nên phong phú. Thế nhưng tôi vẫn để dành cho mình một giờ: đóng cửa, viết nhật ký, nghe bài mình thích. Có bạn bên cạnh thì tốt, có một khoảng thời gian thuộc về mình cũng quan trọng không kém.", "en": "When I first moved into the dorm, it was very quiet around me; at night I could only hear the cars downstairs. In those days I found life a bit dull, and I also hated eating alone. Later I slowly made a few friends. After dinner we would sit in the corridor and talk about hometown snacks and jokes from class, and the evenings suddenly became rich. And yet I still keep one hour for myself: I close the door, write in my diary, and listen to a song I like. It is good to have friends nearby, and a stretch of time that belongs only to you is just as important."}]}, {"n": 5, "zh": "短文：朋友不是只会说好话的人", "vi": "Đoạn văn: Bạn không phải chỉ biết nói lời hay", "en": "Passage: A friend is not only someone who says nice things", "kw": ["镜子", "理解", "困难", "及时", "陪", "而", "真正"], "lines": [{"s": "", "sp": [], "t": "有人把朋友比作镜子，觉得镜子里只会看见自己最好看的样子。可我想，真正的朋友更像一扇窗。当你遇到困难，他能理解你为什么走不动，也会及时过来敲敲门，陪你把心里的话说完。他高兴时会和你一起笑，而在你不想说话的时候，也愿意安静地坐在旁边。这样的人不必很多，但有一个，就够让人觉得自己不是一个人。", "p": ["yǒu", "rén", "bǎ", "péng", "you", "bǐ", "zuò", "jìng", "zi", "", "jué", "de", "jìng", "zi", "lǐ", "zhǐ", "huì", "kàn", "jiàn", "zì", "jǐ", "zuì", "hǎo", "kàn", "de", "yàng", "zi", "", "kě", "wǒ", "xiǎng", "", "zhēn", "zhèng", "de", "péng", "you", "gèng", "xiàng", "yí", "shàn", "chuāng", "", "dāng", "nǐ", "yù", "dào", "kùn", "nan", "", "tā", "néng", "lǐ", "jiě", "nǐ", "wèi", "shén", "me", "zǒu", "bú", "dòng", "", "yě", "huì", "jí", "shí", "guò", "lái", "qiāo", "qiāo", "mén", "", "péi", "nǐ", "bǎ", "xīn", "lǐ", "de", "huà", "shuō", "wán", "", "tā", "gāo", "xìng", "shí", "huì", "hé", "nǐ", "yì", "qǐ", "xiào", "", "ér", "zài", "nǐ", "bù", "xiǎng", "shuō", "huà", "de", "shí", "hòu", "", "yě", "yuàn", "yì", "ān", "jìng", "dì", "zuò", "zài", "páng", "biān", "", "zhè", "yàng", "de", "rén", "bú", "bì", "hěn", "duō", "", "dàn", "yǒu", "yí", "gè", "", "jiù", "gòu", "ràng", "rén", "jué", "de", "zì", "jǐ", "bú", "shì", "yí", "gè", "rén", ""], "vi": "Có người ví bạn bè như tấm gương, cho rằng trong gương chỉ thấy mình ở kiểu đẹp nhất. Nhưng tôi nghĩ, người bạn thật sự hơn giống một ô cửa sổ. Khi bạn gặp khó khăn, người ấy hiểu vì sao bạn bước không nổi, cũng kịp thời đến gõ cửa, ở bên để bạn nói hết những điều trong lòng. Lúc vui họ cười cùng bạn, còn khi bạn không muốn nói, họ cũng sẵn sàng ngồi yên cạnh đó. Người như vậy không cần nhiều, nhưng có một người thôi, cũng đủ để thấy mình không cô độc.", "en": "Some people compare a friend to a mirror, and feel that a mirror only shows you at your best. But I think a true friend is more like a window. When you run into difficulties, they can understand why you can't go on, and they will also come and knock in time, and sit with you until you've said what's on your mind. They will laugh with you when they're happy, and when you don't feel like talking, they are also willing to sit quietly beside you. You don't need many people like that, but even one is enough to make you feel you are not alone."}]}]}, {"l": 3, "texts": [{"n": 1, "zh": "对话：阿玲面试前有点儿紧张", "vi": "Hội thoại: A Linh hơi hồi hộp trước buổi phỏng vấn", "en": "Dialogue: A Linh is a little nervous before her interview", "kw": ["紧张", "能力", "提供", "信心", "招聘", "挺"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "明天那家语言中心招聘辅导老师，你还去吗？", "p": ["míng", "tiān", "nà", "jiā", "yǔ", "yán", "zhōng", "xīn", "zhāo", "pìn", "fǔ", "dǎo", "lǎo", "shī", "", "nǐ", "hái", "qù", "ma", ""], "vi": "Ngày mai trung tâm ngôn ngữ ấy tuyển giáo viên kèm, cậu vẫn đi chứ?", "en": "That language centre is recruiting tutors tomorrow — are you still going?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "去。可我一想到要开口介绍自己，就有点儿紧张。", "p": ["qù", "", "kě", "wǒ", "yì", "xiǎng", "dào", "yào", "kāi", "kǒu", "jiè", "shào", "zì", "jǐ", "", "jiù", "yǒu", "diǎn", "r", "jǐn", "zhāng", ""], "vi": "Đi chứ. Nhưng nghĩ đến lúc phải mở miệng giới thiệu mình là mình hơi hồi hộp.", "en": "Yes. But as soon as I think about having to introduce myself, I get a little nervous."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "他们要看的是你的能力，不是你讲得漂不漂亮。你带学生复习，一向很清楚。", "p": ["tā", "men", "yào", "kàn", "de", "shì", "nǐ", "de", "néng", "lì", "", "bú", "shì", "nǐ", "jiǎng", "de", "piāo", "bú", "piào", "liàng", "", "nǐ", "dài", "xué", "shēng", "fù", "xí", "", "yí", "xiàng", "hěn", "qīng", "chǔ", ""], "vi": "Họ nhìn năng lực của cậu, không phải nói hay hay không. Cậu kèm các bạn ôn bài vốn rất rõ ràng.", "en": "They'll be looking at your ability, not at how pretty your speech is. You're always very clear when you review with students."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "通知上说，他们会提供一周的培训。有培训，我心里才有信心一点儿。", "p": ["tōng", "zhī", "shàng", "shuō", "", "tā", "men", "huì", "tí", "gōng", "yì", "zhōu", "de", "péi", "xùn", "", "yǒu", "péi", "xùn", "", "wǒ", "xīn", "lǐ", "cái", "yǒu", "xìn", "xīn", "yì", "diǎn", "r", ""], "vi": "Trong giấy báo nói họ sẽ cung cấp một tuần tập huấn. Có tập huấn, mình mới có chút tự tin.", "en": "The notice said they would provide a week of training. With that, I feel a bit more confident."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "那就好好睡一觉。我看你挺适合这份工作的。", "p": ["nà", "jiù", "hǎo", "hǎo", "shuì", "yí", "jiào", "", "wǒ", "kàn", "nǐ", "tǐng", "shì", "hé", "zhè", "fèn", "gōng", "zuò", "de", ""], "vi": "Vậy thì ngủ một giấc cho ngon. Mình thấy cậu khá hợp với việc này.", "en": "Then get a good night's sleep. I think you're quite right for this job."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "好。明天我一出来，就给你发消息。", "p": ["hǎo", "", "míng", "tiān", "wǒ", "yì", "chū", "lái", "", "jiù", "gěi", "nǐ", "fā", "xiāo", "xi", ""], "vi": "Được. Ngày mai ra xong mình nhắn ngay cho cậu.", "en": "All right. I'll message you as soon as I come out tomorrow."}]}, {"n": 2, "zh": "对话：周姐和阿玲谈两份应聘材料", "vi": "Hội thoại: Chị Châu và A Linh bàn hai hồ sơ ứng tuyển", "en": "Dialogue: Sister Zhou and A Linh discuss two applications", "kw": ["本来", "材料", "符合", "负责", "通知", "应聘"], "lines": [{"s": "周姐", "sp": ["zhōu", "jiě"], "t": "阿玲，你帮我看看这两份应聘材料。前台这份工作，本来我们想找有经验的人。", "p": ["ā", "líng", "", "nǐ", "bāng", "wǒ", "kàn", "kàn", "zhè", "liǎng", "fèn", "yìng", "pìn", "cái", "liào", "", "qián", "tái", "zhè", "fèn", "gōng", "zuò", "", "běn", "lái", "wǒ", "men", "xiǎng", "zhǎo", "yǒu", "jīng", "yàn", "de", "rén", ""], "vi": "A Linh, em xem giúp chị hai hồ sơ ứng tuyển này. Việc lễ tân này, vốn dĩ chị muốn tìm người có kinh nghiệm.", "en": "A Linh, help me look at these two job applications. For this front-desk job, we originally wanted someone with experience."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "这份更符合要求：字写得清楚，也写过类似的工作。那一份经验少一些。", "p": ["zhè", "fèn", "gèng", "fú", "hé", "yāo", "qiú", "", "zì", "xiě", "de", "qīng", "chǔ", "", "yě", "xiě", "guò", "lèi", "sì", "de", "gōng", "zuò", "", "nà", "yí", "fèn", "jīng", "yàn", "shǎo", "yì", "xiē", ""], "vi": "Hồ sơ này hợp yêu cầu hơn: chữ viết rõ, cũng từng làm việc tương tự. Hồ sơ kia ít kinh nghiệm hơn.", "en": "This one fits the requirements better: the writing is clear, and they've done similar work. The other one has a little less experience."}, {"s": "周姐", "sp": ["zhōu", "jiě"], "t": "那我先通知第一位下周三来见面。来了以后，前台就由她负责试做一天。", "p": ["nà", "wǒ", "xiān", "tōng", "zhī", "dì", "yī", "wèi", "xià", "zhōu", "sān", "lái", "jiàn", "miàn", "", "lái", "le", "yǐ", "hòu", "", "qián", "tái", "jiù", "yóu", "tā", "fù", "zé", "shì", "zuò", "yì", "tiān", ""], "vi": "Vậy chị báo trước cho người thứ nhất thứ tư tuần sau đến gặp. Đến rồi thì để bạn ấy phụ trách lễ tân thử một ngày.", "en": "Then I'll notify the first person to come in next Wednesday. Once they're here, they can be responsible for the front desk on a one-day trial."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "要是她那天来不了呢？", "p": ["yào", "shi", "tā", "nà", "tiān", "lái", "bù", "liǎo", "ne", ""], "vi": "Nếu hôm đó bạn ấy không đến được thì sao?", "en": "What if she can't come that day?"}, {"s": "周姐", "sp": ["zhōu", "jiě"], "t": "再联系第二位。招聘不宜拖太久，咱们尽快定下来。", "p": ["zài", "lián", "xì", "dì", "èr", "wèi", "", "zhāo", "pìn", "bù", "yí", "tuō", "tài", "jiǔ", "", "zán", "men", "jǐn", "kuài", "dìng", "xià", "lái", ""], "vi": "Thì liên lạc người thứ hai. Việc tuyển dụng không nên kéo dài, mình quyết sớm thôi.", "en": "Then we'll contact the second one. We shouldn't let the hiring drag on — let's decide as soon as we can."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "好，我把时间记在本子上。", "p": ["hǎo", "", "wǒ", "bǎ", "shí", "jiān", "jì", "zài", "běn", "zi", "shàng", ""], "vi": "Được, em ghi thời gian vào sổ.", "en": "All right, I'll write the time down in the notebook."}]}, {"n": 3, "zh": "对话：陈晓跟阿玲说她的新工作", "vi": "Hội thoại: Trần Hiểu kể với A Linh về việc mới", "en": "Dialogue: Chen Xiao tells A Linh about her new job", "kw": ["安排", "另外", "律师", "收入", "咱们", "专业"], "lines": [{"s": "陈晓", "sp": ["chén", "xiǎo"], "t": "阿玲，我找到工作了，在一家律师事务所做助理。", "p": ["ā", "líng", "", "wǒ", "zhǎo", "dào", "gōng", "zuò", "le", "", "zài", "yì", "jiā", "lǜ", "shī", "shì", "wù", "suǒ", "zuò", "zhù", "lǐ", ""], "vi": "A Linh, mình tìm được việc rồi, làm trợ lý ở một văn phòng luật sư.", "en": "A Linh, I've found a job — as an assistant at a law firm."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "真好！你的专业就是法律，这不是正好用上了吗？", "p": ["zhēn", "hǎo", "", "nǐ", "de", "zhuān", "yè", "jiù", "shì", "fǎ", "lǜ", "", "zhè", "bú", "shì", "zhèng", "hǎo", "yòng", "shàng", "le", "ma", ""], "vi": "Hay quá! Chuyên ngành cậu là luật, thế thì chẳng đúng lúc dùng được sao?", "en": "That's wonderful! Your major is law — isn't that just the right use for it?"}, {"s": "陈晓", "sp": ["chén", "xiǎo"], "t": "对。收入不算特别高，可每个月都很稳定。另外，晚上还能继续上课。", "p": ["duì", "", "shōu", "rù", "bú", "suàn", "tè", "bié", "gāo", "", "kě", "měi", "gè", "yuè", "dōu", "hěn", "wěn", "dìng", "", "lìng", "wài", "", "wǎn", "shàng", "hái", "néng", "jì", "xù", "shàng", "kè", ""], "vi": "Đúng. Thu nhập không đặc biệt cao, nhưng tháng nào cũng ổn định. Ngoài ra, tối vẫn học tiếp được.", "en": "Yes. The income isn't especially high, but it's steady every month. Besides that, I can still go to class in the evenings."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "那时间够用吗？咱们以前晚上常一起去图书馆。", "p": ["nà", "shí", "jiān", "gòu", "yòng", "ma", "", "zán", "men", "yǐ", "qián", "wǎn", "shàng", "cháng", "yì", "qǐ", "qù", "tú", "shū", "guǎn", ""], "vi": "Vậy thời gian có đủ không? Trước giờ tối nào mình cũng hay cùng đi thư viện.", "en": "Will you have enough time? We used to go to the library together in the evenings."}, {"s": "陈晓", "sp": ["chén", "xiǎo"], "t": "我自己先把一周的安排写好。忙的那几天，可能只能周末再见了。", "p": ["wǒ", "zì", "jǐ", "xiān", "bǎ", "yì", "zhōu", "de", "ān", "pái", "xiě", "hǎo", "", "máng", "de", "nà", "jǐ", "tiān", "", "kě", "néng", "zhǐ", "néng", "zhōu", "mò", "zài", "jiàn", "le", ""], "vi": "Mình sẽ viết sẵn lịch một tuần. Những ngày bận, có lẽ chỉ cuối tuần mới gặp được.", "en": "I'll write out the week's schedule first. On the busy days, we may only be able to meet at the weekend."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "没关系。你先安顿好，我为你高兴。", "p": ["méi", "guān", "xì", "", "nǐ", "xiān", "ān", "dùn", "hǎo", "", "wǒ", "wèi", "nǐ", "gāo", "xìng", ""], "vi": "Không sao. Cậu an vị đã, mình mừng cho cậu.", "en": "That's all right. Get yourself settled first — I'm happy for you."}]}, {"n": 4, "zh": "短文：面试时我想着的两件事", "vi": "Đoạn văn: Hai điều tôi nhớ khi phỏng vấn", "en": "Passage: Two things I keep in mind in an interview", "kw": ["首先", "其次", "诚实", "正式", "留"], "lines": [{"s": "", "sp": [], "t": "第一次去参加正式面试的时候，我在门口站了很久。后来我只记住两件事。首先，要诚实：不会的不要装会，被问到也可以说“我想再学”。其次，要认真听完再回答，不要抢话。衣服不必很贵，但要干净、整齐。走出门的时候我还是有些不好意思，可我希望自己至少留下了一个清楚、认真的印象。", "p": ["dì", "yī", "cì", "qù", "cān", "jiā", "zhèng", "shì", "miàn", "shì", "de", "shí", "hòu", "", "wǒ", "zài", "mén", "kǒu", "zhàn", "le", "hěn", "jiǔ", "", "hòu", "lái", "wǒ", "zhǐ", "jì", "zhù", "liǎng", "jiàn", "shì", "", "shǒu", "xiān", "", "yào", "chéng", "shí", "", "bú", "huì", "de", "bú", "yào", "zhuāng", "huì", "", "bèi", "wèn", "dào", "yě", "kě", "yǐ", "shuō", "", "wǒ", "xiǎng", "zài", "xué", "", "", "qí", "cì", "", "yào", "rèn", "zhēn", "tīng", "wán", "zài", "huí", "dá", "", "bú", "yào", "qiǎng", "huà", "", "yī", "fú", "bú", "bì", "hěn", "guì", "", "dàn", "yào", "gān", "jìng", "", "zhěng", "qí", "", "zǒu", "chū", "mén", "de", "shí", "hòu", "wǒ", "hái", "shì", "yǒu", "xiē", "bù", "hǎo", "yì", "sī", "", "kě", "wǒ", "xī", "wàng", "zì", "jǐ", "zhì", "shǎo", "liú", "xià", "le", "yí", "gè", "qīng", "chǔ", "", "rèn", "zhēn", "de", "yìn", "xiàng", ""], "vi": "Lần đầu đi phỏng vấn chính thức, tôi đứng mãi ở cửa. Sau đó tôi chỉ nhớ hai điều. Trước hết, phải thành thật: không biết thì đừng giả vờ biết, bị hỏi cũng có thể nói «tôi muốn học thêm». Thứ hai, phải nghe hết rồi mới trả lời, đừng cướp lời. Áo quần không cần đắt, nhưng phải sạch và gọn. Lúc bước ra tôi vẫn hơi ngại, nhưng mong ít nhất mình đã để lại một ấn tượng rõ ràng, nghiêm túc.", "en": "The first time I went to a formal interview, I stood at the door for a long time. After that I only kept two things in mind. First, be honest: if you can't do something, don't pretend you can, and if you're asked, you can also say \"I'd like to learn more.\" Second, listen to the end before you answer, and don't interrupt. Your clothes don't have to be expensive, but they should be clean and tidy. I was still a little embarrassed when I walked out, but I hoped I had at least left a clear, careful impression."}]}, {"n": 5, "zh": "短文：把约定的时间放在心里", "vi": "Đoạn văn: Để thời gian đã hẹn trong lòng", "en": "Passage: Keep the appointed time in mind", "kw": ["不管", "改变", "感觉", "顾客", "判断", "约会", "准时", "与"], "lines": [{"s": "", "sp": [], "t": "我在一家小咖啡馆打工。每天要与顾客说话，先判断他们是想坐一下，还是打包就走，再按他们的需要去做。不管店里有多忙，我都提醒自己不要改变脸上的态度。有一次，一位老师与我约好下午三点来取蛋糕，那是我们的一次约会。我提前做好，准时放到柜台上。她进门时笑着说：“我就知道你们不会让人白等。”那句话让我感觉，准时其实是一种尊重。", "p": ["wǒ", "zài", "yì", "jiā", "xiǎo", "kā", "fēi", "guǎn", "dǎ", "gōng", "", "měi", "tiān", "yào", "yǔ", "gù", "kè", "shuō", "huà", "", "xiān", "pàn", "duàn", "tā", "men", "shì", "xiǎng", "zuò", "yí", "xià", "", "hái", "shì", "dǎ", "bāo", "jiù", "zǒu", "", "zài", "àn", "tā", "men", "de", "xū", "yào", "qù", "zuò", "", "bù", "guǎn", "diàn", "lǐ", "yǒu", "duō", "máng", "", "wǒ", "dōu", "tí", "xǐng", "zì", "jǐ", "bú", "yào", "gǎi", "biàn", "liǎn", "shàng", "de", "tài", "dù", "", "yǒu", "yí", "cì", "", "yí", "wèi", "lǎo", "shī", "yǔ", "wǒ", "yuē", "hǎo", "xià", "wǔ", "sān", "diǎn", "lái", "qǔ", "dàn", "gāo", "", "nà", "shì", "wǒ", "men", "de", "yí", "cì", "yuē", "huì", "", "wǒ", "tí", "qián", "zuò", "hǎo", "", "zhǔn", "shí", "fàng", "dào", "guì", "tái", "shàng", "", "tā", "jìn", "mén", "shí", "xiào", "zhe", "shuō", "", "", "wǒ", "jiù", "zhī", "dào", "nǐ", "men", "bú", "huì", "ràng", "rén", "bái", "děng", "", "", "nà", "jù", "huà", "ràng", "wǒ", "gǎn", "jué", "", "zhǔn", "shí", "qí", "shí", "shì", "yì", "zhǒng", "zūn", "zhòng", ""], "vi": "Tôi làm thêm ở một quán cà phê nhỏ. Mỗi ngày phải nói chuyện với khách, trước hết phán đoán họ muốn ngồi một chút hay lấy mang về, rồi làm theo nhu cầu của họ. Dù trong quán bận đến mấy, tôi cũng nhắc mình đừng đổi thái độ trên mặt. Có lần một cô giáo hẹn với tôi chiều ba giờ đến lấy bánh, đó là một cuộc hẹn của chúng tôi. Tôi làm sẵn, đúng giờ đặt lên quầy. Cô bước vào, cười nói: «Tôi biết các bạn sẽ không để người ta đợi phí.» Câu ấy khiến tôi cảm thấy, đúng giờ thật ra là một cách tôn trọng.", "en": "I work part-time in a little café. Every day I have to talk with the customers, first judge whether they want to sit for a moment or take their order away, and then do what they need. No matter how busy the shop is, I remind myself not to change the look on my face. Once a teacher arranged with me to pick up a cake at three in the afternoon — that was an appointment we had. I had it ready and put it on the counter on time. When she came in she smiled and said, \"I knew you wouldn't leave anyone waiting for nothing.\" That sentence made me feel that being on time is really a kind of respect."}]}]}, {"l": 4, "texts": [{"n": 1, "zh": "对话：小雪又想换工作", "vi": "Hội thoại: Tiểu Tuyết lại muốn đổi việc", "en": "Dialogue: Xiaoxue wants to change jobs again", "kw": ["完全", "以为", "份", "提", "赚"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "阿玲，我又想提换工作的事了。这份工作做了半年，我以为能学到很多，结果每天都差不多。", "p": ["ā", "líng", "", "wǒ", "yòu", "xiǎng", "tí", "huàn", "gōng", "zuò", "de", "shì", "le", "", "zhè", "fèn", "gōng", "zuò", "zuò", "le", "bàn", "nián", "", "wǒ", "yǐ", "wéi", "néng", "xué", "dào", "hěn", "duō", "", "jié", "guǒ", "měi", "tiān", "dōu", "chà", "bu", "duō", ""], "vi": "A Linh, mình lại muốn nêu chuyện đổi việc. Việc này làm đã nửa năm, mình tưởng học được nhiều, hóa ra ngày nào cũng gần như nhau.", "en": "A Linh, I want to bring up changing jobs again. I've done this job for half a year. I thought I would learn a lot, but every day is more or less the same."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "你不是才涨了一点儿工资吗？别完全否定它。", "p": ["nǐ", "bú", "shì", "cái", "zhǎng", "le", "yì", "diǎn", "r", "gōng", "zī", "ma", "", "bié", "wán", "quán", "fǒu", "dìng", "tā", ""], "vi": "Chẳng phải cậu vừa được tăng một chút lương sao? Đừng phủ nhận hoàn toàn.", "en": "Didn't you just get a small raise? Don't dismiss it completely."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "涨是涨了，可我看同学做别的，好像赚得更多。", "p": ["zhǎng", "shì", "zhǎng", "le", "", "kě", "wǒ", "kàn", "tóng", "xué", "zuò", "bié", "de", "", "hǎo", "xiàng", "zhuàn", "de", "gèng", "duō", ""], "vi": "Tăng thì có tăng, nhưng mình thấy bạn cùng lớp làm việc khác, hình như kiếm được nhiều hơn.", "en": "The raise happened, yes, but I see classmates in other jobs who seem to earn more."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "赚钱很重要，可一份工作好不好，不能只看这个月的数字。", "p": ["zhuàn", "qián", "hěn", "zhòng", "yào", "", "kě", "yí", "fèn", "gōng", "zuò", "hǎo", "bù", "hǎo", "", "bù", "néng", "zhǐ", "kàn", "zhè", "ge", "yuè", "de", "shù", "zì", ""], "vi": "Kiếm tiền thì quan trọng, nhưng một công việc có tốt hay không không thể chỉ nhìn con số tháng này.", "en": "Earning money is important, but whether a job is good or not can't be judged only by this month's number."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "那你说我该等等？", "p": ["nà", "nǐ", "shuō", "wǒ", "gāi", "děng", "děng", ""], "vi": "Vậy cậu bảo mình nên đợi thêm?", "en": "So you think I should wait a little longer?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "先把现在手边的事做好。真要走，也先想清楚下一份是什么，再提离开。", "p": ["xiān", "bǎ", "xiàn", "zài", "shǒu", "biān", "de", "shì", "zuò", "hǎo", "", "zhēn", "yào", "zǒu", "", "yě", "xiān", "xiǎng", "qīng", "chǔ", "xià", "yí", "fèn", "shì", "shén", "me", "", "zài", "tí", "lí", "kāi", ""], "vi": "Hãy làm tốt việc đang có đã. Thật sự muốn đi, cũng nghĩ rõ việc tiếp theo là gì rồi hãy nói đến chuyện rời đi.", "en": "Do the work in front of you well first. If you really want to leave, think clearly about what the next job is before you bring up going."}]}, {"n": 2, "zh": "对话：林主管请小雪把调查提前做完", "vi": "Hội thoại: Chủ quản Lâm nhờ Tiểu Tuyết hoàn thành khảo sát sớm", "en": "Dialogue: Supervisor Lin asks Xiaoxue to finish a survey early", "kw": ["保证", "调查", "计划", "提前", "提醒", "原来", "乱"], "lines": [{"s": "林主管", "sp": ["lín", "zhǔ", "guǎn"], "t": "小雪，上周那份调查，计划是这周五交。现在要提前到周三，你能保证完成吗？", "p": ["xiǎo", "xuě", "", "shàng", "zhōu", "nà", "fèn", "diào", "chá", "", "jì", "huà", "shì", "zhè", "zhōu", "wǔ", "jiāo", "", "xiàn", "zài", "yào", "tí", "qián", "dào", "zhōu", "sān", "", "nǐ", "néng", "bǎo", "zhèng", "wán", "chéng", "ma", ""], "vi": "Tiểu Tuyết, bản khảo sát tuần trước, kế hoạch là nộp thứ sáu này. Giờ phải làm sớm hơn vào thứ tư, em bảo đảm hoàn thành được không?", "en": "Xiaoxue, for that survey from last week, the plan was to hand it in this Friday. Now it has to be earlier, by Wednesday — can you guarantee you'll finish it?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "周三……时间是紧了些。我先把这几天的安排重新看一遍，免得改乱了。", "p": ["zhōu", "sān", "", "", "shí", "jiān", "shì", "jǐn", "le", "xiē", "", "wǒ", "xiān", "bǎ", "zhè", "jǐ", "tiān", "de", "ān", "pái", "chóng", "xīn", "kàn", "yí", "biàn", "", "miǎn", "de", "gǎi", "luàn", "le", ""], "vi": "Thứ tư… thời gian hơi căng. Em xem lại lịch mấy ngày này đã, để khỏi sửa cho rối.", "en": "Wednesday… that's a bit tight. I'll go through these days' schedule again first, so it doesn't get into a mess."}, {"s": "林主管", "sp": ["lín", "zhǔ", "guǎn"], "t": "原来截止日期改了，是因为后面还有一场会。我明天再提醒你一次。", "p": ["yuán", "lái", "jié", "zhǐ", "rì", "qī", "gǎi", "le", "", "shì", "yīn", "wèi", "hòu", "miàn", "hái", "yǒu", "yì", "cháng", "huì", "", "wǒ", "míng", "tiān", "zài", "tí", "xǐng", "nǐ", "yí", "cì", ""], "vi": "Hóa ra hạn chót đổi vì phía sau còn một cuộc họp. Ngày mai chị nhắc em thêm lần nữa.", "en": "It turns out the deadline was changed because there's a meeting after that. I'll remind you again tomorrow."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "好。今晚我先做完前半部分，明天一早就把后半部分接着做。", "p": ["hǎo", "", "jīn", "wǎn", "wǒ", "xiān", "zuò", "wán", "qián", "bàn", "bù", "fèn", "", "míng", "tiān", "yì", "zǎo", "jiù", "bǎ", "hòu", "bàn", "bù", "fèn", "jiē", "zhe", "zuò", ""], "vi": "Được. Tối nay em làm xong nửa đầu, sáng mai làm tiếp nửa sau.", "en": "All right. I'll finish the first half tonight, and carry on with the second half first thing tomorrow."}, {"s": "林主管", "sp": ["lín", "zhǔ", "guǎn"], "t": "有困难早点说，不要拖到最后。", "p": ["yǒu", "kùn", "nan", "zǎo", "diǎn", "shuō", "", "bú", "yào", "tuō", "dào", "zuì", "hòu", ""], "vi": "Có khó thì nói sớm, đừng để đến phút cuối.", "en": "If there's a difficulty, say so early — don't leave it until the last minute."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "知道了。我尽量在周二晚上给您。", "p": ["zhī", "dào", "le", "", "wǒ", "jǐn", "liàng", "zài", "zhōu", "èr", "wǎn", "shàng", "gěi", "nín", ""], "vi": "Em biết rồi. Em cố đưa chị vào tối thứ ba.", "en": "Understood. I'll try to get it to you by Tuesday evening."}]}, {"n": 3, "zh": "对话：赵叔叔跟阿玲谈做小生意", "vi": "Hội thoại: Chú Triệu nói với A Linh về làm ăn nhỏ", "en": "Dialogue: Uncle Zhao talks with A Linh about a small business", "kw": ["积累", "经验", "生意", "一切", "谈"], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "赵叔叔，听说您在社区开了一家小文具店？", "p": ["zhào", "shū", "shu", "", "tīng", "shuō", "nín", "zài", "shè", "qū", "kāi", "le", "yì", "jiā", "xiǎo", "wén", "jù", "diàn", ""], "vi": "Chú Triệu, nghe nói chú mở một tiệm văn phòng phẩm nhỏ trong khu?", "en": "Uncle Zhao, I heard you opened a little stationery shop in the neighbourhood?"}, {"s": "赵叔叔", "sp": ["zhào", "shū", "shu"], "t": "是啊。说起来是生意，其实刚开头那几个月，一切都比我想的慢。", "p": ["shì", "a", "", "shuō", "qǐ", "lái", "shì", "shēng", "yi", "", "qí", "shí", "gāng", "kāi", "tóu", "nà", "jǐ", "gè", "yuè", "", "yí", "qiè", "dōu", "bǐ", "wǒ", "xiǎng", "de", "màn", ""], "vi": "Phải. Nói là làm ăn, nhưng mấy tháng đầu mọi thứ đều chậm hơn chú nghĩ.", "en": "That's right. You can call it a business, but in those first few months everything was slower than I had expected."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "您以前不是做过老师吗？开店跟教书差很多吧？", "p": ["nín", "yǐ", "qián", "bú", "shì", "zuò", "guò", "lǎo", "shī", "ma", "", "kāi", "diàn", "gēn", "jiāo", "shū", "chà", "hěn", "duō", "ba", ""], "vi": "Trước chú chẳng phải làm giáo viên sao? Mở tiệm khác dạy học nhiều chứ?", "en": "Weren't you a teacher before? Running a shop must be very different from teaching, surely?"}, {"s": "赵叔叔", "sp": ["zhào", "shū", "shu"], "t": "差很多。不过以前带学生，也让我积累了一些与人谈话的经验。客人来谈需要，我能听得比较耐心。", "p": ["chà", "hěn", "duō", "", "bú", "guò", "yǐ", "qián", "dài", "xué", "shēng", "", "yě", "ràng", "wǒ", "jī", "lěi", "le", "yì", "xiē", "yǔ", "rén", "tán", "huà", "de", "jīng", "yàn", "", "kè", "rén", "lái", "tán", "xū", "yào", "", "wǒ", "néng", "tīng", "de", "bǐ", "jiào", "nài", "xīn", ""], "vi": "Khác nhiều. Nhưng trước dẫn học sinh cũng giúp chú tích lũy ít kinh nghiệm nói chuyện với người. Khách đến bàn nhu cầu, chú nghe được kiên nhẫn hơn.", "en": "Very different. But taking students before also helped me build up some experience of talking with people. When customers come to discuss what they need, I can listen more patiently."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "那现在好一些了吗？", "p": ["nà", "xiàn", "zài", "hǎo", "yì", "xiē", "le", "ma", ""], "vi": "Vậy giờ đã khá hơn chưa?", "en": "Is it any better now?"}, {"s": "赵叔叔", "sp": ["zhào", "shū", "shu"], "t": "慢慢好了。别急着看这个月赚多少，先把店里的事一件一件做稳。", "p": ["màn", "màn", "hǎo", "le", "", "bié", "jí", "zhe", "kàn", "zhè", "ge", "yuè", "zhuàn", "duō", "shǎo", "", "xiān", "bǎ", "diàn", "lǐ", "de", "shì", "yí", "jiàn", "yí", "jiàn", "zuò", "wěn", ""], "vi": "Dần khá rồi. Đừng vội nhìn tháng này kiếm được bao nhiêu, hãy làm vững từng việc trong tiệm đã.", "en": "It's slowly getting better. Don't be in a hurry to look at how much this month earns — first get each thing in the shop on a steady footing."}]}, {"n": 4, "zh": "短文：一条让人放心的消息", "vi": "Đoạn văn: Một tin khiến người ta yên tâm", "en": "Passage: A piece of news that puts people at ease", "kw": ["按时", "按照", "成功", "感谢", "奖金", "顺利", "消息"], "lines": [{"s": "", "sp": [], "t": "今年部门的工作进行得很顺利。大家按照年初写好的计划，一件一件按时做完，最后成功地赶上了大活动的日期。活动结束那天，经理发来一条消息，感谢每一个加班的人，还说今年会有一笔小小的奖金。钱不多，可那条消息让人觉得：只要把该做的事做完，别人是看得见的。", "p": ["jīn", "nián", "bù", "mén", "de", "gōng", "zuò", "jìn", "xíng", "de", "hěn", "shùn", "lì", "", "dà", "jiā", "àn", "zhào", "nián", "chū", "xiě", "hǎo", "de", "jì", "huà", "", "yí", "jiàn", "yí", "jiàn", "àn", "shí", "zuò", "wán", "", "zuì", "hòu", "chéng", "gōng", "dì", "gǎn", "shàng", "le", "dà", "huó", "dòng", "de", "rì", "qī", "", "huó", "dòng", "jié", "shù", "nà", "tiān", "", "jīng", "lǐ", "fà", "lái", "yì", "tiáo", "xiāo", "xi", "", "gǎn", "xiè", "měi", "yí", "gè", "jiā", "bān", "de", "rén", "", "hái", "shuō", "jīn", "nián", "huì", "yǒu", "yì", "bǐ", "xiǎo", "xiǎo", "de", "jiǎng", "jīn", "", "qián", "bù", "duō", "", "kě", "nà", "tiáo", "xiāo", "xi", "ràng", "rén", "jué", "de", "", "zhǐ", "yào", "bǎ", "gāi", "zuò", "de", "shì", "zuò", "wán", "", "bié", "rén", "shì", "kàn", "de", "jiàn", "de", ""], "vi": "Năm nay việc của phòng diễn ra rất thuận lợi. Mọi người làm theo kế hoạch viết từ đầu năm, hoàn thành đúng hạn từng việc, cuối cùng thành công bắt kịp ngày sự kiện lớn. Ngày kết thúc, giám đốc gửi một tin, cảm ơn từng người tăng ca, còn nói năm nay sẽ có một khoản thưởng nhỏ. Tiền không nhiều, nhưng tin ấy khiến người ta thấy: chỉ cần làm xong việc phải làm, người khác sẽ nhìn thấy.", "en": "This year the department's work has gone smoothly. Everyone followed the plan written at the beginning of the year, finished each task on time, and in the end succeeded in meeting the date of the big event. On the day it ended, the manager sent a message thanking everyone who had worked extra hours, and also said there would be a small bonus this year. It was not a lot of money, but that message made people feel that if you finish what you're supposed to do, others will notice."}]}, {"n": 5, "zh": "短文：不愿做的那份工作", "vi": "Đoạn văn: Việc mình không muốn làm", "en": "Passage: The work you would rather not do", "kw": ["不得不", "方法", "工资", "甚至", "责任", "知识"], "lines": [{"s": "", "sp": [], "t": "工作里总会有人不愿意做的事：又慢，又看不出成绩。可有时你不得不把它做完，因为那是你的责任。我曾经把一份很烦的材料推了又推，甚至想：这又不会加工资，为什么要认真？后来还是坐下来，找到自己的方法，把材料一项一项做清楚。做完以后我才发现，自己又多懂了一点相关的知识。工资是生活的一部分，但把一件难事做完，也会让人踏实。", "p": ["gōng", "zuò", "lǐ", "zǒng", "huì", "yǒu", "rén", "bú", "yuàn", "yì", "zuò", "de", "shì", "", "yòu", "màn", "", "yòu", "kàn", "bù", "chū", "chéng", "jì", "", "kě", "yǒu", "shí", "nǐ", "bù", "dé", "bù", "bǎ", "tā", "zuò", "wán", "", "yīn", "wèi", "nà", "shì", "nǐ", "de", "zé", "rèn", "", "wǒ", "céng", "jīng", "bǎ", "yí", "fèn", "hěn", "fán", "de", "cái", "liào", "tuī", "le", "yòu", "tuī", "", "shèn", "zhì", "xiǎng", "", "zhè", "yòu", "bú", "huì", "jiā", "gōng", "zī", "", "wèi", "shén", "me", "yào", "rèn", "zhēn", "", "hòu", "lái", "hái", "shì", "zuò", "xià", "lái", "", "zhǎo", "dào", "zì", "jǐ", "de", "fāng", "fǎ", "", "bǎ", "cái", "liào", "yí", "xiàng", "yí", "xiàng", "zuò", "qīng", "chǔ", "", "zuò", "wán", "yǐ", "hòu", "wǒ", "cái", "fā", "xiàn", "", "zì", "jǐ", "yòu", "duō", "dǒng", "le", "yì", "diǎn", "xiāng", "guān", "de", "zhī", "shi", "", "gōng", "zī", "shì", "shēng", "huó", "de", "yí", "bù", "fèn", "", "dàn", "bǎ", "yí", "jiàn", "nán", "shì", "zuò", "wán", "", "yě", "huì", "ràng", "rén", "tā", "shi", ""], "vi": "Trong việc luôn có chuyện người ta không muốn làm: vừa chậm, vừa không thấy thành tích. Nhưng đôi khi bạn buộc phải làm xong, vì đó là trách nhiệm. Tôi từng đẩy đi đẩy lại một bản tài liệu rất mệt, thậm chí nghĩ: cái này lại không tăng lương, cần gì nghiêm túc? Sau cùng vẫn ngồi xuống, tìm phương pháp của mình, làm rõ từng mục. Xong rồi tôi mới thấy mình hiểu thêm một chút kiến thức liên quan. Lương là một phần của đời sống, nhưng làm xong một việc khó cũng khiến người ta vững lòng.", "en": "In any job there are always things people would rather not do: they are slow, and they don't seem to show any results. But sometimes you have no choice but to finish them, because that is your responsibility. I once pushed a very tedious set of materials aside again and again, and even thought: this won't even raise my pay, so why take it seriously? In the end I still sat down, found my own method, and worked through the materials item by item. Only when I had finished did I realise I had learned a little more of the related knowledge. Pay is part of life, but finishing a hard task also leaves you feeling steady."}]}]}, {"l": 5, "texts": [{"n": 1, "zh": "对话：阿玲在家具店看沙发", "vi": "Hội thoại: A Linh xem ghế sofa ở cửa hàng nội thất", "en": "Dialogue: A Linh looks at sofas in a furniture shop", "kw": ["打折", "家具", "价格", "肯定", "流行", "沙发", "质量"], "lines": [{"s": "吴姐", "sp": ["wú", "jiě"], "t": "姑娘，想看沙发吗？这几款最近很流行，这周末还打折。", "p": ["gū", "niáng", "", "xiǎng", "kàn", "shā", "fā", "ma", "", "zhè", "jǐ", "kuǎn", "zuì", "jìn", "hěn", "liú", "xíng", "", "zhè", "zhōu", "mò", "hái", "dǎ", "zhé", ""], "vi": "Cô gái, muốn xem sofa không? Mấy mẫu này gần đây rất thịnh hành, cuối tuần này còn giảm giá.", "en": "Miss, would you like to look at sofas? These styles have been very popular lately, and they're also on sale this weekend."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我想看质量好一点儿的。颜色不要太花，价格也希望能接受。", "p": ["wǒ", "xiǎng", "kàn", "zhì", "liàng", "hǎo", "yì", "diǎn", "r", "de", "", "yán", "sè", "bú", "yào", "tài", "huā", "", "jià", "gé", "yě", "xī", "wàng", "néng", "jiē", "shòu", ""], "vi": "Em muốn xem loại chất lượng khá hơn một chút. Màu đừng quá sặc sỡ, giá cũng mong chấp nhận được.", "en": "I'd like to see ones with a bit better quality. The colour shouldn't be too busy, and I hope the price is acceptable too."}, {"s": "吴姐", "sp": ["wú", "jiě"], "t": "那您看这一套。面料耐用，坐上去也舒服。现在的价格比上周低了不少。", "p": ["nà", "nín", "kàn", "zhè", "yí", "tào", "", "miàn", "liào", "nài", "yòng", "", "zuò", "shàng", "qù", "yě", "shū", "fú", "", "xiàn", "zài", "de", "jià", "gé", "bǐ", "shàng", "zhōu", "dī", "le", "bù", "shǎo", ""], "vi": "Vậy cô xem bộ này. Vải bền, ngồi cũng êm. Giá hiện tại thấp hơn tuần trước nhiều.", "en": "Then have a look at this set. The fabric is durable, and it's comfortable to sit on. The price now is quite a bit lower than last week."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我再摸摸。买家具不是小事，我肯定要再比较一下。", "p": ["wǒ", "zài", "mō", "mō", "", "mǎi", "jiā", "jù", "bú", "shì", "xiǎo", "shì", "", "wǒ", "kěn", "dìng", "yào", "zài", "bǐ", "jiào", "yí", "xià", ""], "vi": "Em sờ thêm đã. Mua nội thất không phải việc nhỏ, em chắc chắn phải so nữa.", "en": "I'll feel it again. Buying furniture isn't a small thing — I definitely want to compare a bit more."}, {"s": "吴姐", "sp": ["wú", "jiě"], "t": "可以。您先拍个照片，想好了再来。", "p": ["kě", "yǐ", "", "nín", "xiān", "pāi", "gè", "zhào", "piān", "", "xiǎng", "hǎo", "le", "zài", "lái", ""], "vi": "Được. Cô chụp ảnh trước, nghĩ xong hãy đến.", "en": "Of course. Take a photo first, and come back when you've thought it over."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "好，谢谢您。我今天先看看别的店。", "p": ["hǎo", "", "xiè", "xiè", "nín", "", "wǒ", "jīn", "tiān", "xiān", "kàn", "kàn", "bié", "de", "diàn", ""], "vi": "Vâng, cảm ơn chị. Hôm nay em xem thêm vài cửa khác đã.", "en": "Thank you. I'll look at a few other shops today first."}]}, {"n": 2, "zh": "对话：阿玲和周南在商场", "vi": "Hội thoại: A Linh và Châu Nam ở trung tâm thương mại", "en": "Dialogue: A Linh and Zhou Nan at the mall", "kw": ["实在", "顺便", "现金", "效果", "光", "台"], "lines": [{"s": "周南", "sp": ["zhōu", "nán"], "t": "你不是来看台灯的吗？怎么站在冰箱前面了？", "p": ["nǐ", "bú", "shì", "lái", "kàn", "tái", "dēng", "de", "ma", "", "zěn", "me", "zhàn", "zài", "bīng", "xiāng", "qián", "miàn", "le", ""], "vi": "Chẳng phải cậu đến xem đèn bàn sao? Sao lại đứng trước tủ lạnh?", "en": "Weren't you here to look at desk lamps? Why are you standing in front of the fridges?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我想顺便看看。这一台能耗低，可价钱实在不便宜。", "p": ["wǒ", "xiǎng", "shùn", "biàn", "kàn", "kàn", "", "zhè", "yì", "tái", "néng", "hào", "dī", "", "kě", "jià", "qián", "shí", "zài", "bú", "biàn", "yí", ""], "vi": "Mình muốn tiện thể xem. Cái này tiêu hao điện thấp, nhưng giá thực sự không rẻ.", "en": "I wanted to have a look while we're here. This one uses little electricity, but the price really isn't cheap."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "你不能光看宣传上写的效果，最好再问问一个月大概要用多少电。", "p": ["nǐ", "bù", "néng", "guāng", "kàn", "xuān", "chuán", "shàng", "xiě", "de", "xiào", "guǒ", "", "zuì", "hǎo", "zài", "wèn", "wèn", "yí", "gè", "yuè", "dà", "gài", "yào", "yòng", "duō", "shǎo", "diàn", ""], "vi": "Cậu đừng chỉ nhìn hiệu quả viết trên tờ quảng cáo, tốt nhất hỏi thêm mỗi tháng tốn khoảng bao nhiêu điện.", "en": "You shouldn't only look at the results written in the ads. It'd be better to ask how much electricity it uses in a month."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "说得对。那台灯呢？我想找一盏光不会太刺眼的。", "p": ["shuō", "de", "duì", "", "nà", "tái", "dēng", "ne", "", "wǒ", "xiǎng", "zhǎo", "yì", "zhǎn", "guāng", "bú", "huì", "tài", "cì", "yǎn", "de", ""], "vi": "Đúng đó. Còn đèn bàn? Mình muốn tìm cái ánh sáng không quá chói.", "en": "That's true. And the lamp? I want one whose light isn't too harsh."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "那两台都不错。你要是决定买，我可以用现金先付。", "p": ["nà", "liǎng", "tái", "dōu", "bú", "cuò", "", "nǐ", "yào", "shi", "jué", "dìng", "mǎi", "", "wǒ", "kě", "yǐ", "yòng", "xiàn", "jīn", "xiān", "fù", ""], "vi": "Hai cái kia cũng ổn. Nếu cậu quyết mua, mình có thể trả bằng tiền mặt trước.", "en": "Those two are both fine. If you decide to buy one, I can pay in cash first."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "先把说明书拍下来，回去再想一晚吧。", "p": ["xiān", "bǎ", "shuō", "míng", "shū", "pāi", "xià", "lái", "", "huí", "qù", "zài", "xiǎng", "yì", "wǎn", "ba", ""], "vi": "Chụp hướng dẫn đã, về nghĩ thêm một đêm.", "en": "Let's photograph the instructions first and think it over for a night at home."}]}, {"n": 3, "zh": "对话：给陈老师挑一份礼物", "vi": "Hội thoại: Chọn quà cho cô Trần", "en": "Dialogue: Choosing a gift for Teacher Chen", "kw": ["广告", "葡萄", "实际", "味道", "邀请", "艺术", "优点"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "周末想邀请陈老师来家里吃晚饭。礼物你说买什么好？", "p": ["zhōu", "mò", "xiǎng", "yāo", "qǐng", "chén", "lǎo", "shī", "lái", "jiā", "lǐ", "chī", "wǎn", "fàn", "", "lǐ", "wù", "nǐ", "shuō", "mǎi", "shén", "me", "hǎo", ""], "vi": "Cuối tuần muốn mời cô Trần đến nhà ăn tối. Quà cậu bảo nên mua gì?", "en": "I'd like to invite Teacher Chen home for dinner at the weekend. What do you think we should buy her as a gift?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "水果比较合适。那边在卖葡萄，广告上写“又甜又大”，可不知道实际味道怎么样。", "p": ["shuǐ", "guǒ", "bǐ", "jiào", "hé", "shì", "", "nà", "biān", "zài", "mài", "pú", "tao", "", "guǎng", "gào", "shàng", "xiě", "", "yòu", "tián", "yòu", "dà", "", "", "kě", "bù", "zhī", "dào", "shí", "jì", "wèi", "dao", "zěn", "me", "yàng", ""], "vi": "Trái cây thì hợp. Bên đó đang bán nho, quảng cáo viết «vừa ngọt vừa to», nhưng không biết vị thực tế ra sao.", "en": "Fruit would be suitable. They're selling grapes over there, and the advertisement says \"sweet and big\", but I don't know what they actually taste like."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "那我们先买一丁点儿尝尝。要是味道不行，再看别的。", "p": ["nà", "wǒ", "men", "xiān", "mǎi", "yì", "dīng", "diǎn", "r", "cháng", "cháng", "", "yào", "shi", "wèi", "dao", "bù", "xíng", "", "zài", "kàn", "bié", "de", ""], "vi": "Vậy mình mua một chút nếm trước. Nếu vị không ổn thì xem thứ khác.", "en": "Then let's buy a little to taste first. If the flavour isn't right, we'll look at something else."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "也可以送一本小画册。她喜欢艺术，这算是一个优点：不贵，又记得住。", "p": ["yě", "kě", "yǐ", "sòng", "yì", "běn", "xiǎo", "huà", "cè", "", "tā", "xǐ", "huān", "yì", "shù", "", "zhè", "suàn", "shì", "yí", "gè", "yōu", "diǎn", "", "bú", "guì", "", "yòu", "jì", "de", "zhù", ""], "vi": "Cũng có thể tặng một tập tranh nhỏ. Cô thích nghệ thuật, đó là một ưu điểm: không đắt mà lại dễ nhớ.", "en": "We could also give her a little book of pictures. She likes art, and that's one advantage: it isn't expensive, and she'll remember it."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "那就水果和画册都准备一点儿，让她选。", "p": ["nà", "jiù", "shuǐ", "guǒ", "hé", "huà", "cè", "dōu", "zhǔn", "bèi", "yì", "diǎn", "r", "", "ràng", "tā", "xuǎn", ""], "vi": "Vậy thì chuẩn bị cả trái cây lẫn tập tranh, để cô chọn.", "en": "Then let's get a little of both, the fruit and the picture book, and let her choose."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "好。广告再好看，我们也先看东西本身。", "p": ["hǎo", "", "guǎng", "gào", "zài", "hǎo", "kàn", "", "wǒ", "men", "yě", "xiān", "kàn", "dōng", "xi", "běn", "shēn", ""], "vi": "Được. Quảng cáo đẹp đến mấy, mình cũng xem bản thân món đồ đã.", "en": "All right. However nice the advertisement is, we'll look at the thing itself first."}]}, {"n": 4, "zh": "短文：买衣服时我给自己的几条标准", "vi": "Đoạn văn: Vài tiêu chuẩn tôi đặt khi mua áo", "en": "Passage: A few standards I set myself when I buy clothes", "kw": ["标准", "考虑", "浪费", "年龄", "样子", "质量"], "lines": [{"s": "", "sp": [], "t": "以前我买衣服，只看样子新不新，偶尔还跟着流行走。穿过两次就不想再穿，等于把钱浪费了。后来我给自己定了几条标准：先考虑质量，再看颜色和大小是否适合我现在的年龄。样子可以简单，但一定要舒服、耐穿。这样买，衣服虽然少了，可每一件都能穿很久。", "p": ["yǐ", "qián", "wǒ", "mǎi", "yī", "fú", "", "zhǐ", "kàn", "yàng", "zi", "xīn", "bù", "xīn", "", "ǒu", "ěr", "hái", "gēn", "zhe", "liú", "xíng", "zǒu", "", "chuān", "guò", "liǎng", "cì", "jiù", "bù", "xiǎng", "zài", "chuān", "", "děng", "yú", "bǎ", "qián", "làng", "fèi", "le", "", "hòu", "lái", "wǒ", "gěi", "zì", "jǐ", "dìng", "le", "jǐ", "tiáo", "biāo", "zhǔn", "", "xiān", "kǎo", "lǜ", "zhì", "liàng", "", "zài", "kàn", "yán", "sè", "hé", "dà", "xiǎo", "shì", "fǒu", "shì", "hé", "wǒ", "xiàn", "zài", "de", "nián", "líng", "", "yàng", "zi", "kě", "yǐ", "jiǎn", "dān", "", "dàn", "yí", "dìng", "yào", "shū", "fú", "", "nài", "chuān", "", "zhè", "yàng", "mǎi", "", "yī", "fú", "suī", "rán", "shǎo", "le", "", "kě", "měi", "yí", "jiàn", "dōu", "néng", "chuān", "hěn", "jiǔ", ""], "vi": "Trước kia tôi mua áo chỉ nhìn kiểu mới hay không, đôi lúc còn theo mốt. Mặc hai lần đã không muốn mặc nữa, chẳng khác nào lãng phí tiền. Sau tôi đặt cho mình vài tiêu chuẩn: trước hãy xem xét chất lượng, rồi mới nhìn màu và kích cỡ có hợp với tuổi hiện tại không. Kiểu có thể đơn giản, nhưng phải thoải mái, bền. Mua như vậy, áo tuy ít hơn, nhưng mỗi món mặc được rất lâu.", "en": "I used to buy clothes only by whether the look was new, and sometimes I even followed the fashion. After wearing something twice I wouldn't want it again, which really meant I was wasting money. Later I set myself a few standards: consider the quality first, and then see whether the colour and size suit my age now. The style can be simple, but it must be comfortable and long-lasting. Buying this way, I have fewer clothes, but I can wear each piece for a long time."}]}, {"n": 5, "zh": "短文：网上购物也要停一停", "vi": "Đoạn văn: Mua hàng online cũng cần dừng lại một chút", "en": "Passage: Even when shopping online, it helps to pause", "kw": ["购物", "任何", "受到", "尤其", "寄", "家具"], "lines": [{"s": "", "sp": [], "t": "现在网上购物很方便，图片好看，手指一点，过两天东西就寄到家。可任何便利的背后，都可能让人买多。我曾经受到几张漂亮图片的影响，尤其是家具，看着眼红就下了单，收到后才发现房间根本放不下。后来我给自己定了个习惯：想买的东西先放一天，再决定要不要点。购物是为了用，不是为了点得痛快。", "p": ["xiàn", "zài", "wǎng", "shàng", "gòu", "wù", "hěn", "fāng", "biàn", "", "tú", "piàn", "hǎo", "kàn", "", "shǒu", "zhǐ", "yì", "diǎn", "", "guò", "liǎng", "tiān", "dōng", "xi", "jiù", "jì", "dào", "jiā", "", "kě", "rèn", "hé", "biàn", "lì", "de", "bèi", "hòu", "", "dōu", "kě", "néng", "ràng", "rén", "mǎi", "duō", "", "wǒ", "céng", "jīng", "shòu", "dào", "jǐ", "zhāng", "piào", "liàng", "tú", "piàn", "de", "yǐng", "xiǎng", "", "yóu", "qí", "shì", "jiā", "jù", "", "kàn", "zhe", "yǎn", "hóng", "jiù", "xià", "le", "dān", "", "shōu", "dào", "hòu", "cái", "fā", "xiàn", "fáng", "jiān", "gēn", "běn", "fàng", "bú", "xià", "", "hòu", "lái", "wǒ", "gěi", "zì", "jǐ", "dìng", "le", "gè", "xí", "guàn", "", "xiǎng", "mǎi", "de", "dōng", "xi", "xiān", "fàng", "yì", "tiān", "", "zài", "jué", "dìng", "yào", "bú", "yào", "diǎn", "", "gòu", "wù", "shì", "wèi", "le", "yòng", "", "bú", "shì", "wèi", "le", "diǎn", "de", "tòng", "kuai", ""], "vi": "Giờ mua sắm trên mạng rất tiện, ảnh đẹp, một cái chạm tay, vài hôm sau đồ đã được gửi tới nhà. Nhưng đằng sau bất kỳ sự tiện nào cũng có thể khiến người ta mua nhiều. Tôi từng chịu ảnh hưởng của vài tấm ảnh đẹp, nhất là đồ nội thất, nhìn ham là đặt, nhận xong mới thấy phòng chẳng để vừa. Sau tôi đặt cho mình một thói quen: món muốn mua để đó một ngày, rồi mới quyết có bấm không. Mua sắm là để dùng, không phải để bấm cho đã.", "en": "Shopping online is very convenient now: the pictures look nice, you tap once, and in a couple of days the things are sent to your home. But behind any convenience there is a chance you'll buy too much. I was once influenced by a few attractive pictures, especially of furniture; I ordered while my eyes were still hungry for it, and only when it arrived did I find it wouldn't fit in the room at all. Later I gave myself a habit: I leave anything I want to buy for a day, and only then decide whether to click. You shop in order to use things, not in order to enjoy clicking."}]}]}, {"l": 6, "texts": [{"n": 1, "zh": "对话：小雪逛完小店回来", "vi": "Hội thoại: Tiểu Tuyết về sau khi ghé cửa hàng nhỏ", "en": "Dialogue: Xiaoxue comes back from a little shop", "kw": ["售货员", "打扰", "果汁", "竟然", "袜子"], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "你怎么这么晚才回来？我还以为你在图书馆。", "p": ["nǐ", "zěn", "me", "zhè", "me", "wǎn", "cái", "huí", "lái", "", "wǒ", "hái", "yǐ", "wéi", "nǐ", "zài", "tú", "shū", "guǎn", ""], "vi": "Sao cậu về muộn thế? Mình còn tưởng cậu ở thư viện.", "en": "Why are you back so late? I thought you were at the library."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "我路过那家小店，进去看袜子。售货员一直跟着我介绍，有点儿打扰，可她态度很好。", "p": ["wǒ", "lù", "guò", "nà", "jiā", "xiǎo", "diàn", "", "jìn", "qù", "kàn", "wà", "zi", "", "shòu", "huò", "yuán", "yì", "zhí", "gēn", "zhe", "wǒ", "jiè", "shào", "", "yǒu", "diǎn", "r", "dǎ", "rǎo", "", "kě", "tā", "tài", "dù", "hěn", "hǎo", ""], "vi": "Mình đi ngang tiệm nhỏ, vào xem tất. Nhân viên bán hàng cứ đi theo giới thiệu, hơi làm phiền, nhưng thái độ chị ấy rất tốt.", "en": "I passed that little shop and went in to look at socks. The salesperson kept following me around to explain things, which was a bit of a disturbance, but her manner was very kind."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "那你买了吗？", "p": ["nà", "nǐ", "mǎi", "le", "ma", ""], "vi": "Vậy cậu có mua không?", "en": "So did you buy anything?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "买了两双深色的。排队付款的时候，我竟然还拿了一瓶果汁。走的时候，售货员还说欢迎再来。", "p": ["mǎi", "le", "liǎng", "shuāng", "shēn", "sè", "de", "", "pái", "duì", "fù", "kuǎn", "de", "shí", "hòu", "", "wǒ", "jìng", "rán", "hái", "ná", "le", "yì", "píng", "guǒ", "zhī", "", "zǒu", "de", "shí", "hòu", "", "shòu", "huò", "yuán", "hái", "shuō", "huān", "yíng", "zài", "lái", ""], "vi": "Mua hai đôi màu tối. Lúc xếp hàng trả tiền, mình không ngờ còn cầm thêm một chai nước ép. Lúc đi, nhân viên còn nói lần sau ghé lại.", "en": "I bought two dark pairs. While I was queuing to pay, I even picked up a bottle of juice, unexpectedly. As I left, the salesperson said I was welcome to come again."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "瓶子在包里吗？小心别洒了。", "p": ["píng", "zi", "zài", "bāo", "lǐ", "ma", "", "xiǎo", "xīn", "bié", "sǎ", "le", ""], "vi": "Chai trong túi chứ? Cẩn thận kẻo đổ.", "en": "Is the bottle in your bag? Be careful not to spill it."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "放稳了。你要不要尝一口？很甜。", "p": ["fàng", "wěn", "le", "", "nǐ", "yào", "bú", "yào", "cháng", "yì", "kǒu", "", "hěn", "tián", ""], "vi": "Để chắc rồi. Cậu có muốn nếm một ngụm không? Ngọt lắm.", "en": "It's sitting securely. Do you want a sip? It's very sweet."}]}, {"n": 2, "zh": "对话：阿玲和周南帮社区挑西红柿", "vi": "Hội thoại: A Linh và Châu Nam chọn cà chua giúp khu phố", "en": "Dialogue: A Linh and Zhou Nan pick tomatoes for the neighbourhood", "kw": ["百分之", "西红柿", "好处", "皮肤", "倍", "尝"], "lines": [{"s": "周南", "sp": ["zhōu", "nán"], "t": "吴姐托我们买西红柿，做明天社区的汤。你说买哪一种？", "p": ["wú", "jiě", "tuō", "wǒ", "men", "mǎi", "xī", "hóng", "shì", "", "zuò", "míng", "tiān", "shè", "qū", "de", "tāng", "", "nǐ", "shuō", "mǎi", "nǎ", "yì", "zhǒng", ""], "vi": "Chị Ngô nhờ mình mua cà chua, nấu canh cho khu phố ngày mai. Cậu bảo mua loại nào?", "en": "Sister Wu asked us to buy tomatoes for tomorrow's neighbourhood soup. Which kind do you think we should get?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "先尝一块。这边的更甜，表面也更光滑。", "p": ["xiān", "cháng", "yí", "kuài", "", "zhè", "biān", "de", "gèng", "tián", "", "biǎo", "miàn", "yě", "gèng", "guāng", "huá", ""], "vi": "Nếm một miếng đã. Bên này ngọt hơn, bề mặt cũng mượt hơn.", "en": "Let's taste a piece first. These are sweeter, and the skin is smoother too."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "摊主说，常吃对皮肤有好处。我也不知道是不是真的。", "p": ["tān", "zhǔ", "shuō", "", "cháng", "chī", "duì", "pí", "fū", "yǒu", "hǎo", "chu", "", "wǒ", "yě", "bù", "zhī", "dào", "shì", "bú", "shì", "zhēn", "de", ""], "vi": "Chủ quán nói ăn thường thì có lợi cho da. Mình cũng không biết có thật không.", "en": "The stallholder said eating them often is good for the skin. I don't know whether that's true."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "好处先不说，你看这个牌子：熟的占百分之八十，比那边多了差不多一倍。做汤正合适。", "p": ["hǎo", "chu", "xiān", "bù", "shuō", "", "nǐ", "kàn", "zhè", "ge", "pái", "zi", "", "shú", "de", "zhàn", "bǎi", "fēn", "zhī", "bā", "shí", "", "bǐ", "nà", "biān", "duō", "le", "chà", "bu", "duō", "yí", "bèi", "", "zuò", "tāng", "zhèng", "hé", "shì", ""], "vi": "Lợi ích để đó đã, cậu nhìn tấm bảng này: quả chín chiếm tám mươi phần trăm, nhiều hơn bên kia gần một lần. Nấu canh thì đúng.", "en": "Leave the benefits aside for a moment. Look at this sign: eighty percent of them are ripe, almost twice as many as at the other stall. That'll be just right for soup."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "那就这一筐。我再问一句能不能少拿几个青的。", "p": ["nà", "jiù", "zhè", "yì", "kuāng", "", "wǒ", "zài", "wèn", "yí", "jù", "néng", "bù", "néng", "shǎo", "ná", "jǐ", "gè", "qīng", "de", ""], "vi": "Vậy lấy rổ này. Mình hỏi thêm có thể bớt vài quả xanh không.", "en": "Then let's take this basket. I'll also ask whether we can leave out a few of the green ones."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "好。买完我们直接送到吴姐那儿。", "p": ["hǎo", "", "mǎi", "wán", "wǒ", "men", "zhí", "jiē", "sòng", "dào", "wú", "jiě", "nà", "r", ""], "vi": "Được. Mua xong mình đưa thẳng tới chỗ chị Ngô.", "en": "All right. When we've bought them we'll take them straight to Sister Wu."}]}, {"n": 3, "zh": "对话：周南要出远门买箱子", "vi": "Hội thoại: Châu Nam sắp đi xa, mua vali", "en": "Dialogue: Zhou Nan is going away and buys a suitcase", "kw": ["方面", "活动", "免费", "修理", "值得", "内", "轻"], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "你不是下个月要去广州吗？怎么来看箱子了？", "p": ["nǐ", "bú", "shì", "xià", "gè", "yuè", "yào", "qù", "guǎng", "zhōu", "ma", "", "zěn", "me", "lái", "kàn", "xiāng", "zi", "le", ""], "vi": "Tháng sau chẳng phải cậu đi Quảng Châu sao? Sao lại xem vali?", "en": "Aren't you going to Guangzhou next month? Why are you looking at suitcases?"}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "我想买一个轻一点儿的。你看这只，提起来不费劲，内里还有一层小口袋。", "p": ["wǒ", "xiǎng", "mǎi", "yí", "gè", "qīng", "yì", "diǎn", "r", "de", "", "nǐ", "kàn", "zhè", "zhǐ", "", "tí", "qǐ", "lái", "bú", "fèi", "jìn", "", "nèi", "lǐ", "hái", "yǒu", "yì", "céng", "xiǎo", "kǒu", "dài", ""], "vi": "Mình muốn mua cái nhẹ hơn một chút. Cậu xem cái này, xách lên không mất sức, bên trong còn một lớp túi nhỏ.", "en": "I'd like one that's a bit lighter. Look at this one: it isn't hard to lift, and there is also a layer of small pockets inside."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "价格呢？这周末商场有活动，会不会便宜些？", "p": ["jià", "gé", "ne", "", "zhè", "zhōu", "mò", "shāng", "chǎng", "yǒu", "huó", "dòng", "", "huì", "bú", "huì", "pián", "yi", "xiē", ""], "vi": "Còn giá? Cuối tuần này trung tâm có hoạt động, liệu có rẻ hơn không?", "en": "What about the price? The mall has a promotion this weekend — might it be cheaper?"}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "问过了。现在买，一年内免费修理，我觉得值得。", "p": ["wèn", "guò", "le", "", "xiàn", "zài", "mǎi", "", "yì", "nián", "nèi", "miǎn", "fèi", "xiū", "lǐ", "", "wǒ", "jué", "de", "zhí", "de", ""], "vi": "Hỏi rồi. Mua bây giờ thì trong một năm sửa miễn phí, mình thấy đáng.", "en": "I've already asked. If I buy it now, repairs are free within a year. I think it's worth it."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "那在质量方面没问题就好。你再试试轮子转不转得稳。", "p": ["nà", "zài", "zhì", "liàng", "fāng", "miàn", "méi", "wèn", "tí", "jiù", "hǎo", "", "nǐ", "zài", "shì", "shì", "lún", "zi", "zhuǎn", "bù", "zhuǎn", "de", "wěn", ""], "vi": "Vậy về mặt chất lượng không vấn đề là được. Cậu thử bánh xe quay có vững không.", "en": "Then as long as there's no problem with the quality, that's fine. Try whether the wheels run steadily too."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "还行。我就拿这只吧，省得再跑一趟。", "p": ["hái", "xíng", "", "wǒ", "jiù", "ná", "zhè", "zhǐ", "ba", "", "shěng", "de", "zài", "pǎo", "yí", "tàng", ""], "vi": "Cũng ổn. Mình lấy cái này vậy, khỏi phải chạy thêm chuyến.", "en": "It's all right. I'll take this one, so I don't have to come back again."}]}, {"n": 4, "zh": "短文：书店里的一场小活动", "vi": "Đoạn văn: Một hoạt động nhỏ trong hiệu sách", "en": "Passage: A little event in the bookshop", "kw": ["获得", "举行", "其中", "所有", "小说", "支持", "满"], "lines": [{"s": "", "sp": [], "t": "今天下午，学校书店举行了一场交换旧书的活动。座位很快就坐满了，过道里也站着人。所有带来书的同学，都可以获得一张小书签；其中带来三本以上的，还能再选一本小说带回家。我把两本看完的故事和一本词典放在桌上。虽然我没有多换到什么，可看到那么多人来支持这场活动，心里还是很高兴。晚上我坐在灯下，翻开那本刚换来的小说，倒觉得这一下午没有白来。", "p": ["jīn", "tiān", "xià", "wǔ", "", "xué", "xiào", "shū", "diàn", "jǔ", "xíng", "le", "yì", "cháng", "jiāo", "huàn", "jiù", "shū", "de", "huó", "dòng", "", "zuò", "wèi", "hěn", "kuài", "jiù", "zuò", "mǎn", "le", "", "guò", "dào", "lǐ", "yě", "zhàn", "zhe", "rén", "", "suǒ", "yǒu", "dài", "lái", "shū", "de", "tóng", "xué", "", "dōu", "kě", "yǐ", "huò", "de", "yì", "zhāng", "xiǎo", "shū", "qiān", "", "qí", "zhōng", "dài", "lái", "sān", "běn", "yǐ", "shàng", "de", "", "hái", "néng", "zài", "xuǎn", "yì", "běn", "xiǎo", "shuō", "dài", "huí", "jiā", "", "wǒ", "bǎ", "liǎng", "běn", "kàn", "wán", "de", "gù", "shì", "hé", "yì", "běn", "cí", "diǎn", "fàng", "zài", "zhuō", "shàng", "", "suī", "rán", "wǒ", "méi", "yǒu", "duō", "huàn", "dào", "shén", "me", "", "kě", "kàn", "dào", "nà", "me", "duō", "rén", "lái", "zhī", "chí", "zhè", "chǎng", "huó", "dòng", "", "xīn", "lǐ", "hái", "shì", "hěn", "gāo", "xìng", "", "wǎn", "shàng", "wǒ", "zuò", "zài", "dēng", "xià", "", "fān", "kāi", "nà", "běn", "gāng", "huàn", "lái", "de", "xiǎo", "shuō", "", "dào", "jué", "de", "zhè", "yí", "xià", "wǔ", "méi", "yǒu", "bái", "lái", ""], "vi": "Chiều nay hiệu sách trường tổ chức một hoạt động đổi sách cũ. Chỗ ngồi chẳng mấy chốc đã kín, lối đi cũng có người đứng. Tất cả bạn mang sách đến đều có thể nhận một tấm đánh dấu sách nhỏ; trong số đó ai mang từ ba quyển trở lên còn được chọn thêm một tiểu thuyết mang về. Tôi để hai tập truyện đã đọc xong và một quyển từ điển lên bàn. Tuy không đổi thêm được bao nhiêu, nhưng thấy nhiều người đến ủng hộ hoạt động ấy, trong lòng vẫn vui. Tối tôi ngồi dưới đèn, mở quyển tiểu thuyết mới đổi, lại thấy cả buổi chiều không uổng.", "en": "This afternoon the school bookshop held an event for exchanging old books. The seats were soon full, and people were standing in the aisles as well. All the students who brought books could obtain a little bookmark; among them, those who brought three or more could also choose a novel to take home. I put two stories I had finished and a dictionary on the table. Although I did not exchange much extra, I was still glad to see so many people come and support the event. In the evening I sat under the lamp, opened the novel I had just exchanged, and felt that the afternoon had not been wasted."}]}, {"n": 5, "zh": "短文：比的不只是价格", "vi": "Đoạn văn: So không chỉ mỗi cái giá", "en": "Passage: It is not only the price you compare", "kw": ["降低", "举办", "例如", "情况", "各"], "lines": [{"s": "", "sp": [], "t": "商场一举办促销，价格就会降低一些，这谁都知道。可各家的情况并不一样。例如上周校园超市减价，我看到两种外观差不多的笔记本：一种很便宜，写两天纸就起毛；另一种贵一点，却能用一个学期。后来我才明白，减价是让人走近货架，真正要比较的，是自己会用多久。便宜得让人立刻动手，不一定最合适；贵一点但能用很长时间，有时反而更省。", "p": ["shāng", "chǎng", "yì", "jǔ", "bàn", "cù", "xiāo", "", "jià", "gé", "jiù", "huì", "jiàng", "dī", "yì", "xiē", "", "zhè", "shéi", "dōu", "zhī", "dào", "", "kě", "gè", "jiā", "de", "qíng", "kuàng", "bìng", "bù", "yí", "yàng", "", "lì", "rú", "shàng", "zhōu", "xiào", "yuán", "chāo", "shì", "jiǎn", "jià", "", "wǒ", "kàn", "dào", "liǎng", "zhǒng", "wài", "guān", "chà", "bu", "duō", "de", "bǐ", "jì", "běn", "", "yì", "zhǒng", "hěn", "pián", "yi", "", "xiě", "liǎng", "tiān", "zhǐ", "jiù", "qǐ", "máo", "", "lìng", "yì", "zhǒng", "guì", "yì", "diǎn", "", "què", "néng", "yòng", "yí", "gè", "xué", "qī", "", "hòu", "lái", "wǒ", "cái", "míng", "bái", "", "jiǎn", "jià", "shì", "ràng", "rén", "zǒu", "jìn", "huò", "jià", "", "zhēn", "zhèng", "yào", "bǐ", "jiào", "de", "", "shì", "zì", "jǐ", "huì", "yòng", "duō", "jiǔ", "", "pián", "yi", "de", "ràng", "rén", "lì", "kè", "dòng", "shǒu", "", "bù", "yí", "dìng", "zuì", "hé", "shì", "", "guì", "yì", "diǎn", "dàn", "néng", "yòng", "hěn", "cháng", "shí", "jiān", "", "yǒu", "shí", "fǎn", "ér", "gèng", "shěng", ""], "vi": "Trung tâm một tổ chức khuyến mãi là giá sẽ giảm đôi chút, ai cũng biết. Nhưng tình hình mỗi nơi không giống nhau. Ví dụ tuần trước siêu thị trong trường giảm giá, tôi thấy hai loại vở trông gần như nhau: một loại rất rẻ, viết hai ngày giấy đã xơ; loại kia đắt hơn một chút, nhưng dùng được cả học kỳ. Sau tôi mới hiểu, giảm giá là để người ta lại gần kệ, điều thật sự cần so là mình dùng được bao lâu. Rẻ đến mức khiến người ta sờ ngay, chưa chắc đã hợp nhất; đắt hơn một chút nhưng dùng lâu, đôi khi lại tiết kiệm hơn.", "en": "Everyone knows that as soon as a shopping centre holds a promotion, prices will drop a little. But the situation is not the same at every shop. For example, when the campus supermarket reduced prices last week, I saw two kinds of notebook that looked almost alike: one was very cheap, but after two days of writing the paper began to fluff; the other cost a little more, yet it could last a whole term. Only later did I understand that a sale is what brings you to the shelf, and what you really have to compare is how long you will use the thing. Something so cheap that you reach for it at once is not necessarily the best fit; something a little dearer that lasts a long time can, in fact, save you more."}]}]}, {"l": 7, "texts": [{"n": 1, "zh": "对话：换季的时候阿玲咳嗽了", "vi": "Hội thoại: Đổi mùa, A Linh bị ho", "en": "Dialogue: A Linh has a cough when the season changes", "kw": ["窗户", "估计", "咳嗽", "空气", "气候", "严重", "擦"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你的声音怎么哑了？是不是又咳嗽了？", "p": ["nǐ", "de", "shēng", "yīn", "zěn", "me", "yǎ", "le", "", "shì", "bú", "shì", "yòu", "ké", "sou", "le", ""], "vi": "Giọng cậu sao khàn thế? Lại ho rồi à?", "en": "Why is your voice so hoarse? Have you got a cough again?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "这两天气候一下子变冷，我晚上忘了关窗户，早上起来就咳。还好不太严重。", "p": ["zhè", "liǎng", "tiān", "qì", "hòu", "yí", "xià", "zi", "biàn", "lěng", "", "wǒ", "wǎn", "shàng", "wàng", "le", "guān", "chuāng", "hu", "", "zǎo", "shàng", "qǐ", "lái", "jiù", "ké", "", "hái", "hǎo", "bú", "tài", "yán", "zhòng", ""], "vi": "Mấy hôm nay khí hậu lạnh đột ngột, tối mình quên đóng cửa sổ, sáng dậy là ho. May mà không nghiêm trọng lắm.", "en": "The climate turned cold all of a sudden these past two days. I forgot to close the window at night, and I was coughing when I got up. Luckily it isn't too serious."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "我估计是风灌进来了。你把窗边擦一擦，别让灰和冷空气一起进来。", "p": ["wǒ", "gū", "jì", "shì", "fēng", "guàn", "jìn", "lái", "le", "", "nǐ", "bǎ", "chuāng", "biān", "cā", "yì", "cā", "", "bié", "ràng", "huī", "hé", "lěng", "kōng", "qì", "yì", "qǐ", "jìn", "lái", ""], "vi": "Mình đoán gió lùa vào. Cậu lau mép cửa sổ một chút, đừng để bụi và không khí lạnh cùng vào.", "en": "I would estimate the wind blew in. Wipe around the window a bit, so the dust and the cold air don't come in together."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "好。我再泡杯热的。你那边呢？还习惯这儿春天的气候吗？", "p": ["hǎo", "", "wǒ", "zài", "pào", "bēi", "rè", "de", "", "nǐ", "nà", "biān", "ne", "", "hái", "xí", "guàn", "zhè", "r", "chūn", "tiān", "de", "qì", "hòu", "ma", ""], "vi": "Được. Mình pha thêm chén nóng. Còn phía cậu? Đã quen khí hậu mùa xuân ở đây chưa?", "en": "All right. I'll also make a cup of something hot. What about you? Have you got used to the spring climate here yet?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "比我家那边湿一点儿，不过开窗换空气，人会舒服些。", "p": ["bǐ", "wǒ", "jiā", "nà", "biān", "shī", "yì", "diǎn", "r", "", "bú", "guò", "kāi", "chuāng", "huàn", "kōng", "qì", "", "rén", "huì", "shū", "fú", "xiē", ""], "vi": "Ẩm hơn nhà mình một chút, nhưng mở cửa đổi không khí thì người dễ chịu hơn.", "en": "It's a bit damper than at home, but if you open the window and change the air, you feel more comfortable."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "那我白天把窗户打开一阵，晚上再关上。", "p": ["nà", "wǒ", "bái", "tiān", "bǎ", "chuāng", "hu", "dǎ", "kāi", "yí", "zhèn", "", "wǎn", "shàng", "zài", "guān", "shàng", ""], "vi": "Vậy ban ngày mình mở cửa sổ một lúc, tối đóng lại.", "en": "Then I'll open the window for a while in the daytime, and close it again at night."}]}, {"n": 2, "zh": "对话：小雪劝表哥少抽烟", "vi": "Hội thoại: Tiểu Tuyết khuyên anh họ ít hút thuốc", "en": "Dialogue: Xiaoxue urges her cousin to smoke less", "kw": ["来不及", "抽烟", "出现", "动作", "反对", "后悔", "帅"], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "你一接完电话就皱眉，谁啊？", "p": ["nǐ", "yì", "jiē", "wán", "diàn", "huà", "jiù", "zhòu", "méi", "", "shuí", "a", ""], "vi": "Vừa gác máy cậu đã nhíu mày, ai thế?", "en": "You frowned as soon as you hung up. Who was it?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "我表哥。他一抽烟，家里就反对，可他还是停不下来。", "p": ["wǒ", "biǎo", "gē", "", "tā", "yì", "chōu", "yān", "", "jiā", "lǐ", "jiù", "fǎn", "duì", "", "kě", "tā", "hái", "shì", "tíng", "bú", "xià", "lái", ""], "vi": "Anh họ mình. Hễ anh ấy hút thuốc là nhà phản đối, nhưng anh ấy vẫn không dừng được.", "en": "My cousin. Whenever he smokes, the family is against it, but he still can't stop."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "你怎么劝的？", "p": ["nǐ", "zěn", "me", "quàn", "de", ""], "vi": "Cậu khuyên thế nào?", "en": "What did you say to him?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "我说，你看起来挺帅的，可一出现烟味，别人就会往旁边让。他听了只是笑。", "p": ["wǒ", "shuō", "", "nǐ", "kàn", "qǐ", "lái", "tǐng", "shuài", "de", "", "kě", "yì", "chū", "xiàn", "yān", "wèi", "", "bié", "rén", "jiù", "huì", "wǎng", "páng", "biān", "ràng", "", "tā", "tīng", "le", "zhǐ", "shì", "xiào", ""], "vi": "Mình nói, trông anh cũng khá đẹp trai, nhưng hễ mùi thuốc xuất hiện là người khác tránh sang bên. Anh ấy nghe xong chỉ cười.", "en": "I said, \"You look quite handsome, but as soon as the smell of smoke appears, people step aside.\" He only laughed when he heard that."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "他后悔过吗？", "p": ["tā", "hòu", "huǐ", "guò", "ma", ""], "vi": "Anh ấy đã từng hối chưa?", "en": "Has he ever regretted it?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "后悔过。有一次要赶车，他在站里找打火机，动作一慢，车就开走了，来不及追。他说那次真不该把时间耗在烟上。", "p": ["hòu", "huǐ", "guò", "", "yǒu", "yí", "cì", "yào", "gǎn", "chē", "", "tā", "zài", "zhàn", "lǐ", "zhǎo", "dǎ", "huǒ", "jī", "", "dòng", "zuò", "yí", "màn", "", "chē", "jiù", "kāi", "zǒu", "le", "", "lái", "bu", "jí", "zhuī", "", "tā", "shuō", "nà", "cì", "zhēn", "bù", "gāi", "bǎ", "shí", "jiān", "hào", "zài", "yān", "shàng", ""], "vi": "Đã hối. Có lần phải bắt xe, anh ấy tìm bật lửa trong bến, động tác chậm một cái là xe chạy mất, không kịp đuổi. Anh ấy bảo lần ấy thật không nên bỏ thời gian vào thuốc.", "en": "He has. Once he had to catch a bus. He was looking for a lighter at the stop, his movements were just a little slow, and the bus left — he had no time to run after it. He said he really shouldn't have spent that time on a cigarette."}]}, {"n": 3, "zh": "对话：陈晓坐太久，大夫让他多走走", "vi": "Hội thoại: Trần Hiểu ngồi quá lâu, bác sĩ bảo đi bộ nhiều hơn", "en": "Dialogue: Chen Xiao sat too long, and the doctor told him to walk more", "kw": ["超过", "大夫", "散步", "研究", "植物"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "陈晓最近怎么总揉肩膀？", "p": ["chén", "xiǎo", "zuì", "jìn", "zěn", "me", "zǒng", "róu", "jiān", "bǎng", ""], "vi": "Dạo này Trần Hiểu sao cứ xoa vai?", "en": "Why has Chen Xiao been rubbing his shoulders so much lately?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "他写论文，一天坐在电脑前超过八个小时。上周去看大夫，大夫说先别吃药，每天出去散步。", "p": ["tā", "xiě", "lùn", "wén", "", "yì", "tiān", "zuò", "zài", "diàn", "nǎo", "qián", "chāo", "guò", "bā", "gè", "xiǎo", "shí", "", "shàng", "zhōu", "qù", "kàn", "dài", "fu", "", "dài", "fu", "shuō", "xiān", "bié", "chī", "yào", "", "měi", "tiān", "chū", "qù", "sàn", "bù", ""], "vi": "Cậu ấy viết luận văn, một ngày ngồi trước máy tính hơn tám tiếng. Tuần trước đi khám, bác sĩ bảo đừng uống thuốc vội, mỗi ngày ra ngoài đi dạo.", "en": "He's writing his thesis and sits in front of the computer for more than eight hours a day. He went to see the doctor last week. The doctor said not to take medicine first, and to go out for a walk every day."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "光散步够吗？", "p": ["guāng", "sàn", "bù", "gòu", "ma", ""], "vi": "Chỉ đi dạo đã đủ chưa?", "en": "Is walking enough on its own?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "大夫还让他在桌上放两盆植物，研究里说，看看绿色，眼睛会轻松一些。", "p": ["dài", "fu", "hái", "ràng", "tā", "zài", "zhuō", "shàng", "fàng", "liǎng", "pén", "zhí", "wù", "", "yán", "jiū", "lǐ", "shuō", "", "kàn", "kàn", "lǜ", "sè", "", "yǎn", "jīng", "huì", "qīng", "sōng", "yì", "xiē", ""], "vi": "Bác sĩ còn bảo đặt hai chậu cây trên bàn, trong nghiên cứu nói nhìn màu xanh thì mắt dễ chịu hơn.", "en": "The doctor also told him to put two pots of plants on the desk. Research says that looking at something green makes the eyes a little more at ease."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "那倒简单。我下午去市场，顺便帮他买一盆。", "p": ["nà", "dào", "jiǎn", "dān", "", "wǒ", "xià", "wǔ", "qù", "shì", "chǎng", "", "shùn", "biàn", "bāng", "tā", "mǎi", "yì", "pén", ""], "vi": "Thế thì đơn giản. Chiều mình ra chợ, tiện thể mua giúp một chậu.", "en": "That's easy enough. I'll go to the market this afternoon and get a pot for him while I'm there."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "你跟他说一声就行。他已经开始晚饭后围着楼散步了。", "p": ["nǐ", "gēn", "tā", "shuō", "yì", "shēng", "jiù", "xíng", "", "tā", "yǐ", "jīng", "kāi", "shǐ", "wǎn", "fàn", "hòu", "wéi", "zhe", "lóu", "sàn", "bù", "le", ""], "vi": "Cậu nói với anh ấy một tiếng là được. Anh ấy đã bắt đầu sau bữa tối đi dạo quanh nhà rồi.", "en": "Just mention it to him. He has already started walking around the building after dinner."}]}, {"n": 4, "zh": "短文：教授指给我看的一组数字", "vi": "Đoạn văn: Một nhóm số giáo sư chỉ cho tôi xem", "en": "Passage: A set of numbers a professor pointed out to me", "kw": ["教授", "数字", "说明", "要是", "指"], "lines": [{"s": "", "sp": [], "t": "健康课上，教授在黑板上写下几组数字，又用粉笔指着其中一行说：“你们看，坐着的时间一年比一年长。”这些数字说明，很多同学不是不知道运动，而是把运动一直往后放。要是每天能抽出二十分钟走一走，情况就会不一样。下课后我把那一行数字抄在本子上，贴在书桌前面。不是为了吓自己，只是希望一抬头就能看见：身体的事，拖不得。", "p": ["jiàn", "kāng", "kè", "shàng", "", "jiào", "shòu", "zài", "hēi", "bǎn", "shàng", "xiě", "xià", "jǐ", "zǔ", "shù", "zì", "", "yòu", "yòng", "fěn", "bǐ", "zhǐ", "zhe", "qí", "zhōng", "yì", "xíng", "shuō", "", "", "nǐ", "men", "kàn", "", "zuò", "zhe", "de", "shí", "jiān", "yì", "nián", "bǐ", "yì", "nián", "zhǎng", "", "", "zhè", "xiē", "shù", "zì", "shuō", "míng", "", "hěn", "duō", "tóng", "xué", "bú", "shì", "bù", "zhī", "dào", "yùn", "dòng", "", "ér", "shì", "bǎ", "yùn", "dòng", "yì", "zhí", "wǎng", "hòu", "fàng", "", "yào", "shi", "měi", "tiān", "néng", "chōu", "chū", "èr", "shí", "fēn", "zhōng", "zǒu", "yì", "zǒu", "", "qíng", "kuàng", "jiù", "huì", "bù", "yí", "yàng", "", "xià", "kè", "hòu", "wǒ", "bǎ", "nà", "yì", "xíng", "shù", "zì", "chāo", "zài", "běn", "zi", "shàng", "", "tiē", "zài", "shū", "zhuō", "qián", "miàn", "", "bú", "shì", "wèi", "le", "xià", "zì", "jǐ", "", "zhǐ", "shì", "xī", "wàng", "yì", "tái", "tóu", "jiù", "néng", "kàn", "jiàn", "", "shēn", "tǐ", "de", "shì", "", "tuō", "bù", "de", ""], "vi": "Trên giờ sức khỏe, giáo sư viết vài nhóm số lên bảng, rồi dùng phấn chỉ một hàng nói: «Các em nhìn, thời gian ngồi năm sau dài hơn năm trước.» Những con số ấy cho thấy nhiều bạn không phải không biết vận động, mà cứ để việc ấy về sau. Nếu mỗi ngày dành được hai mươi phút đi bộ, tình hình sẽ khác. Tan học tôi chép hàng số đó vào sổ, dán trước bàn. Không phải để tự dọa, chỉ mong ngẩng lên là thấy: việc của cơ thể không thể trì.", "en": "In the health class, the professor wrote a few sets of numbers on the blackboard, then pointed to one line with the chalk and said, \"Look: the time spent sitting is getting longer year by year.\" These numbers show that many students are not unaware of exercise; they just keep putting it off. If they could take twenty minutes every day to walk a little, the situation would be different. After class I copied that line of numbers into my notebook and stuck it in front of my desk. It was not to frighten myself, only in the hope that I would see it as soon as I looked up: you cannot put off matters of the body."}]}, {"n": 5, "zh": "短文：掉下去的不是只是体重", "vi": "Đoạn văn: Cái rơi đi không chỉ là cân nặng", "en": "Passage: It is not only the weight that drops", "kw": ["肚子", "烦恼", "感情", "减肥", "辛苦", "掉"], "lines": [{"s": "", "sp": [], "t": "我有个朋友为减肥烦了很久。她一看到肚子上的肉，烦恼就来了，连晚饭都吃不安心。后来她不再只看秤上的数字，而是每天走一段路，再少喝一杯甜的。过程当然辛苦，有一回晚上她差点放弃。可坚持了两个月，掉下去的不只是体重，还有那种一看镜子就不开心的感情。她说，身材会变，但更让她高兴的是，自己终于能跟身体好好相处。", "p": ["wǒ", "yǒu", "gè", "péng", "you", "wèi", "jiǎn", "féi", "fán", "le", "hěn", "jiǔ", "", "tā", "yí", "kàn", "dào", "dǔ", "zi", "shàng", "de", "ròu", "", "fán", "nǎo", "jiù", "lái", "le", "", "lián", "wǎn", "fàn", "dōu", "chī", "bù", "ān", "xīn", "", "hòu", "lái", "tā", "bú", "zài", "zhǐ", "kàn", "chèng", "shàng", "de", "shù", "zì", "", "ér", "shì", "měi", "tiān", "zǒu", "yí", "duàn", "lù", "", "zài", "shǎo", "hē", "yì", "bēi", "tián", "de", "", "guò", "chéng", "dāng", "rán", "xīn", "kǔ", "", "yǒu", "yì", "huí", "wǎn", "shàng", "tā", "chà", "diǎn", "fàng", "qì", "", "kě", "jiān", "chí", "le", "liǎng", "gè", "yuè", "", "diào", "xià", "qù", "de", "bù", "zhǐ", "shì", "tǐ", "zhòng", "", "hái", "yǒu", "nà", "zhǒng", "yí", "kàn", "jìng", "zi", "jiù", "bù", "kāi", "xīn", "de", "gǎn", "qíng", "", "tā", "shuō", "", "shēn", "cái", "huì", "biàn", "", "dàn", "gèng", "ràng", "tā", "gāo", "xìng", "de", "shì", "", "zì", "jǐ", "zhōng", "yú", "néng", "gēn", "shēn", "tǐ", "hǎo", "hǎo", "xiāng", "chǔ", ""], "vi": "Tôi có người bạn đã lo chuyện giảm cân rất lâu. Hễ thấy lớp mỡ trên bụng là phiền não kéo đến, cơm tối cũng không yên. Sau cô ấy không chỉ nhìn con số trên cân, mà mỗi ngày đi một đoạn, rồi bớt một ly đồ ngọt. Quá trình tất nhiên vất vả, có tối cô suýt bỏ cuộc. Nhưng kiên trì hai tháng, cái rơi đi không chỉ là cân nặng, mà cả cảm xúc khó chịu mỗi khi nhìn gương. Cô nói, dáng sẽ thay đổi, nhưng điều khiến cô vui hơn là cuối cùng mình sống được tử tế với cơ thể.", "en": "I have a friend who was troubled about losing weight for a long time. As soon as she saw the fat on her stomach, the worry arrived, and she could not even eat dinner in peace. Later she stopped looking only at the number on the scale, and instead walked a stretch every day and also drank one less sweet cup. The process was hard work, of course, and one evening she almost gave up. But after she kept it up for two months, what had dropped was not only her weight, but also that unhappy feeling she used to get as soon as she looked in the mirror. She said her figure would change, but what pleased her more was that she could finally get along properly with her own body."}]}]}, {"l": 8, "texts": [{"n": 1, "zh": "对话：阿玲买巧克力走亲戚", "vi": "Hội thoại: A Linh mua sô-cô-la đi thăm họ hàng", "en": "Dialogue: A Linh buys chocolate to visit relatives", "kw": ["巧克力", "亲戚", "伤心", "心情", "愉快", "使"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你提着这么一大盒，要去哪儿？", "p": ["nǐ", "tí", "zhe", "zhè", "me", "yí", "dà", "hé", "", "yào", "qù", "nǎ", "r", ""], "vi": "Cậu xách hộp to thế, định đi đâu?", "en": "You're carrying such a big box — where are you going?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "去看林阿姨那边的亲戚。我买了巧克力，想使他们高兴一点儿。", "p": ["qù", "kàn", "lín", "ā", "yí", "nà", "biān", "de", "qīn", "qi", "", "wǒ", "mǎi", "le", "qiǎo", "kè", "lì", "", "xiǎng", "shǐ", "tā", "men", "gāo", "xìng", "yì", "diǎn", "r", ""], "vi": "Đi thăm họ hàng bên thím Lâm. Mình mua sô-cô-la, muốn làm họ vui hơn một chút.", "en": "To see some relatives on Aunt Lin's side. I bought chocolate, hoping to make them a little happier."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "听说吃甜的能让人心情变好，是真的吗？", "p": ["tīng", "shuō", "chī", "tián", "de", "néng", "ràng", "rén", "xīn", "qíng", "biàn", "hǎo", "", "shì", "zhēn", "de", "ma", ""], "vi": "Nghe nói ăn đồ ngọt có thể khiến tâm trạng khá hơn, có thật không?", "en": "People say eating something sweet can improve your mood — is that true?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我也不敢说每次都行。不过林阿姨前阵子有点儿伤心，我见她拆开包装，脸色倒是愉快了不少。", "p": ["wǒ", "yě", "bù", "gǎn", "shuō", "měi", "cì", "dōu", "xíng", "", "bú", "guò", "lín", "ā", "yí", "qián", "zhèn", "zi", "yǒu", "diǎn", "r", "shāng", "xīn", "", "wǒ", "jiàn", "tā", "chāi", "kāi", "bāo", "zhuāng", "", "liǎn", "sè", "dào", "shì", "yú", "kuài", "le", "bù", "shǎo", ""], "vi": "Mình cũng không dám nói lần nào cũng được. Nhưng thím Lâm vừa rồi hơi buồn, mình thấy thím mở gói ra, nét mặt vui hơn hẳn.", "en": "I wouldn't dare say it works every time. But Aunt Lin was a little sad a while ago, and when I saw her unwrap it, her face did become a good deal more cheerful."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "那就好。你代我问她一声好。", "p": ["nà", "jiù", "hǎo", "", "nǐ", "dài", "wǒ", "wèn", "tā", "yì", "shēng", "hǎo", ""], "vi": "Thế thì tốt. Cậu hỏi thăm thím giúp mình một tiếng.", "en": "That's good. Please say hello to her for me."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "一定。我还买了一小袋给她孙子，免得他看见大人吃，自己没份。", "p": ["yī", "dìng", "", "wǒ", "hái", "mǎi", "le", "yì", "xiǎo", "dài", "gěi", "tā", "sūn", "zi", "", "miǎn", "de", "tā", "kàn", "jiàn", "dà", "rén", "chī", "", "zì", "jǐ", "méi", "fèn", ""], "vi": "Chắc rồi. Mình còn mua một túi nhỏ cho cháu trai thím, kẻo cháu thấy người lớn ăn mà mình không có phần.", "en": "I will. I also bought a small bag for her grandson, so he wouldn't watch the adults eat and have none himself."}]}, {"n": 2, "zh": "对话：周末在山上踢球以后", "vi": "Hội thoại: Sau trận bóng trên núi cuối tuần", "en": "Dialogue: After a game of football in the hills at the weekend", "kw": ["成为", "发生", "放松", "回忆", "景色", "压力", "只要"], "lines": [{"s": "周南", "sp": ["zhōu", "nán"], "t": "上周日那场合球，踢完你还愿意再去吗？", "p": ["shàng", "zhōu", "rì", "nà", "chǎng", "hé", "qiú", "", "tī", "wán", "nǐ", "huán", "yuàn", "yì", "zài", "qù", "ma", ""], "vi": "Chủ nhật tuần trước trận bóng ấy, đá xong cậu còn muốn đi nữa không?", "en": "After that football game last Sunday, would you still go again?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "愿意。一到山上，城市里的压力好像都放下了。只要天气还行，我都想去。", "p": ["yuàn", "yì", "", "yí", "dào", "shān", "shàng", "", "chéng", "shì", "lǐ", "de", "yā", "lì", "hǎo", "xiàng", "dōu", "fàng", "xià", "le", "", "zhǐ", "yào", "tiān", "qì", "hái", "xíng", "", "wǒ", "dōu", "xiǎng", "qù", ""], "vi": "Muốn chứ. Vừa lên núi, áp lực trong thành phố như buông hết. Chỉ cần thời tiết còn ổn là mình muốn đi.", "en": "Yes. As soon as we got up into the hills, the pressure of the city seemed to fall away. As long as the weather is all right, I'll want to go."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "中途还发生了一件有意思的事：球滚进草里，我们找了半天，结果旁边的景色倒成了最好看的一段。", "p": ["zhōng", "tú", "hái", "fā", "shēng", "le", "yí", "jiàn", "yǒu", "yì", "si", "de", "shì", "", "qiú", "gǔn", "jìn", "cǎo", "lǐ", "", "wǒ", "men", "zhǎo", "le", "bàn", "tiān", "", "jié", "guǒ", "páng", "biān", "de", "jǐng", "sè", "dào", "chéng", "le", "zuì", "hǎo", "kàn", "de", "yí", "duàn", ""], "vi": "Giữa chừng còn xảy ra một chuyện thú vị: bóng lăn vào cỏ, mình tìm mãi, hóa ra cảnh bên cạnh lại thành đoạn đẹp nhất.", "en": "Something interesting happened halfway through: the ball rolled into the grass, and we looked for it for a long time. In the end the scenery next to us turned out to be the best part."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我现在一回忆，先想起的不是比分，是大家坐在石头上喝水、放松的样子。", "p": ["wǒ", "xiàn", "zài", "yì", "huí", "yì", "", "xiān", "xiǎng", "qǐ", "de", "bú", "shì", "bǐ", "fēn", "", "shì", "dà", "jiā", "zuò", "zài", "shí", "tou", "shàng", "hē", "shuǐ", "", "fàng", "sōng", "de", "yàng", "zi", ""], "vi": "Giờ mình vừa hồi tưởng, điều nhớ trước không phải tỉ số, mà là mọi người ngồi trên đá uống nước, thư giãn.", "en": "When I look back now, the first thing I recall is not the score, but everyone sitting on the rocks, drinking water and relaxing."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "那就这么说定：下次还去。谁输了，谁买饮料。", "p": ["nà", "jiù", "zhè", "me", "shuō", "dìng", "", "xià", "cì", "hái", "qù", "", "shuí", "shū", "le", "", "shuí", "mǎi", "yǐn", "liào", ""], "vi": "Vậy chốt vậy: lần sau vẫn đi. Ai thua thì người ấy mua nước.", "en": "Then it's settled: we'll go again next time. Whoever loses buys the drinks."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "好。能成为每周一次的活动，也不错。", "p": ["hǎo", "", "néng", "chéng", "wéi", "měi", "zhōu", "yí", "cì", "de", "huó", "dòng", "", "yě", "bú", "cuò", ""], "vi": "Được. Trở thành hoạt động mỗi tuần một lần cũng hay.", "en": "All right. It wouldn't be bad if it became a once-a-week activity."}]}, {"n": 3, "zh": "对话：程师傅送阿玲去办事", "vi": "Hội thoại: Bác Trình đưa A Linh đi làm việc", "en": "Dialogue: Master Cheng drives A Linh on an errand", "kw": ["大使馆", "堵车", "距离", "耐心", "师傅"], "lines": [{"s": "程师傅", "sp": ["chéng", "shī", "fu"], "t": "姑娘，今天路上堵车，可能要比平时多花二十分钟。", "p": ["gū", "niáng", "", "jīn", "tiān", "lù", "shàng", "dǔ", "chē", "", "kě", "néng", "yào", "bǐ", "píng", "shí", "duō", "huā", "èr", "shí", "fēn", "zhōng", ""], "vi": "Cô gái, hôm nay đường tắc, có lẽ mất hơn bình thường hai mươi phút.", "en": "Miss, the traffic is jammed today. It may take twenty minutes more than usual."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "没关系，师傅。我去大使馆交材料，时间还来得及。", "p": ["méi", "guān", "xì", "", "shī", "fu", "", "wǒ", "qù", "dà", "shǐ", "guǎn", "jiāo", "cái", "liào", "", "shí", "jiān", "hái", "lái", "de", "jí", ""], "vi": "Không sao, bác. Em đến đại sứ quán nộp hồ sơ, thời gian vẫn kịp.", "en": "That's all right, Master. I'm going to the embassy to hand in some papers, and there's still time."}, {"s": "程师傅", "sp": ["chéng", "shī", "fu"], "t": "从这儿到大使馆距离不远，就是这几盏灯特别慢。您再耐心等一等。", "p": ["cóng", "zhè", "r", "dào", "dà", "shǐ", "guǎn", "jù", "lí", "bù", "yuǎn", "", "jiù", "shì", "zhè", "jǐ", "zhǎn", "dēng", "tè", "bié", "màn", "", "nín", "zài", "nài", "xīn", "děng", "yì", "děng", ""], "vi": "Từ đây tới đại sứ quán khoảng cách không xa, chỉ mấy đèn này chậm đặc biệt. Cô kiên nhẫn đợi thêm.", "en": "The distance from here to the embassy isn't far; it's just that these lights are especially slow. Please be patient a little longer."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我就坐着看窗外。您开这么稳，我倒不着急了。", "p": ["wǒ", "jiù", "zuò", "zhe", "kàn", "chuāng", "wài", "", "nín", "kāi", "zhè", "me", "wěn", "", "wǒ", "dào", "bù", "zháo", "jí", "le", ""], "vi": "Em ngồi nhìn ra cửa sổ. Bác lái vững thế, em lại không nóng ruột nữa.", "en": "I'll just sit and look out of the window. You drive so steadily that I'm not in a hurry any more."}, {"s": "程师傅", "sp": ["chéng", "shī", "fu"], "t": "前头车一动，我们就走。您把材料放好，别掉了。", "p": ["qián", "tou", "chē", "yí", "dòng", "", "wǒ", "men", "jiù", "zǒu", "", "nín", "bǎ", "cái", "liào", "fàng", "hǎo", "", "bié", "diào", "le", ""], "vi": "Xe phía trước vừa nhúc, mình đi. Cô để hồ sơ cho chắc, đừng rơi.", "en": "As soon as the car in front moves, we'll go. Keep those papers safe so they don't fall."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "已经放进包里了。谢谢师傅。", "p": ["yǐ", "jīng", "fàng", "jìn", "bāo", "lǐ", "le", "", "xiè", "xiè", "shī", "fu", ""], "vi": "Để vào túi rồi. Cảm ơn bác.", "en": "They're already in my bag. Thank you, Master."}]}, {"n": 4, "zh": "短文：路边也能看见的东西", "vi": "Đoạn văn: Thứ cũng thấy được bên đường", "en": "Passage: Things you can also see by the roadside", "kw": ["到处", "缺少", "生命", "态度", "因此"], "lines": [{"s": "", "sp": [], "t": "以前我觉得美只在风景区里，后来才发现，它到处都是。楼下的老树，公交站那盆花，甚至雨后地上的一小摊水，都有自己的样子。生活并不缺少可看的东西，缺少的常常是停一下的态度。因此我现在出门会走得慢一些。不是每条路都有名，可每一条路上都有正在进行的生命。只要愿意看，平凡的早晨也能让人觉得不普通。", "p": ["yǐ", "qián", "wǒ", "jué", "de", "měi", "zhǐ", "zài", "fēng", "jǐng", "qū", "lǐ", "", "hòu", "lái", "cái", "fā", "xiàn", "", "tā", "dào", "chù", "dōu", "shì", "", "lóu", "xià", "de", "lǎo", "shù", "", "gōng", "jiāo", "zhàn", "nà", "pén", "huā", "", "shèn", "zhì", "yǔ", "hòu", "dì", "shàng", "de", "yì", "xiǎo", "tān", "shuǐ", "", "dōu", "yǒu", "zì", "jǐ", "de", "yàng", "zi", "", "shēng", "huó", "bìng", "bù", "quē", "shǎo", "kě", "kàn", "de", "dōng", "xi", "", "quē", "shǎo", "de", "cháng", "cháng", "shì", "tíng", "yí", "xià", "de", "tài", "dù", "", "yīn", "cǐ", "wǒ", "xiàn", "zài", "chū", "mén", "huì", "zǒu", "de", "màn", "yì", "xiē", "", "bú", "shì", "měi", "tiáo", "lù", "dōu", "yǒu", "míng", "", "kě", "měi", "yì", "tiáo", "lù", "shàng", "dōu", "yǒu", "zhèng", "zài", "jìn", "xíng", "de", "shēng", "mìng", "", "zhǐ", "yào", "yuàn", "yì", "kàn", "", "píng", "fán", "de", "zǎo", "chén", "yě", "néng", "ràng", "rén", "jué", "de", "bù", "pǔ", "tōng", ""], "vi": "Trước tôi nghĩ cái đẹp chỉ ở khu thắng cảnh, sau mới thấy nó ở khắp nơi. Cây già dưới nhà, chậu hoa ở trạm xe, thậm chí một vũng nước nhỏ trên đất sau cơn mưa, đều có dáng của mình. Cuộc sống không thiếu thứ đáng nhìn, cái thường thiếu là thái độ dừng lại một chút. Vì thế giờ tôi ra khỏi cửa đi chậm hơn. Không phải con đường nào cũng nổi tiếng, nhưng đường nào cũng có sự sống đang diễn ra. Chỉ cần muốn nhìn, một sáng bình thường cũng có thể khiến người ta thấy không tầm thường.", "en": "I used to feel that beauty existed only in scenic spots. Later I found that it is everywhere. The old tree downstairs, the pot of flowers at the bus stop, even a small puddle on the ground after rain, each has a look of its own. Life does not lack things worth looking at; what is often lacking is the attitude of pausing for a moment. Therefore I now walk a little more slowly when I go out. Not every road is famous, but on every road there is life going on. If you are willing to look, an ordinary morning can also feel uncommon."}]}, {"n": 5, "zh": "短文：阳光下的好心情，也要自己找", "vi": "Đoạn văn: Tâm trạng tốt dưới ánh nắng cũng cần tự tìm", "en": "Passage: A good mood in the sunshine is also something you find for yourself", "kw": ["积极", "科学", "特点", "往往", "阳光", "证明"], "lines": [{"s": "", "sp": [], "t": "有人说，心情好不好，要看当天有没有阳光。这话只说对了一半。科学研究并不能证明每一个晴天都会让人愉快，它只能说明：阳光往往使人更想出门。真正起作用的，是你出不出去、跟谁说话、用什么样的态度对待麻烦。积极的人有一个特点，不是从不遇到烦事，而是遇到了还肯再试一次。心情不会从天上掉下来，可它会在你迈出门的那一步里慢慢出现。", "p": ["yǒu", "rén", "shuō", "", "xīn", "qíng", "hǎo", "bù", "hǎo", "", "yào", "kàn", "dàng", "tiān", "yǒu", "méi", "yǒu", "yáng", "guāng", "", "zhè", "huà", "zhǐ", "shuō", "duì", "le", "yí", "bàn", "", "kē", "xué", "yán", "jiū", "bìng", "bù", "néng", "zhèng", "míng", "měi", "yí", "gè", "qíng", "tiān", "dōu", "huì", "ràng", "rén", "yú", "kuài", "", "tā", "zhǐ", "néng", "shuō", "míng", "", "yáng", "guāng", "wǎng", "wǎng", "shǐ", "rén", "gèng", "xiǎng", "chū", "mén", "", "zhēn", "zhèng", "qǐ", "zuò", "yòng", "de", "", "shì", "nǐ", "chū", "bù", "chū", "qù", "", "gēn", "shuí", "shuō", "huà", "", "yòng", "shén", "me", "yàng", "de", "tài", "dù", "duì", "dài", "má", "fan", "", "jī", "jí", "de", "rén", "yǒu", "yí", "gè", "tè", "diǎn", "", "bú", "shì", "cóng", "bú", "yù", "dào", "fán", "shì", "", "ér", "shì", "yù", "dào", "le", "hái", "kěn", "zài", "shì", "yí", "cì", "", "xīn", "qíng", "bú", "huì", "cóng", "tiān", "shàng", "diào", "xià", "lái", "", "kě", "tā", "huì", "zài", "nǐ", "mài", "chū", "mén", "de", "nà", "yí", "bù", "lǐ", "màn", "màn", "chū", "xiàn", ""], "vi": "Có người nói tâm trạng tốt hay không là nhìn hôm ấy có ánh nắng hay không. Câu ấy đúng có một nửa. Nghiên cứu khoa học không thể chứng minh ngày nắng nào cũng làm người ta vui, nó chỉ cho thấy: ánh nắng thường khiến người ta muốn ra khỏi cửa hơn. Điều thật sự có tác dụng là bạn có ra ngoài không, nói với ai, lấy thái độ thế nào trước chuyện phiền. Người tích cực có một đặc điểm, không phải không gặp chuyện buồn, mà gặp rồi vẫn chịu thử thêm lần nữa. Tâm trạng không rơi từ trên trời, nhưng nó sẽ dần xuất hiện trong bước bạn bước ra cửa.", "en": "Some people say whether you are in a good mood depends on whether there is sunshine that day. That is only half right. Scientific research cannot prove that every clear day will make a person cheerful; it can only show that sunshine often makes people more inclined to go out. What really makes a difference is whether you go out, who you talk to, and what attitude you take toward trouble. A positive person has one characteristic: it is not that they never meet anything annoying, but that when they do, they are still willing to try once more. A mood will not fall from the sky, but it will slowly appear in the step you take out of the door."}]}]}, {"l": 9, "texts": [{"n": 1, "zh": "对话：小雪又为零食发愁", "vi": "Hội thoại: Tiểu Tuyết lại lo vì đồ ăn vặt", "en": "Dialogue: Xiaoxue is worried about snacks again", "kw": ["饼干", "放弃", "坚持", "难道", "主意", "得"], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "你怎么把饼干放到柜子最上面了？", "p": ["nǐ", "zěn", "me", "bǎ", "bǐng", "gān", "fàng", "dào", "guì", "zi", "zuì", "shàng", "miàn", "le", ""], "vi": "Sao cậu để bánh quy lên tầng cao nhất của tủ?", "en": "Why have you put the biscuits on the very top shelf of the cupboard?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "我得少吃点儿。一打开包装就停不下来，我难道还要每周都后悔一次吗？", "p": ["wǒ", "děi", "shǎo", "chī", "diǎn", "r", "", "yì", "dǎ", "kāi", "bāo", "zhuāng", "jiù", "tíng", "bú", "xià", "lái", "", "wǒ", "nán", "dào", "hái", "yào", "měi", "zhōu", "dōu", "hòu", "huǐ", "yí", "cì", "ma", ""], "vi": "Mình phải ăn ít thôi. Hễ mở gói là không dừng được, chẳng lẽ tuần nào cũng phải hối một lần sao?", "en": "I have to eat a little less. Once I open a pack I can't stop. Do I really have to regret it every week?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "那你就一下子放弃所有零食？怕是坚持不了几天。", "p": ["nà", "nǐ", "jiù", "yí", "xià", "zi", "fàng", "qì", "suǒ", "yǒu", "líng", "shí", "", "pà", "shì", "jiān", "chí", "bù", "liǎo", "jǐ", "tiān", ""], "vi": "Vậy cậu bỏ hết mọi món vặt một lúc? E không kiên trì được vài ngày.", "en": "So you're going to give up all snacks in one go? I'm afraid you won't last more than a few days."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "我也这么想。你有没有更好的主意？", "p": ["wǒ", "yě", "zhè", "me", "xiǎng", "", "nǐ", "yǒu", "méi", "yǒu", "gèng", "hǎo", "de", "zhǔ", "yi", ""], "vi": "Mình cũng nghĩ vậy. Cậu có ý hay hơn không?", "en": "I think so too. Have you got a better idea?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "每天只留两块饼干，其余的先不买。想吃的时候先喝杯水，再决定还要不要打开柜子。", "p": ["měi", "tiān", "zhǐ", "liú", "liǎng", "kuài", "bǐng", "gān", "", "qí", "yú", "de", "xiān", "bù", "mǎi", "", "xiǎng", "chī", "de", "shí", "hòu", "xiān", "hē", "bēi", "shuǐ", "", "zài", "jué", "dìng", "hái", "yào", "bú", "yào", "dǎ", "kāi", "guì", "zi", ""], "vi": "Mỗi ngày chỉ để lại hai cái bánh, còn lại đừng mua vội. Lúc muốn ăn thì uống một ly nước đã, rồi mới quyết có mở tủ hay không.", "en": "Keep only two biscuits each day, and don't buy the rest for now. When you want some, drink a glass of water first, and then decide whether to open the cupboard."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "这主意我可以试试。从今天开始，我得坚持两周看看。", "p": ["zhè", "zhǔ", "yi", "wǒ", "kě", "yǐ", "shì", "shì", "", "cóng", "jīn", "tiān", "kāi", "shǐ", "", "wǒ", "děi", "jiān", "chí", "liǎng", "zhōu", "kàn", "kàn", ""], "vi": "Ý này mình thử được. Từ hôm nay, mình phải kiên trì hai tuần xem sao.", "en": "I can try that idea. Starting today, I have to keep it up for two weeks and see."}]}, {"n": 2, "zh": "对话：周南的网球又赢了", "vi": "Hội thoại: Châu Nam lại thắng trận quần vợt", "en": "Dialogue: Zhou Nan has won at tennis again", "kw": ["国际", "轻松", "随便", "通过", "网球", "汗", "赢"], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "看你衬衫都湿了，刚打完网球？", "p": ["kàn", "nǐ", "chèn", "shān", "dōu", "shī", "le", "", "gāng", "dǎ", "wán", "wǎng", "qiú", ""], "vi": "Áo cậu ướt hết, vừa đánh quần vợt xong à?", "en": "Your shirt is soaked — have you just finished tennis?"}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "对。今天赢了两局，汗都来不及擦。不过真不轻松，对方也是校队的。", "p": ["duì", "", "jīn", "tiān", "yíng", "le", "liǎng", "jú", "", "hàn", "dōu", "lái", "bu", "jí", "cā", "", "bú", "guò", "zhēn", "bù", "qīng", "sōng", "", "duì", "fāng", "yě", "shì", "xiào", "duì", "de", ""], "vi": "Đúng. Hôm nay thắng hai ván, mồ hôi còn chưa kịp lau. Nhưng chẳng thoải mái gì, đối phương cũng là đội trường.", "en": "Yes. I won two sets today, and I had no time to wipe the sweat. But it was really not easy. The other player is on the school team too."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "你怎么进步这么快？是不是有什么特别的方法？", "p": ["nǐ", "zěn", "me", "jìn", "bù", "zhè", "me", "kuài", "", "shì", "bú", "shì", "yǒu", "shén", "me", "tè", "bié", "de", "fāng", "fǎ", ""], "vi": "Sao cậu tiến bộ nhanh thế? Có cách gì đặc biệt không?", "en": "How have you improved so quickly? Is there some special method?"}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "没有什么随便就能赢的办法。我每周通过三次训练，把基本动作练熟，再看一些国际比赛的录像。", "p": ["méi", "yǒu", "shén", "me", "suí", "biàn", "jiù", "néng", "yíng", "de", "bàn", "fǎ", "", "wǒ", "měi", "zhōu", "tōng", "guò", "sān", "cì", "xùn", "liàn", "", "bǎ", "jī", "běn", "dòng", "zuò", "liàn", "shú", "", "zài", "kàn", "yì", "xiē", "guó", "jì", "bǐ", "sài", "de", "lù", "xiàng", ""], "vi": "Không có cách nào tùy tiện là thắng. Mỗi tuần mình trải ba buổi tập, luyện thuần động tác cơ bản, rồi xem vài băng giải quốc tế.", "en": "There is no way to win just casually. I get through three training sessions a week, practise the basic movements until they're familiar, and also watch some recordings of international matches."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "听着就累。你下次练习，我可不可以去看看？", "p": ["tīng", "zhe", "jiù", "lèi", "", "nǐ", "xià", "cì", "liàn", "xí", "", "wǒ", "kě", "bù", "kě", "yǐ", "qù", "kàn", "kàn", ""], "vi": "Nghe đã thấy mệt. Lần sau cậu tập, mình có thể đến xem được không?", "en": "It sounds tiring already. May I come and watch next time you practise?"}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "可以。你要是也想试试，我借你一副球拍。", "p": ["kě", "yǐ", "", "nǐ", "yào", "shi", "yě", "xiǎng", "shì", "shì", "", "wǒ", "jiè", "nǐ", "yí", "fù", "qiú", "pāi", ""], "vi": "Được. Nếu cậu cũng muốn thử, mình cho mượn một vợt.", "en": "Yes. If you'd like to try as well, I'll lend you a racket."}]}, {"n": 3, "zh": "对话：陈晓想当作家", "vi": "Hội thoại: Trần Hiểu muốn làm nhà văn", "en": "Dialogue: Chen Xiao wants to be a writer", "kw": ["当时", "可是", "理想", "正确", "作家", "篇"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "陈晓又在本子上写什么？都这么晚了。", "p": ["chén", "xiǎo", "yòu", "zài", "běn", "zi", "shàng", "xiě", "shén", "me", "", "dōu", "zhè", "me", "wǎn", "le", ""], "vi": "Trần Hiểu lại viết gì trong sổ thế? Muộn vậy rồi.", "en": "What's Chen Xiao writing in his notebook again? It's so late."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "一篇短故事。他的理想是以后做作家，可是现在写得很慢，一篇要改很多遍。", "p": ["yī", "piān", "duǎn", "gù", "shì", "", "tā", "de", "lǐ", "xiǎng", "shì", "yǐ", "hòu", "zuò", "zuò", "jiā", "", "kě", "shì", "xiàn", "zài", "xiě", "de", "hěn", "màn", "", "yì", "piān", "yào", "gǎi", "hěn", "duō", "biàn", ""], "vi": "Một truyện ngắn. Lý tưởng của anh ấy là sau này làm nhà văn, nhưng giờ viết rất chậm, một bài phải sửa rất nhiều lần.", "en": "A short story. His ideal is to become a writer one day, but he writes very slowly now, and a single piece has to be revised many times."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "当时他不是说先找一份稳定的工作吗？", "p": ["dāng", "shí", "tā", "bú", "shì", "shuō", "xiān", "zhǎo", "yí", "fèn", "wěn", "dìng", "de", "gōng", "zuò", "ma", ""], "vi": "Lúc ấy chẳng phải anh ấy nói tìm một việc ổn định trước sao?", "en": "Didn't he say at the time that he would find a steady job first?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "他说那也正确，晚上和周末仍然可以写。这样生活和理想都能顾上。", "p": ["tā", "shuō", "nà", "yě", "zhèng", "què", "", "wǎn", "shàng", "hé", "zhōu", "mò", "réng", "rán", "kě", "yǐ", "xiě", "", "zhè", "yàng", "shēng", "huó", "hé", "lǐ", "xiǎng", "dōu", "néng", "gù", "shàng", ""], "vi": "Anh ấy bảo điều đó cũng đúng, tối và cuối tuần vẫn viết được. Như vậy đời sống và lý tưởng đều giữ được.", "en": "He said that was correct too, and that he could still write in the evenings and at weekends. That way he can look after both his life and his ideal."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "那倒实在。等他写完这篇，我们帮忙看看。", "p": ["nà", "dào", "shí", "zài", "", "děng", "tā", "xiě", "wán", "zhè", "piān", "", "wǒ", "men", "bāng", "máng", "kàn", "kàn", ""], "vi": "Thế thì thực tế. Đợi anh ấy viết xong bài này, mình xem giúp.", "en": "That's practical. When he finishes this piece, we can help by reading it."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "他已经答应了。他说最怕写完没人读。", "p": ["tā", "yǐ", "jīng", "dā", "yìng", "le", "", "tā", "shuō", "zuì", "pà", "xiě", "wán", "méi", "rén", "dú", ""], "vi": "Anh ấy đã đồng ý. Anh ấy bảo sợ nhất là viết xong chẳng ai đọc.", "en": "He's already agreed. He said what he fears most is finishing a piece and having no one read it."}]}, {"n": 4, "zh": "短文：一次陶艺课给我的总结", "vi": "Đoạn văn: Một bài tổng kết từ giờ gốm", "en": "Passage: A summary a pottery class gave me", "kw": ["过程", "结果", "失败", "勇敢", "至少", "总结"], "lines": [{"s": "", "sp": [], "t": "第一次上陶艺课，我满心想做出一只漂亮的杯子。结果杯子歪了，还裂了一道。我当时觉得这就是失败。老师却让我把过程再走一遍：土要揉匀，手要稳，火也不能太急。第二次仍然不完美，可至少不再裂开。后来我给自己做了一个总结：结果当然重要，可真正让人进步的，是你敢在失败以后再勇敢地坐回去，把每一步重新做认真。那只歪杯子我还留着，为的是记得那一课。", "p": ["dì", "yī", "cì", "shàng", "táo", "yì", "kè", "", "wǒ", "mǎn", "xīn", "xiǎng", "zuò", "chū", "yì", "zhī", "piào", "liàng", "de", "bēi", "zi", "", "jié", "guǒ", "bēi", "zi", "wāi", "le", "", "hái", "liè", "le", "yí", "dào", "", "wǒ", "dāng", "shí", "jué", "de", "zhè", "jiù", "shì", "shī", "bài", "", "lǎo", "shī", "què", "ràng", "wǒ", "bǎ", "guò", "chéng", "zài", "zǒu", "yí", "biàn", "", "tǔ", "yào", "róu", "yún", "", "shǒu", "yào", "wěn", "", "huǒ", "yě", "bù", "néng", "tài", "jí", "", "dì", "èr", "cì", "réng", "rán", "bù", "wán", "měi", "", "kě", "zhì", "shǎo", "bú", "zài", "liè", "kāi", "", "hòu", "lái", "wǒ", "gěi", "zì", "jǐ", "zuò", "le", "yí", "gè", "zǒng", "jié", "", "jié", "guǒ", "dāng", "rán", "zhòng", "yào", "", "kě", "zhēn", "zhèng", "ràng", "rén", "jìn", "bù", "de", "", "shì", "nǐ", "gǎn", "zài", "shī", "bài", "yǐ", "hòu", "zài", "yǒng", "gǎn", "dì", "zuò", "huí", "qù", "", "bǎ", "měi", "yí", "bù", "chóng", "xīn", "zuò", "rèn", "zhēn", "", "nà", "zhǐ", "wāi", "bēi", "zi", "wǒ", "hái", "liú", "zhe", "", "wèi", "de", "shì", "jì", "de", "nà", "yí", "kè", ""], "vi": "Lần đầu học gốm, tôi chỉ nghĩ làm cho được một cái cốc đẹp. Kết quả cốc lệch, lại nứt một đường. Lúc ấy tôi thấy đó là thất bại. Giáo viên lại bảo tôi đi lại quá trình: đất phải nhào đều, tay phải vững, lửa cũng đừng vội. Lần hai vẫn chưa hoàn hảo, nhưng ít nhất không nứt nữa. Sau tôi tự viết một bài tổng kết: kết quả cố nhiên quan trọng, nhưng điều thật sự giúp người ta tiến bộ là dám, sau thất bại, dũng cảm ngồi lại, làm lại từng bước cho tử tế. Cái cốc lệch ấy tôi vẫn giữ, để nhớ buổi học đó.", "en": "The first time I went to a pottery class, all I wanted was to make a handsome cup. The result was that the cup came out crooked and also cracked along one line. At the time I felt that this was failure. The teacher, however, had me go through the process again: the clay had to be kneaded evenly, the hands had to be steady, and the fire could not be too hasty. The second try was still not perfect, but at least it no longer cracked. Later I wrote a summary for myself: the result is important, of course, but what really helps you improve is daring, after a failure, to sit back down bravely and do each step carefully once more. I still keep that crooked cup, so that I will remember the lesson."}]}, {"n": 5, "zh": "短文：暂时落后的时候", "vi": "Đoạn văn: Lúc tạm thời bị tụt lại", "en": "Passage: When you are temporarily behind", "kw": ["经历", "区别", "许多", "暂时", "取"], "lines": [{"s": "", "sp": [], "t": "比赛或考试里，暂时落后是许多人都会有的经历。有人一看见分数不高就停手，有人却会先看别人好在哪里，再取其中对自己有用的一点。这两种态度的区别，不在聪不聪明，而在你还肯不肯再看一眼自己的练习。我以前也急着跟前面的人比，后来才发现，许多弯路都是自己走出来的。把别人的方法取来试一试，再把不适合的放下，路会安静得多。", "p": ["bǐ", "sài", "huò", "kǎo", "shì", "lǐ", "", "zàn", "shí", "luò", "hòu", "shì", "xǔ", "duō", "rén", "dōu", "huì", "yǒu", "de", "jīng", "lì", "", "yǒu", "rén", "yí", "kàn", "jiàn", "fēn", "shù", "bù", "gāo", "jiù", "tíng", "shǒu", "", "yǒu", "rén", "què", "huì", "xiān", "kàn", "bié", "rén", "hǎo", "zài", "nǎ", "lǐ", "", "zài", "qǔ", "qí", "zhōng", "duì", "zì", "jǐ", "yǒu", "yòng", "de", "yì", "diǎn", "", "zhè", "liǎng", "zhǒng", "tài", "dù", "de", "qū", "bié", "", "bú", "zài", "cōng", "bù", "cōng", "míng", "", "ér", "zài", "nǐ", "hái", "kěn", "bù", "kěn", "zài", "kàn", "yì", "yǎn", "zì", "jǐ", "de", "liàn", "xí", "", "wǒ", "yǐ", "qián", "yě", "jí", "zhe", "gēn", "qián", "miàn", "de", "rén", "bǐ", "", "hòu", "lái", "cái", "fā", "xiàn", "", "xǔ", "duō", "wān", "lù", "dōu", "shì", "zì", "jǐ", "zǒu", "chū", "lái", "de", "", "bǎ", "bié", "rén", "de", "fāng", "fǎ", "qǔ", "lái", "shì", "yí", "shì", "", "zài", "bǎ", "bú", "shì", "hé", "de", "fàng", "xià", "", "lù", "huì", "ān", "jìng", "de", "duō", ""], "vi": "Trong thi đấu hay kỳ thi, việc tạm thời bị tụt lại là trải nghiệm nhiều người đều có. Có người vừa thấy điểm không cao đã dừng tay, có người lại nhìn người khác hay ở chỗ nào, rồi lấy một điểm hữu ích cho mình. Sự khác nhau của hai thái độ ấy không ở thông minh hay không, mà ở chỗ bạn còn chịu nhìn lại bài tập của mình hay không. Trước tôi cũng sốt ruột so với người đi trước, sau mới thấy nhiều đoạn vòng là tự mình đi ra. Lấy cách của người khác về thử, rồi đặt xuống những gì không hợp, đường sẽ yên hơn nhiều.", "en": "In a contest or an exam, being temporarily behind is an experience many people have. Some people stop as soon as they see a low score; others first look at what someone else does well, and then take from it one point that is useful to themselves. The difference between these two attitudes is not about how clever you are, but about whether you are still willing to look at your own practice once more. I used to be in a hurry to compare myself with the people in front; only later did I find that many of the detours were ones I had taken myself. If you take other people's methods and try them, and then put down what does not suit you, the road becomes much quieter."}]}]}, {"l": 10, "texts": [{"n": 1, "zh": "对话：礼拜天阿玲陪母亲出门", "vi": "Hội thoại: Ngày chủ nhật A Linh đi cùng mẹ", "en": "Dialogue: On Sunday A Linh goes out with her mother", "kw": ["礼拜天", "不过", "方向", "空儿", "母亲", "永远"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "今天礼拜天，你怎么起得这么早？", "p": ["jīn", "tiān", "lǐ", "bài", "tiān", "", "nǐ", "zěn", "me", "qǐ", "de", "zhè", "me", "zǎo", ""], "vi": "Hôm nay chủ nhật, sao cậu dậy sớm thế?", "en": "It's Sunday today — why did you get up so early?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我陪母亲去公园。她说平时没什么空儿，只有这一天走得比较慢。", "p": ["wǒ", "péi", "mǔ", "qin", "qù", "gōng", "yuán", "", "tā", "shuō", "píng", "shí", "méi", "shén", "me", "kòng", "r", "", "zhǐ", "yǒu", "zhè", "yì", "tiān", "zǒu", "de", "bǐ", "jiào", "màn", ""], "vi": "Mình đi công viên với mẹ. Mẹ bảo bình thường chẳng có chút thì giờ nào, chỉ ngày này đi chậm hơn được.", "en": "I'm going to the park with my mother. She says she doesn't usually have a spare moment, and only on this day can she walk a little more slowly."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "那挺好。你们还去别的地方吗？", "p": ["nà", "tǐng", "hǎo", "", "nǐ", "men", "hái", "qù", "bié", "de", "dì", "fāng", "ma", ""], "vi": "Thế thì hay. Hai mẹ con còn đi chỗ khác nữa không?", "en": "That's nice. Are you going anywhere else as well?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "先往湖那边走。不过要是太阳太大，我们就换个方向，去有树荫的那条路。", "p": ["xiān", "wǎng", "hú", "nà", "biān", "zǒu", "", "bú", "guò", "yào", "shi", "tài", "yáng", "tài", "dà", "", "wǒ", "men", "jiù", "huàn", "gè", "fāng", "xiàng", "", "qù", "yǒu", "shù", "yīn", "de", "nà", "tiáo", "lù", ""], "vi": "Đi về phía hồ trước. Nhưng nếu nắng quá thì mình đổi hướng, sang con đường có bóng cây.", "en": "We'll head toward the lake first. But if the sun is too strong, we'll change direction and take the path with the tree shade."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "替我问阿姨好。她做的汤，我永远都记得。", "p": ["tì", "wǒ", "wèn", "ā", "yí", "hǎo", "", "tā", "zuò", "de", "tāng", "", "wǒ", "yǒng", "yuǎn", "dōu", "jì", "de", ""], "vi": "Nhờ cậu hỏi thăm thím. Món canh thím nấu, mình nhớ mãi.", "en": "Please say hello to your mother for me. I'll always remember the soup she makes."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "一定。晚上要是你有空儿，来家里喝一碗。", "p": ["yī", "dìng", "", "wǎn", "shàng", "yào", "shi", "nǐ", "yǒu", "kòng", "r", "", "lái", "jiā", "lǐ", "hē", "yì", "wǎn", ""], "vi": "Chắc rồi. Tối nếu cậu rảnh, đến nhà uống một bát.", "en": "I will. If you have a moment this evening, come over to the house for a bowl."}]}, {"n": 2, "zh": "对话：两位老师谈同事的新消息", "vi": "Hội thoại: Hai giáo viên nói về tin mới của đồng nghiệp", "en": "Dialogue: Two teachers talk about a colleague's news", "kw": ["翻译", "确实", "硕士", "兴奋", "优秀", "拉"], "lines": [{"s": "赵老师", "sp": ["zhào", "lǎo", "shī"], "t": "林老师，您听说了吗？王老师的硕士论文通过了。", "p": ["lín", "lǎo", "shī", "", "nín", "tīng", "shuō", "le", "ma", "", "wáng", "lǎo", "shī", "de", "shuò", "shì", "lùn", "wén", "tōng", "guò", "le", ""], "vi": "Thầy Lâm, thầy nghe tin chưa? Cô Vương đã bảo vệ xong luận văn thạc sĩ.", "en": "Mr. Lin, have you heard? Ms. Wang's master's thesis has been passed."}, {"s": "林老师", "sp": ["lín", "lǎo", "shī"], "t": "听说了。她研究的是翻译，课又上得好，确实优秀。", "p": ["tīng", "shuō", "le", "", "tā", "yán", "jiū", "de", "shì", "fān", "yì", "", "kè", "yòu", "shàng", "de", "hǎo", "", "què", "shí", "yōu", "xiù", ""], "vi": "Nghe rồi. Cô ấy nghiên cứu biên dịch, dạy cũng giỏi, quả thật xuất sắc.", "en": "I have. She works on translation, and she teaches well too. She is excellent, she really is."}, {"s": "赵老师", "sp": ["zhào", "lǎo", "shī"], "t": "消息一传开，办公室里都兴奋起来。下午她还要拉一段小提琴给大家听。", "p": ["xiāo", "xi", "yì", "chuán", "kāi", "", "bàn", "gōng", "shì", "lǐ", "dōu", "xīng", "fèn", "qǐ", "lái", "", "xià", "wǔ", "tā", "hái", "yào", "lā", "yí", "duàn", "xiǎo", "tí", "qín", "gěi", "dà", "jiā", "tīng", ""], "vi": "Tin vừa loan, cả phòng đều hào hứng. Chiều cô ấy còn kéo một khúc vĩ cầm cho mọi người nghe.", "en": "As soon as the news spread, the whole office got excited. This afternoon she is even going to play a piece on the violin for everyone."}, {"s": "林老师", "sp": ["lín", "lǎo", "shī"], "t": "那我一定去。她一拉琴，整个楼道都安静了。", "p": ["nà", "wǒ", "yí", "dìng", "qù", "", "tā", "yì", "lā", "qín", "", "zhěng", "gè", "lóu", "dào", "dōu", "ān", "jìng", "le", ""], "vi": "Thế thì tôi nhất định đến. Cô ấy vừa kéo đàn là cả hành lang im hết.", "en": "Then I shall certainly go. As soon as she starts to play, the whole corridor goes quiet."}, {"s": "赵老师", "sp": ["zhào", "lǎo", "shī"], "t": "是啊。能把课、论文和琴都照顾好，真不容易。", "p": ["shì", "a", "", "néng", "bǎ", "kè", "", "lùn", "wén", "hé", "qín", "dōu", "zhào", "gù", "hǎo", "", "zhēn", "bù", "róng", "yì", ""], "vi": "Phải. Giữ được cả giờ dạy, luận văn lẫn đàn, thật không dễ.", "en": "Yes. Managing to look after her classes, her thesis and the violin is really not easy."}, {"s": "林老师", "sp": ["lín", "lǎo", "shī"], "t": "我们准备一束花吧，让她一进门就能看见。", "p": ["wǒ", "men", "zhǔn", "bèi", "yí", "shù", "huā", "ba", "", "ràng", "tā", "yí", "jìn", "mén", "jiù", "néng", "kàn", "jiàn", ""], "vi": "Mình chuẩn bị một bó hoa, để cô ấy vừa vào cửa đã thấy.", "en": "Let's get a bunch of flowers ready, so she can see them as soon as she comes in."}]}, {"n": 3, "zh": "对话：陈晓为将来的工作发愁", "vi": "Hội thoại: Trần Hiểu lo việc làm cho tương lai", "en": "Dialogue: Chen Xiao worries about a job for the future", "kw": ["发展", "关键", "建议", "将来", "职业", "困", "躺"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "陈晓中午怎么不吃饭，躺在宿舍里？", "p": ["chén", "xiǎo", "zhōng", "wǔ", "zěn", "me", "bù", "chī", "fàn", "", "tǎng", "zài", "sù", "shè", "lǐ", ""], "vi": "Buổi trưa Trần Hiểu sao không ăn, nằm trong ký túc xá?", "en": "Why didn't Chen Xiao have lunch? Why is he lying in the dorm?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "他昨晚想将来的职业，想得太困了，今早又爬起来改简历。", "p": ["tā", "zuó", "wǎn", "xiǎng", "jiāng", "lái", "de", "zhí", "yè", "", "xiǎng", "de", "tài", "kùn", "le", "", "jīn", "zǎo", "yòu", "pá", "qǐ", "lái", "gǎi", "jiǎn", "lì", ""], "vi": "Tối qua cậu ấy nghĩ về nghề nghiệp tương lai, nghĩ đến mệt rũ, sáng lại dậy sửa sơ yếu lý lịch.", "en": "Last night he was thinking about a future career until he was too sleepy, and this morning he got up again to revise his CV."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "他有没有方向？", "p": ["tā", "yǒu", "méi", "yǒu", "fāng", "xiàng", ""], "vi": "Cậu ấy đã có hướng chưa?", "en": "Does he have a direction?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "有两个选择，一个偏研究，一个偏语言。我建议他先问清楚，这两个方向以后怎么发展。", "p": ["yǒu", "liǎng", "gè", "xuǎn", "zé", "", "yí", "gè", "piān", "yán", "jiū", "", "yí", "gè", "piān", "yǔ", "yán", "", "wǒ", "jiàn", "yì", "tā", "xiān", "wèn", "qīng", "chǔ", "", "zhè", "liǎng", "gè", "fāng", "xiàng", "yǐ", "hòu", "zěn", "me", "fā", "zhǎn", ""], "vi": "Có hai lựa chọn, một thiên về nghiên cứu, một thiên về ngôn ngữ. Mình khuyên cậu ấy hỏi rõ hai hướng ấy sau này phát triển thế nào.", "en": "There are two options, one more toward research and one more toward language. I suggested he first find out clearly how those two directions might develop later on."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "关键是他自己喜欢哪一种，别只看工资。", "p": ["guān", "jiàn", "shì", "tā", "zì", "jǐ", "xǐ", "huān", "nǎ", "yì", "zhǒng", "", "bié", "zhǐ", "kàn", "gōng", "zī", ""], "vi": "Điều then chốt là bản thân cậu ấy thích loại nào, đừng chỉ nhìn lương.", "en": "The key is which kind he himself likes, not to look only at the pay."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "对。等他起来，我们再一起帮他看看那两份介绍。", "p": ["duì", "", "děng", "tā", "qǐ", "lái", "", "wǒ", "men", "zài", "yì", "qǐ", "bāng", "tā", "kàn", "kàn", "nà", "liǎng", "fèn", "jiè", "shào", ""], "vi": "Đúng. Đợi cậu ấy dậy, mình cùng xem giúp hai bản giới thiệu ấy.", "en": "That's right. When he gets up, we'll go through those two descriptions with him."}]}, {"n": 4, "zh": "短文：小店门口的一句话", "vi": "Đoạn văn: Một câu trước cửa tiệm nhỏ", "en": "Passage: A sentence at the door of a little shop", "kw": ["经济", "条件", "由于", "等", "富", "穷"], "lines": [{"s": "", "sp": [], "t": "社区口有一家小文具店。老板并不富，也不觉得自己穷。由于店面不大，纸、笔、本子等常用的东西他都会进，但不进太贵的。有学生问他：“现在经济条件好的人很多，您不着急扩大吗？”他笑着说：“我得先让到这儿的人买得安心。条件会变，急着变富，容易把该做的事放下。”我听完在门口站了一下。钱当然重要，可把眼前的事做稳，也是一种踏实。", "p": ["shè", "qū", "kǒu", "yǒu", "yì", "jiā", "xiǎo", "wén", "jù", "diàn", "", "lǎo", "bǎn", "bìng", "bú", "fù", "", "yě", "bù", "jué", "de", "zì", "jǐ", "qióng", "", "yóu", "yú", "diàn", "miàn", "bú", "dà", "", "zhǐ", "", "bǐ", "", "běn", "zi", "děng", "cháng", "yòng", "de", "dōng", "xi", "tā", "dōu", "huì", "jìn", "", "dàn", "bú", "jìn", "tài", "guì", "de", "", "yǒu", "xué", "shēng", "wèn", "tā", "", "", "xiàn", "zài", "jīng", "jì", "tiáo", "jiàn", "hǎo", "de", "rén", "hěn", "duō", "", "nín", "bù", "zháo", "jí", "kuò", "dà", "ma", "", "", "tā", "xiào", "zhe", "shuō", "", "", "wǒ", "děi", "xiān", "ràng", "dào", "zhè", "r", "de", "rén", "mǎi", "de", "ān", "xīn", "", "tiáo", "jiàn", "huì", "biàn", "", "jí", "zhe", "biàn", "fù", "", "róng", "yì", "bǎ", "gāi", "zuò", "de", "shì", "fàng", "xià", "", "", "wǒ", "tīng", "wán", "zài", "mén", "kǒu", "zhàn", "le", "yí", "xià", "", "qián", "dāng", "rán", "zhòng", "yào", "", "kě", "bǎ", "yǎn", "qián", "de", "shì", "zuò", "wěn", "", "yě", "shì", "yì", "zhǒng", "tā", "shi", ""], "vi": "Ở cửa khu có một tiệm văn phòng phẩm nhỏ. Ông chủ không giàu, cũng không thấy mình nghèo. Vì cửa tiệm không lớn, giấy, bút, vở và những thứ dùng thường ông đều nhập, nhưng không nhập đồ quá đắt. Có học sinh hỏi: «Giờ nhiều người điều kiện kinh tế tốt, bác không sốt ruột mở rộng sao?» Ông cười: «Tôi phải để người đến đây mua cho yên đã. Điều kiện sẽ đổi, vội giàu thì dễ đặt xuống việc phải làm.» Tôi nghe xong đứng trước cửa một chút. Tiền cố nhiên quan trọng, nhưng làm vững việc trước mắt cũng là một sự chắc chắn.", "en": "There is a little stationery shop at the entrance to the neighbourhood. The owner is not rich, and he does not feel poor either. Because the shop is not large, he stocks paper, pens, notebooks and other everyday things, but he does not stock anything too expensive. A student once asked him, \"Plenty of people have good economic conditions now. Aren't you in a hurry to expand?\" He smiled and said, \"I have to make sure the people who come here can buy with peace of mind first. Conditions will change, and if you rush to get rich, it is easy to put down the work you ought to be doing.\" I stood at the door for a moment after I heard that. Money is important, of course, but doing the work in front of you steadily is also a kind of firmness."}]}, {"n": 5, "zh": "短文：黑板上的几种答案", "vi": "Đoạn văn: Vài lời đáp trên bảng", "en": "Passage: A few answers on the blackboard", "kw": ["比如", "答案", "橡皮", "低", "糖"], "lines": [{"s": "", "sp": [], "t": "语文老师在黑板上写下“什么是幸福”，让大家用一句话回答。答案各不相同。比如有人写“周末能睡到自然醒”，有人写“妈妈泡的、糖放得很低的那杯茶”。一个同学写完又用橡皮轻轻擦掉几个字，改成“和家人一起吃饭”。老师没有说哪一句最对，只说：幸福不一定很响，也不一定很贵。能说出来的答案，往往就在这些很小、很日常的事情里。", "p": ["yǔ", "wén", "lǎo", "shī", "zài", "hēi", "bǎn", "shàng", "xiě", "xià", "", "shén", "me", "shì", "xìng", "fú", "", "", "ràng", "dà", "jiā", "yòng", "yí", "jù", "huà", "huí", "dá", "", "dá", "àn", "gè", "bù", "xiāng", "tóng", "", "bǐ", "rú", "yǒu", "rén", "xiě", "", "zhōu", "mò", "néng", "shuì", "dào", "zì", "rán", "xǐng", "", "", "yǒu", "rén", "xiě", "", "mā", "mā", "pào", "de", "", "táng", "fàng", "de", "hěn", "dī", "de", "nà", "bēi", "chá", "", "", "yí", "gè", "tóng", "xué", "xiě", "wán", "yòu", "yòng", "xiàng", "pí", "qīng", "qīng", "cā", "diào", "jǐ", "gè", "zì", "", "gǎi", "chéng", "", "hé", "jiā", "rén", "yì", "qǐ", "chī", "fàn", "", "", "lǎo", "shī", "méi", "yǒu", "shuō", "nǎ", "yí", "jù", "zuì", "duì", "", "zhǐ", "shuō", "", "xìng", "fú", "bù", "yí", "dìng", "hěn", "xiǎng", "", "yě", "bù", "yí", "dìng", "hěn", "guì", "", "néng", "shuō", "chū", "lái", "de", "dá", "àn", "", "wǎng", "wǎng", "jiù", "zài", "zhè", "xiē", "hěn", "xiǎo", "", "hěn", "rì", "cháng", "de", "shì", "qíng", "lǐ", ""], "vi": "Cô ngữ văn viết lên bảng «Hạnh phúc là gì», bảo cả lớp trả lời bằng một câu. Câu trả lời mỗi người một khác. Chẳng hạn có bạn viết «cuối tuần ngủ đến khi nào tỉnh thì tỉnh», có bạn viết «chén trà mẹ pha, đường để rất thấp». Một bạn viết xong lại dùng tẩy xóa nhẹ vài chữ, sửa thành «ăn cơm cùng gia đình». Cô không nói câu nào đúng nhất, chỉ bảo: hạnh phúc không nhất thiết phải ồn, cũng không nhất thiết phải đắt. Những câu trả lời nói ra được, thường nằm trong những việc rất nhỏ, rất thường ngày ấy.", "en": "The Chinese teacher wrote \"What is happiness?\" on the blackboard and asked everyone to answer in one sentence. The answers were all different. For example, one person wrote \"Being able to sleep until I wake naturally at the weekend\", and another wrote \"The cup of tea my mother makes, with the sugar kept very low\". One classmate finished writing, then gently erased a few characters with an eraser and changed the line to \"Eating with my family\". The teacher did not say which sentence was the most correct, only that happiness does not have to be loud, and does not have to be expensive. The answers you can put into words are often found in these very small, everyday things."}]}]}, {"l": 11, "texts": [{"n": 1, "zh": "阿玲学习阅读", "vi": "A Linh luyện đọc hiểu", "en": "A Linh practises reading", "kw": [], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "这篇文章的内容太复杂了，连题目我都看不懂。", "p": ["zhè", "piān", "wén", "zhāng", "de", "nèi", "róng", "tài", "fù", "zá", "le", "", "lián", "tí", "mù", "wǒ", "dōu", "kàn", "bù", "dǒng", ""], "vi": "Nội dung bài văn này phức tạp quá, đến cả đề bài mình cũng không hiểu.", "en": "This article is so complicated that I can't even understand the title."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "别着急。你可以先猜一猜词语的意思，同时看看上下文。", "p": ["bié", "zháo", "jí", "", "nǐ", "kě", "yǐ", "xiān", "cāi", "yì", "cāi", "cí", "yǔ", "de", "yì", "si", "", "tóng", "shí", "kàn", "kàn", "shàng", "xià", "wén", ""], "vi": "Đừng vội. Cậu có thể đoán nghĩa của từ trước, đồng thời xem ngữ cảnh trước sau.", "en": "Don't worry. You can guess the meaning of the words first and look at the context at the same time."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "可是考试的时候来得及吗？", "p": ["kě", "shì", "kǎo", "shì", "de", "shí", "hòu", "lái", "de", "jí", "ma", ""], "vi": "Nhưng lúc thi có kịp không?", "en": "But will there be enough time in the exam?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "所以平时要养成读书的习惯，否则考试时就会很紧张。", "p": ["suǒ", "yǐ", "píng", "shí", "yào", "yǎng", "chéng", "dú", "shū", "de", "xí", "guàn", "", "fǒu", "zé", "kǎo", "shì", "shí", "jiù", "huì", "hěn", "jǐn", "zhāng", ""], "vi": "Vì vậy bình thường phải tạo thói quen đọc sách, nếu không lúc thi sẽ rất căng thẳng.", "en": "That's why you need to make reading a habit, otherwise you'll be very nervous in the exam."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "无论多忙，我每天都读五页中文杂志，怎么样？", "p": ["wú", "lùn", "duō", "máng", "", "wǒ", "měi", "tiān", "dōu", "dú", "wǔ", "yè", "zhōng", "wén", "zá", "zhì", "", "zěn", "me", "yàng", ""], "vi": "Dù bận đến đâu, mỗi ngày mình đọc năm trang tạp chí tiếng Trung, được không?", "en": "No matter how busy I am, I'll read five pages of a Chinese magazine every day. How's that?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "好主意！坚持下去，你的阅读一定会越来越流利。", "p": ["hǎo", "zhǔ", "yi", "", "jiān", "chí", "xià", "qù", "", "nǐ", "de", "yuè", "dú", "yí", "dìng", "huì", "yuè", "lái", "yuè", "liú", "lì", ""], "vi": "Ý hay! Kiên trì, khả năng đọc của cậu nhất định sẽ ngày càng trôi chảy.", "en": "Good idea! Keep it up and your reading will get more and more fluent."}]}, {"n": 2, "zh": "短文：读书的乐趣", "vi": "Đoạn văn: Niềm vui đọc sách", "en": "Passage: The joy of reading", "kw": [], "lines": [{"s": "", "sp": [], "t": "读书可以增加知识，同时也能让我们放松心情。很多著名的人都有每天阅读的习惯。然而，现在很多年轻人只看手机，很少读完一本书。其实读书不需要很多时间，每天读十几页就够了。在客厅放几本自己喜欢的书，有空儿的时候拿起来看看，慢慢地你就会发现读书的精彩。", "p": ["dú", "shū", "kě", "yǐ", "zēng", "jiā", "zhī", "shi", "", "tóng", "shí", "yě", "néng", "ràng", "wǒ", "men", "fàng", "sōng", "xīn", "qíng", "", "hěn", "duō", "zhù", "míng", "de", "rén", "dōu", "yǒu", "měi", "tiān", "yuè", "dú", "de", "xí", "guàn", "", "rán", "ér", "", "xiàn", "zài", "hěn", "duō", "nián", "qīng", "rén", "zhǐ", "kàn", "shǒu", "jī", "", "hěn", "shǎo", "dú", "wán", "yì", "běn", "shū", "", "qí", "shí", "dú", "shū", "bù", "xū", "yào", "hěn", "duō", "shí", "jiān", "", "měi", "tiān", "dú", "shí", "jǐ", "yè", "jiù", "gòu", "le", "", "zài", "kè", "tīng", "fàng", "jǐ", "běn", "zì", "jǐ", "xǐ", "huān", "de", "shū", "", "yǒu", "kòng", "r", "de", "shí", "hòu", "ná", "qǐ", "lái", "kàn", "kàn", "", "màn", "màn", "dì", "nǐ", "jiù", "huì", "fā", "xiàn", "dú", "shū", "de", "jīng", "cǎi", ""], "vi": "Đọc sách có thể tăng thêm kiến thức, đồng thời cũng giúp chúng ta thư giãn. Nhiều người nổi tiếng có thói quen đọc sách mỗi ngày. Tuy nhiên, bây giờ nhiều bạn trẻ chỉ xem điện thoại, rất ít khi đọc hết một cuốn sách. Thật ra đọc sách không cần nhiều thời gian, mỗi ngày đọc mười mấy trang là đủ. Đặt vài cuốn sách mình thích trong phòng khách, lúc rảnh cầm lên đọc, dần dần bạn sẽ phát hiện ra cái hay của việc đọc sách.", "en": "Reading increases our knowledge and also helps us relax. Many famous people read every day. Yet many young people today only look at their phones and rarely finish a book. In fact reading doesn't take much time — a dozen or so pages a day is enough. Keep a few books you like in the living room and pick one up when you're free; gradually you'll discover how wonderful reading is."}]}]}, {"l": 12, "texts": [{"n": 1, "zh": "阿玲学做越南菜", "vi": "A Linh dạy nấu món Việt", "en": "A Linh teaches Vietnamese cooking", "kw": [], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "阿玲，你能教我做越南春卷吗？", "p": ["ā", "líng", "", "nǐ", "néng", "jiāo", "wǒ", "zuò", "yuè", "nán", "chūn", "juǎn", "ma", ""], "vi": "A Linh, cậu dạy mình làm nem cuốn Việt Nam được không?", "en": "A Linh, can you teach me to make Vietnamese spring rolls?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "当然可以。先把菜洗干净，并且要仔细地切好。", "p": ["dāng", "rán", "kě", "yǐ", "", "xiān", "bǎ", "cài", "xǐ", "gān", "jìng", "", "bìng", "qiě", "yào", "zǐ", "xì", "dì", "qiè", "hǎo", ""], "vi": "Tất nhiên rồi. Trước tiên rửa sạch rau, và phải thái cẩn thận.", "en": "Of course. First wash the vegetables, and cut them carefully."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "要放多少盐？用这个勺子可以吗？", "p": ["yào", "fàng", "duō", "shǎo", "yán", "", "yòng", "zhè", "ge", "sháo", "zi", "kě", "yǐ", "ma", ""], "vi": "Phải cho bao nhiêu muối? Dùng cái thìa này được không?", "en": "How much salt should I add? Can I use this spoon?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "只放一点儿就行。对于越南菜来说，酱汁的作用最大。", "p": ["zhǐ", "fàng", "yì", "diǎn", "r", "jiù", "xíng", "", "duì", "yú", "yuè", "nán", "cài", "lái", "shuō", "", "jiàng", "zhī", "de", "zuò", "yòng", "zuì", "dà", ""], "vi": "Chỉ cho một chút là được. Đối với món Việt, nước chấm đóng vai trò lớn nhất.", "en": "Just a little. For Vietnamese food, the dipping sauce plays the biggest role."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "太可惜了，我把卷饼弄破了。", "p": ["tài", "kě", "xī", "le", "", "wǒ", "bǎ", "juǎn", "bǐng", "nòng", "pò", "le", ""], "vi": "Tiếc quá, mình làm rách bánh tráng rồi.", "en": "Oh no, I've torn the rice paper."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "没关系，再难也别放弃。你看，这次卷得很好！", "p": ["méi", "guān", "xì", "", "zài", "nán", "yě", "bié", "fàng", "qì", "", "nǐ", "kàn", "", "zhè", "cì", "juǎn", "de", "hěn", "hǎo", ""], "vi": "Không sao, khó mấy cũng đừng bỏ cuộc. Cậu xem, lần này cuốn đẹp lắm!", "en": "Never mind — however hard it is, don't give up. Look, this one's rolled perfectly!"}]}, {"n": 2, "zh": "短文：语言和误会", "vi": "Đoạn văn: Ngôn ngữ và hiểu lầm", "en": "Passage: Language and misunderstandings", "kw": [], "lines": [{"s": "", "sp": [], "t": "学习一门语言，不只是学习语法和词语，还要了解别人的文化。有一次，阿玲的中国朋友问她：“你吃了吗？”她以为朋友要请她吃饭，结果引起了误会。后来朋友解释说，这只是打招呼的一种方法。相反，越南人见面常常问“你去哪儿？”。也许每种语言都有这样有趣的地方，我们应该友好地互相学习。", "p": ["xué", "xí", "yì", "mén", "yǔ", "yán", "", "bù", "zhǐ", "shì", "xué", "xí", "yǔ", "fǎ", "hé", "cí", "yǔ", "", "hái", "yào", "liǎo", "jiě", "bié", "rén", "de", "wén", "huà", "", "yǒu", "yí", "cì", "", "ā", "líng", "de", "zhōng", "guó", "péng", "you", "wèn", "tā", "", "", "nǐ", "chī", "le", "ma", "", "", "tā", "yǐ", "wéi", "péng", "you", "yào", "qǐng", "tā", "chī", "fàn", "", "jié", "guǒ", "yǐn", "qǐ", "le", "wù", "huì", "", "hòu", "lái", "péng", "you", "jiě", "shì", "shuō", "", "zhè", "zhǐ", "shì", "dǎ", "zhāo", "hu", "de", "yì", "zhǒng", "fāng", "fǎ", "", "xiāng", "fǎn", "", "yuè", "nán", "rén", "jiàn", "miàn", "cháng", "cháng", "wèn", "", "nǐ", "qù", "nǎ", "r", "", "", "", "yě", "xǔ", "měi", "zhǒng", "yǔ", "yán", "dōu", "yǒu", "zhè", "yàng", "yǒu", "qù", "de", "dì", "fāng", "", "wǒ", "men", "yīng", "gāi", "yǒu", "hǎo", "dì", "hù", "xiāng", "xué", "xí", ""], "vi": "Học một ngôn ngữ không chỉ là học ngữ pháp và từ vựng, mà còn phải hiểu văn hóa của người khác. Có lần bạn Trung Quốc của A Linh hỏi cô: \"Cậu ăn chưa?\" Cô tưởng bạn muốn mời mình đi ăn, kết quả gây ra hiểu lầm. Sau đó bạn giải thích rằng đây chỉ là một cách chào hỏi. Ngược lại, người Việt gặp nhau thường hỏi \"Đi đâu đấy?\". Có lẽ mỗi ngôn ngữ đều có những điểm thú vị như vậy, chúng ta nên học hỏi lẫn nhau một cách thân thiện.", "en": "Learning a language means not just learning grammar and words but also understanding other cultures. Once a Chinese friend asked A Linh, \"Have you eaten?\" She thought her friend was inviting her for a meal, which caused a misunderstanding. Her friend later explained it's just a way of saying hello. In contrast, Vietnamese people often greet each other with \"Where are you going?\". Perhaps every language has interesting things like this, and we should learn from each other in a friendly way."}]}]}, {"l": 13, "texts": [{"n": 1, "zh": "阿玲第一次看京剧", "vi": "A Linh lần đầu xem Kinh kịch", "en": "A Linh sees Peking opera for the first time", "kw": [], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "昨天的京剧表演怎么样？", "p": ["zuó", "tiān", "de", "jīng", "jù", "biǎo", "yǎn", "zěn", "me", "yàng", ""], "vi": "Buổi biểu diễn Kinh kịch hôm qua thế nào?", "en": "How was the Peking opera performance yesterday?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "十分精彩！演员的衣服特别漂亮，观众大概有五百人。", "p": ["shí", "fēn", "jīng", "cǎi", "", "yǎn", "yuán", "de", "yī", "fú", "tè", "bié", "piào", "liàng", "", "guān", "zhòng", "dà", "gài", "yǒu", "wǔ", "bǎi", "rén", ""], "vi": "Rất đặc sắc! Trang phục của diễn viên đặc biệt đẹp, khán giả khoảng năm trăm người.", "en": "Wonderful! The actors' costumes were beautiful, and there were about five hundred people in the audience."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你听得懂吗？", "p": ["nǐ", "tīng", "de", "dǒng", "ma", ""], "vi": "Cậu nghe hiểu không?", "en": "Could you understand it?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "只听懂一部分，不过旁边有字幕，稍微看一下就明白了。", "p": ["zhǐ", "tīng", "dǒng", "yí", "bù", "fèn", "", "bú", "guò", "páng", "biān", "yǒu", "zì", "mù", "", "shāo", "wēi", "kàn", "yí", "xià", "jiù", "míng", "bái", "le", ""], "vi": "Chỉ hiểu được một phần, nhưng bên cạnh có phụ đề, nhìn qua một chút là hiểu.", "en": "Only part of it, but there were subtitles at the side, so a quick look was enough."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "我偶尔也去看。随着年龄增加，我越来越喜欢京剧了。", "p": ["wǒ", "ǒu", "ěr", "yě", "qù", "kàn", "", "suí", "zhe", "nián", "líng", "zēng", "jiā", "", "wǒ", "yuè", "lái", "yuè", "xǐ", "huān", "jīng", "jù", "le", ""], "vi": "Thỉnh thoảng mình cũng đi xem. Càng lớn tuổi mình càng thích Kinh kịch.", "en": "I go occasionally too. As I get older, I like Peking opera more and more."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "下次演出我们一起去吧，由我来买票！", "p": ["xià", "cì", "yǎn", "chū", "wǒ", "men", "yì", "qǐ", "qù", "ba", "", "yóu", "wǒ", "lái", "mǎi", "piào", ""], "vi": "Lần biểu diễn sau mình cùng đi nhé, để mình mua vé!", "en": "Let's go together to the next show — I'll buy the tickets!"}]}, {"n": 2, "zh": "短文：互联网和生活", "vi": "Đoạn văn: Internet và cuộc sống", "en": "Passage: The internet and daily life", "kw": [], "lines": [{"s": "", "sp": [], "t": "随着互联网的发展，我们的生活发生了很大的变化。现在，在网上申请工作、和来自世界各地的人讨论问题都非常普遍。阿玲每天晚上都和越南的家人视频，好像他们就在身边一样。不过，互联网也有缺点，有的人一上网就是好几个小时。所以，我们应该正确地使用它，让它成为生活的好帮手。", "p": ["suí", "zhe", "hù", "lián", "wǎng", "de", "fā", "zhǎn", "", "wǒ", "men", "de", "shēng", "huó", "fā", "shēng", "le", "hěn", "dà", "de", "biàn", "huà", "", "xiàn", "zài", "", "zài", "wǎng", "shàng", "shēn", "qǐng", "gōng", "zuò", "", "hé", "lái", "zì", "shì", "jiè", "gè", "dì", "de", "rén", "tǎo", "lùn", "wèn", "tí", "dōu", "fēi", "cháng", "pǔ", "biàn", "", "ā", "líng", "měi", "tiān", "wǎn", "shàng", "dōu", "hé", "yuè", "nán", "de", "jiā", "rén", "shì", "pín", "", "hǎo", "xiàng", "tā", "men", "jiù", "zài", "shēn", "biān", "yí", "yàng", "", "bú", "guò", "", "hù", "lián", "wǎng", "yě", "yǒu", "quē", "diǎn", "", "yǒu", "de", "rén", "yí", "shàng", "wǎng", "jiù", "shì", "hǎo", "jǐ", "gè", "xiǎo", "shí", "", "suǒ", "yǐ", "", "wǒ", "men", "yīng", "gāi", "zhèng", "què", "dì", "shǐ", "yòng", "tā", "", "ràng", "tā", "chéng", "wéi", "shēng", "huó", "de", "hǎo", "bāng", "shǒu", ""], "vi": "Cùng với sự phát triển của Internet, cuộc sống của chúng ta đã thay đổi rất nhiều. Bây giờ, xin việc trên mạng hay thảo luận với những người đến từ khắp nơi trên thế giới đều rất phổ biến. Tối nào A Linh cũng gọi video với gia đình ở Việt Nam, cứ như họ đang ở ngay bên cạnh. Tuy nhiên, Internet cũng có nhược điểm, có người đã lên mạng là mấy tiếng liền. Vì vậy, chúng ta nên sử dụng nó đúng cách, để nó trở thành người trợ thủ tốt trong cuộc sống.", "en": "With the development of the internet, our lives have changed enormously. Applying for jobs online or discussing things with people from all over the world is now very common. Every evening A Linh video-calls her family in Vietnam, as if they were right beside her. But the internet has its downsides too — some people spend hours online at a time. So we should use it properly and make it a good helper in our lives."}]}]}, {"l": 14, "texts": [{"n": 1, "zh": "阿玲出差", "vi": "A Linh đi công tác", "en": "A Linh goes on a business trip", "kw": [], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "这次出差要乘坐火车，我的行李箱太重了。", "p": ["zhè", "cì", "chū", "chāi", "yào", "chéng", "zuò", "huǒ", "chē", "", "wǒ", "de", "xíng", "li", "xiāng", "tài", "zhòng", "le", ""], "vi": "Lần này đi công tác phải đi tàu hỏa, vali của mình nặng quá.", "en": "This business trip is by train, and my suitcase is too heavy."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你都带了什么？", "p": ["nǐ", "dōu", "dài", "le", "shén", "me", ""], "vi": "Cậu mang những gì thế?", "en": "What have you packed?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "毛巾、牙膏、衣服什么的，还有很多材料。", "p": ["máo", "jīn", "", "yá", "gāo", "", "yī", "fú", "shén", "me", "de", "", "hái", "yǒu", "hěn", "duō", "cái", "liào", ""], "vi": "Khăn mặt, kem đánh răng, quần áo các thứ, còn có rất nhiều tài liệu.", "en": "Towels, toothpaste, clothes and so on, plus lots of documents."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "既然酒店有毛巾和牙膏，你就别带了，还能减少塑料袋。", "p": ["jì", "rán", "jiǔ", "diàn", "yǒu", "máo", "jīn", "hé", "yá", "gāo", "", "nǐ", "jiù", "bié", "dài", "le", "", "hái", "néng", "jiǎn", "shǎo", "sù", "liào", "dài", ""], "vi": "Khách sạn đã có khăn và kem đánh răng thì cậu đừng mang nữa, còn giảm được túi ni-lông.", "en": "Since the hotel has towels and toothpaste, don't bring them — that also cuts down on plastic bags."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "有道理，于是我又把它们拿出来了。现在轻多了！", "p": ["yǒu", "dào", "lǐ", "", "yú", "shì", "wǒ", "yòu", "bǎ", "tā", "men", "ná", "chū", "lái", "le", "", "xiàn", "zài", "qīng", "duō", "le", ""], "vi": "Có lý, thế là mình lại lấy chúng ra. Giờ nhẹ hơn nhiều rồi!", "en": "Good point — so I've taken them out again. It's much lighter now!"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "路上注意安全，到了给我发个消息。", "p": ["lù", "shàng", "zhù", "yì", "ān", "quán", "", "dào", "le", "gěi", "wǒ", "fā", "gè", "xiāo", "xi", ""], "vi": "Đi đường cẩn thận, đến nơi nhắn tin cho mình nhé.", "en": "Be safe on the way and send me a message when you arrive."}]}, {"n": 2, "zh": "短文：保护我们的地球", "vi": "Đoạn văn: Bảo vệ Trái Đất của chúng ta", "en": "Passage: Protecting our Earth", "kw": [], "lines": [{"s": "", "sp": [], "t": "地球是我们共同的家，可是现在污染越来越严重，温度也越来越高。其实保护地球并不难，每个人都可以从小事做起：少用塑料袋，不乱扔垃圾，离开房间时关灯，出门时多乘坐公共汽车。阿玲的公司还鼓励员工以骑自行车的方式上班。只要大家一起努力，地球一定会更美丽。", "p": ["dì", "qiú", "shì", "wǒ", "men", "gòng", "tóng", "de", "jiā", "", "kě", "shì", "xiàn", "zài", "wū", "rǎn", "yuè", "lái", "yuè", "yán", "zhòng", "", "wēn", "dù", "yě", "yuè", "lái", "yuè", "gāo", "", "qí", "shí", "bǎo", "hù", "dì", "qiú", "bìng", "bù", "nán", "", "měi", "gè", "rén", "dōu", "kě", "yǐ", "cóng", "xiǎo", "shì", "zuò", "qǐ", "", "shǎo", "yòng", "sù", "liào", "dài", "", "bú", "luàn", "rēng", "lā", "jī", "", "lí", "kāi", "fáng", "jiān", "shí", "guān", "dēng", "", "chū", "mén", "shí", "duō", "chéng", "zuò", "gōng", "gòng", "qì", "chē", "", "ā", "líng", "de", "gōng", "sī", "hái", "gǔ", "lì", "yuán", "gōng", "yǐ", "qí", "zì", "xíng", "chē", "de", "fāng", "shì", "shàng", "bān", "", "zhǐ", "yào", "dà", "jiā", "yì", "qǐ", "nǔ", "lì", "", "dì", "qiú", "yí", "dìng", "huì", "gèng", "měi", "lì", ""], "vi": "Trái Đất là ngôi nhà chung của chúng ta, nhưng bây giờ ô nhiễm ngày càng nghiêm trọng, nhiệt độ cũng ngày càng cao. Thật ra bảo vệ Trái Đất không khó, mỗi người đều có thể bắt đầu từ việc nhỏ: dùng ít túi ni-lông, không vứt rác bừa bãi, tắt đèn khi rời phòng, ra ngoài đi xe buýt nhiều hơn. Công ty của A Linh còn khuyến khích nhân viên đi làm bằng xe đạp. Chỉ cần mọi người cùng cố gắng, Trái Đất nhất định sẽ đẹp hơn.", "en": "The Earth is our shared home, but pollution is getting worse and temperatures keep rising. Protecting the Earth isn't actually hard; everyone can start with small things: use fewer plastic bags, don't litter, switch off the lights when you leave a room, and take the bus more often. A Linh's company even encourages staff to cycle to work. As long as we all make an effort, the Earth will surely become more beautiful."}]}]}, {"l": 15, "texts": [{"n": 1, "zh": "阿玲学弹钢琴", "vi": "A Linh học đàn piano", "en": "A Linh learns the piano", "kw": [], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "我刚才听到有人在弹钢琴，原来是你呀！", "p": ["wǒ", "gāng", "cái", "tīng", "dào", "yǒu", "rén", "zài", "tán", "gāng", "qín", "", "yuán", "lái", "shì", "nǐ", "ya", ""], "vi": "Vừa nãy mình nghe thấy có người đánh đàn piano, hóa ra là cậu à!", "en": "I just heard someone playing the piano — so it was you!"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我才学了两个星期，弹得很笨，你千万别笑我。", "p": ["wǒ", "cái", "xué", "le", "liǎng", "gè", "xīng", "qī", "", "tán", "de", "hěn", "bèn", "", "nǐ", "qiān", "wàn", "bié", "xiào", "wǒ", ""], "vi": "Mình mới học được hai tuần, đánh vụng lắm, cậu đừng cười mình nhé.", "en": "I've only been learning for two weeks and I'm clumsy. Please don't laugh at me."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "怎么会呢？已经很棒了。你怎么想起来学钢琴了？", "p": ["zěn", "me", "huì", "ne", "", "yǐ", "jīng", "hěn", "bàng", "le", "", "nǐ", "zěn", "me", "xiǎng", "qǐ", "lái", "xué", "gāng", "qín", "le", ""], "vi": "Sao thế được? Đã hay lắm rồi. Sao cậu lại nghĩ đến việc học piano?", "en": "Of course not! It's already great. What made you think of learning the piano?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "小时候我就想学，可是家里没条件。现在终于有机会了。", "p": ["xiǎo", "shí", "hòu", "wǒ", "jiù", "xiǎng", "xué", "", "kě", "shì", "jiā", "lǐ", "méi", "tiáo", "jiàn", "", "xiàn", "zài", "zhōng", "yú", "yǒu", "jī", "huì", "le", ""], "vi": "Hồi nhỏ mình đã muốn học, nhưng nhà không có điều kiện. Bây giờ cuối cùng cũng có cơ hội.", "en": "I wanted to learn when I was little, but my family couldn't afford it. Now I finally have the chance."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你每天练多长时间？", "p": ["nǐ", "měi", "tiān", "liàn", "duō", "cháng", "shí", "jiān", ""], "vi": "Mỗi ngày cậu tập bao lâu?", "en": "How long do you practise each day?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "一个小时左右。老师表扬我进步很快，我有点儿骄傲了！", "p": ["yī", "gè", "xiǎo", "shí", "zuǒ", "yòu", "", "lǎo", "shī", "biǎo", "yáng", "wǒ", "jìn", "bù", "hěn", "kuài", "", "wǒ", "yǒu", "diǎn", "r", "jiāo", "ào", "le", ""], "vi": "Khoảng một tiếng. Thầy khen mình tiến bộ nhanh, mình hơi tự hào rồi đấy!", "en": "About an hour. My teacher praised me for improving quickly — I'm a little proud!"}]}, {"n": 2, "zh": "短文：教育孩子的方法", "vi": "Đoạn văn: Cách dạy con", "en": "Passage: How to bring up children", "kw": [], "lines": [{"s": "", "sp": [], "t": "儿童都喜欢被表扬。如果孩子做得好，父母应该及时表扬他；如果孩子粗心弄错了，也不要马上批评，而是耐心地告诉他应该怎么做。有的孩子很害羞，父母可以多鼓励他和别人交流。总之，管理孩子不能只靠批评，合适的方法比严格更重要。", "p": ["ér", "tóng", "dōu", "xǐ", "huān", "bèi", "biǎo", "yáng", "", "rú", "guǒ", "hái", "zi", "zuò", "de", "hǎo", "", "fù", "mǔ", "yīng", "gāi", "jí", "shí", "biǎo", "yáng", "tā", "", "rú", "guǒ", "hái", "zi", "cū", "xīn", "nòng", "cuò", "le", "", "yě", "bú", "yào", "mǎ", "shàng", "pī", "píng", "", "ér", "shì", "nài", "xīn", "dì", "gào", "sù", "tā", "yīng", "gāi", "zěn", "me", "zuò", "", "yǒu", "de", "hái", "zi", "hěn", "hài", "xiū", "", "fù", "mǔ", "kě", "yǐ", "duō", "gǔ", "lì", "tā", "hé", "bié", "rén", "jiāo", "liú", "", "zǒng", "zhī", "", "guǎn", "lǐ", "hái", "zi", "bù", "néng", "zhǐ", "kào", "pī", "píng", "", "hé", "shì", "de", "fāng", "fǎ", "bǐ", "yán", "gé", "gèng", "zhòng", "yào", ""], "vi": "Trẻ em đều thích được khen. Nếu con làm tốt, cha mẹ nên khen kịp thời; nếu con sơ ý làm sai, cũng đừng phê bình ngay mà nên kiên nhẫn nói cho con biết phải làm thế nào. Có những đứa trẻ rất hay xấu hổ, cha mẹ có thể khuyến khích con giao tiếp với người khác nhiều hơn. Tóm lại, dạy con không thể chỉ dựa vào phê bình, phương pháp phù hợp quan trọng hơn nghiêm khắc.", "en": "Children all love to be praised. If a child does well, parents should praise them promptly; if the child makes a careless mistake, don't criticise straight away but patiently show them what to do. Some children are shy, and parents can encourage them to talk with others more. In short, raising children can't rely on criticism alone — the right method matters more than strictness."}]}]}, {"l": 16, "texts": [{"n": 1, "zh": "阿玲办签证", "vi": "A Linh làm visa", "en": "A Linh applies for a visa", "kw": [], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "小雪，我要报名参加一个夏令营，可是签证到底怎么办？", "p": ["xiǎo", "xuě", "", "wǒ", "yào", "bào", "míng", "cān", "jiā", "yí", "gè", "xià", "lìng", "yíng", "", "kě", "shì", "qiān", "zhèng", "dào", "dǐ", "zěn", "me", "bàn", ""], "vi": "Tiểu Tuyết, mình muốn đăng ký trại hè, nhưng rốt cuộc làm visa thế nào?", "en": "Xiaoxue, I want to sign up for a summer camp, but how on earth do I get a visa?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你先在网上填好表格，然后去大使馆交材料。", "p": ["nǐ", "xiān", "zài", "wǎng", "shàng", "tián", "hǎo", "biǎo", "gé", "", "rán", "hòu", "qù", "dà", "shǐ", "guǎn", "jiāo", "cái", "liào", ""], "vi": "Cậu điền tờ khai trên mạng trước, sau đó đến đại sứ quán nộp hồ sơ.", "en": "First fill in the form online, then take your documents to the embassy."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "表格上的内容太多了，我恐怕会填错。", "p": ["biǎo", "gé", "shàng", "de", "nèi", "róng", "tài", "duō", "le", "", "wǒ", "kǒng", "pà", "huì", "tián", "cuò", ""], "vi": "Nội dung trong tờ khai nhiều quá, mình sợ sẽ điền sai.", "en": "There's so much on the form — I'm afraid I'll get it wrong."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "别着急，冷静一点儿。我陪你一起填，千万不能马虎。", "p": ["bié", "zháo", "jí", "", "lěng", "jìng", "yì", "diǎn", "r", "", "wǒ", "péi", "nǐ", "yì", "qǐ", "tián", "", "qiān", "wàn", "bù", "néng", "mǎ", "hǔ", ""], "vi": "Đừng vội, bình tĩnh chút. Mình cùng cậu điền, tuyệt đối không được cẩu thả.", "en": "Don't worry, stay calm. I'll fill it in with you — we mustn't be careless."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "太好了！有你在，我就敢自己去大使馆了。", "p": ["tài", "hǎo", "le", "", "yǒu", "nǐ", "zài", "", "wǒ", "jiù", "gǎn", "zì", "jǐ", "qù", "dà", "shǐ", "guǎn", "le", ""], "vi": "Tốt quá! Có cậu, mình dám tự đi đại sứ quán rồi.", "en": "Wonderful! With you here, I'll dare to go to the embassy on my own."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "可别忘了带护照和照片啊！", "p": ["kě", "bié", "wàng", "le", "dài", "hù", "zhào", "hé", "zhào", "piān", "a", ""], "vi": "Nhớ đừng quên mang hộ chiếu và ảnh đấy nhé!", "en": "Just don't forget your passport and photos!"}]}, {"n": 2, "zh": "短文：尊重别人", "vi": "Đoạn văn: Tôn trọng người khác", "en": "Passage: Respecting others", "kw": [], "lines": [{"s": "", "sp": [], "t": "尊重别人是一种礼貌。拿说话来说，别人讲话时不要随便打断，要认真地听。有时候朋友输了比赛，心情不好，我们应该同情他、鼓励他，而不是笑他。当我们尊重别人时，别人也会重视我们。一个有自信的人，往往也懂得尊重别人。", "p": ["zūn", "zhòng", "bié", "rén", "shì", "yì", "zhǒng", "lǐ", "mào", "", "ná", "shuō", "huà", "lái", "shuō", "", "bié", "rén", "jiǎng", "huà", "shí", "bú", "yào", "suí", "biàn", "dǎ", "duàn", "", "yào", "rèn", "zhēn", "dì", "tīng", "", "yǒu", "shí", "hòu", "péng", "you", "shū", "le", "bǐ", "sài", "", "xīn", "qíng", "bù", "hǎo", "", "wǒ", "men", "yīng", "gāi", "tóng", "qíng", "tā", "", "gǔ", "lì", "tā", "", "ér", "bú", "shì", "xiào", "tā", "", "dāng", "wǒ", "men", "zūn", "zhòng", "bié", "rén", "shí", "", "bié", "rén", "yě", "huì", "zhòng", "shì", "wǒ", "men", "", "yí", "gè", "yǒu", "zì", "xìn", "de", "rén", "", "wǎng", "wǎng", "yě", "dǒng", "de", "zūn", "zhòng", "bié", "rén", ""], "vi": "Tôn trọng người khác là một phép lịch sự. Lấy việc nói chuyện làm ví dụ, khi người khác đang nói đừng tùy tiện ngắt lời, phải chăm chú lắng nghe. Có khi bạn bè thua cuộc thi, tâm trạng không tốt, chúng ta nên thông cảm và động viên họ chứ không phải cười họ. Khi chúng ta tôn trọng người khác, người khác cũng sẽ coi trọng chúng ta. Một người tự tin thường cũng biết tôn trọng người khác.", "en": "Respecting others is a form of politeness. Take speaking, for example: don't casually interrupt when someone is talking — listen carefully. When a friend loses a competition and feels low, we should sympathise and encourage them, not laugh at them. When we respect others, they will value us too. A confident person usually knows how to respect others as well."}]}]}, {"l": 17, "texts": [{"n": 1, "zh": "阿玲放暑假", "vi": "A Linh nghỉ hè", "en": "A Linh's summer holiday", "kw": [], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "快放暑假了，你有什么计划？", "p": ["kuài", "fàng", "shǔ", "jià", "le", "", "nǐ", "yǒu", "shén", "me", "jì", "huà", ""], "vi": "Sắp nghỉ hè rồi, cậu có kế hoạch gì?", "en": "The summer holiday's coming. Any plans?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我想去海边玩儿一趟，那儿比城市凉快多了。", "p": ["wǒ", "xiǎng", "qù", "hǎi", "biān", "wán", "r", "yí", "tàng", "", "nà", "r", "bǐ", "chéng", "shì", "liáng", "kuài", "duō", "le", ""], "vi": "Mình muốn đi biển chơi một chuyến, ở đó mát hơn thành phố nhiều.", "en": "I'd like to take a trip to the seaside — it's much cooler than the city."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "可是暑假的时候人特别多，到处都要排队。", "p": ["kě", "shì", "shǔ", "jià", "de", "shí", "hòu", "rén", "tè", "bié", "duō", "", "dào", "chù", "dōu", "yào", "pái", "duì", ""], "vi": "Nhưng nghỉ hè đông người lắm, chỗ nào cũng phải xếp hàng.", "en": "But it's really crowded in the summer holidays; you have to queue everywhere."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "人多倒是没关系，我就喜欢热闹。", "p": ["rén", "duō", "dào", "shì", "méi", "guān", "xì", "", "wǒ", "jiù", "xǐ", "huān", "rè", "nào", ""], "vi": "Đông người thì cũng chẳng sao, mình thích náo nhiệt mà.", "en": "Crowds don't bother me — I like a lively atmosphere."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "那我们一起去吧！为了省钱，我们可以早点儿订票。", "p": ["nà", "wǒ", "men", "yì", "qǐ", "qù", "ba", "", "wèi", "le", "shěng", "qián", "", "wǒ", "men", "kě", "yǐ", "zǎo", "diǎn", "r", "dìng", "piào", ""], "vi": "Vậy mình đi cùng nhau đi! Để tiết kiệm tiền, mình có thể đặt vé sớm.", "en": "Then let's go together! To save money, we can book tickets early."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "好！虽然还有一个月，我仍然已经开始兴奋了。", "p": ["hǎo", "", "suī", "rán", "hái", "yǒu", "yí", "gè", "yuè", "", "wǒ", "réng", "rán", "yǐ", "jīng", "kāi", "shǐ", "xīng", "fèn", "le", ""], "vi": "Được! Tuy còn một tháng nữa, mình vẫn đã bắt đầu háo hức rồi.", "en": "Great! Even though it's still a month away, I'm already getting excited."}]}, {"n": 2, "zh": "短文：大海的梦", "vi": "Đoạn văn: Giấc mơ về biển", "en": "Passage: Dreaming of the sea", "kw": [], "lines": [{"s": "", "sp": [], "t": "阿玲从小就有一个梦：去看大海。第一次看到海洋时，她激动得抱住了妈妈。蓝色的海水，白色的云，活泼的孩子在沙滩上跑来跑去。她觉得大自然真是太美了。现在社会竞争越来越大，人们的生活压力也很大。有空儿的时候，去海边走走，心情就会好很多。", "p": ["ā", "líng", "cóng", "xiǎo", "jiù", "yǒu", "yí", "gè", "mèng", "", "qù", "kàn", "dà", "hǎi", "", "dì", "yī", "cì", "kàn", "dào", "hǎi", "yáng", "shí", "", "tā", "jī", "dòng", "de", "bào", "zhù", "le", "mā", "mā", "", "lán", "sè", "de", "hǎi", "shuǐ", "", "bái", "sè", "de", "yún", "", "huó", "pō", "de", "hái", "zi", "zài", "shā", "tān", "shàng", "pǎo", "lái", "pǎo", "qù", "", "tā", "jué", "de", "dà", "zì", "rán", "zhēn", "shì", "tài", "měi", "le", "", "xiàn", "zài", "shè", "huì", "jìng", "zhēng", "yuè", "lái", "yuè", "dà", "", "rén", "men", "de", "shēng", "huó", "yā", "lì", "yě", "hěn", "dà", "", "yǒu", "kòng", "r", "de", "shí", "hòu", "", "qù", "hǎi", "biān", "zǒu", "zǒu", "", "xīn", "qíng", "jiù", "huì", "hǎo", "hěn", "duō", ""], "vi": "Từ nhỏ A Linh đã có một giấc mơ: đi ngắm biển. Lần đầu tiên nhìn thấy đại dương, cô xúc động đến mức ôm chầm lấy mẹ. Nước biển xanh, mây trắng, những đứa trẻ hiếu động chạy tới chạy lui trên bãi cát. Cô thấy thiên nhiên thật là đẹp quá. Bây giờ xã hội cạnh tranh ngày càng gay gắt, áp lực cuộc sống của con người cũng rất lớn. Lúc rảnh rỗi, đi dạo bên bờ biển, tâm trạng sẽ tốt lên rất nhiều.", "en": "Ever since she was little, A Linh had a dream: to see the sea. When she first saw the ocean, she was so excited she hugged her mother. Blue water, white clouds, lively children running back and forth on the sand — she thought nature was just so beautiful. Society today is ever more competitive, and people are under a lot of pressure. When you have free time, a walk by the sea will make you feel much better."}]}]}, {"l": 18, "texts": [{"n": 1, "zh": "阿玲迷路了", "vi": "A Linh bị lạc đường", "en": "A Linh gets lost", "kw": [], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "喂，小雪，我好像迷路了，手机也快没电了。", "p": ["wèi", "", "xiǎo", "xuě", "", "wǒ", "hǎo", "xiàng", "mí", "lù", "le", "", "shǒu", "jī", "yě", "kuài", "méi", "diàn", "le", ""], "vi": "Alo, Tiểu Tuyết, hình như mình bị lạc đường rồi, điện thoại cũng sắp hết pin.", "en": "Hello, Xiaoxue? I think I'm lost, and my phone's nearly out of battery."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "别着急，你周围有什么？", "p": ["bié", "zháo", "jí", "", "nǐ", "zhōu", "wéi", "yǒu", "shén", "me", ""], "vi": "Đừng lo, xung quanh cậu có gì?", "en": "Don't panic. What's around you?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "前面有一座桥，旁边是一个邮局。", "p": ["qián", "miàn", "yǒu", "yí", "zuò", "qiáo", "", "páng", "biān", "shì", "yí", "gè", "yóu", "jú", ""], "vi": "Phía trước có một cây cầu, bên cạnh là một bưu điện.", "en": "There's a bridge ahead, and a post office next to it."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "我知道了。你过了桥一直往前走，接着往左拐，就能看到我们学校的门了。", "p": ["wǒ", "zhī", "dào", "le", "", "nǐ", "guò", "le", "qiáo", "yì", "zhí", "wǎng", "qián", "zǒu", "", "jiē", "zhe", "wǎng", "zuǒ", "guǎi", "", "jiù", "néng", "kàn", "dào", "wǒ", "men", "xué", "xiào", "de", "mén", "le", ""], "vi": "Mình biết rồi. Cậu qua cầu đi thẳng, tiếp đó rẽ trái là thấy cổng trường mình.", "en": "I know where you are. Cross the bridge, keep going straight, then turn left and you'll see our school gate."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "太好了！我真受不了自己，总是记不住路。", "p": ["tài", "hǎo", "le", "", "wǒ", "zhēn", "shòu", "bù", "liǎo", "zì", "jǐ", "", "zǒng", "shì", "jì", "bú", "zhù", "lù", ""], "vi": "Tốt quá! Mình chịu hết nổi bản thân, lúc nào cũng không nhớ đường.", "en": "Great! I can't stand myself — I can never remember the way."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "下次出门前先在地图上查一下地址，就安全多了。", "p": ["xià", "cì", "chū", "mén", "qián", "xiān", "zài", "dì", "tú", "shàng", "chá", "yí", "xià", "dì", "zhǐ", "", "jiù", "ān", "quán", "duō", "le", ""], "vi": "Lần sau trước khi ra ngoài tra địa chỉ trên bản đồ trước, sẽ an toàn hơn nhiều.", "en": "Next time check the address on the map before you go out — it's much safer."}]}, {"n": 2, "zh": "短文：网上付款", "vi": "Đoạn văn: Thanh toán trực tuyến", "en": "Passage: Paying online", "kw": [], "lines": [{"s": "", "sp": [], "t": "现在，用手机付款越来越普遍了。买东西、坐车、吃饭，只要输入密码，几秒钟就能完成。这种技术给生活带来了很多方便。除此以外，在网站上还能买火车票、交电费。不过，我们也要注意安全，不要把密码告诉别人，也不要随便打开不认识的网站。是否安全，关键在于我们自己是否小心。", "p": ["xiàn", "zài", "", "yòng", "shǒu", "jī", "fù", "kuǎn", "yuè", "lái", "yuè", "pǔ", "biàn", "le", "", "mǎi", "dōng", "xi", "", "zuò", "chē", "", "chī", "fàn", "", "zhǐ", "yào", "shū", "rù", "mì", "mǎ", "", "jǐ", "miǎo", "zhōng", "jiù", "néng", "wán", "chéng", "", "zhè", "zhǒng", "jì", "shù", "gěi", "shēng", "huó", "dài", "lái", "le", "hěn", "duō", "fāng", "biàn", "", "chú", "cǐ", "yǐ", "wài", "", "zài", "wǎng", "zhàn", "shàng", "hái", "néng", "mǎi", "huǒ", "chē", "piào", "", "jiāo", "diàn", "fèi", "", "bú", "guò", "", "wǒ", "men", "yě", "yào", "zhù", "yì", "ān", "quán", "", "bú", "yào", "bǎ", "mì", "mǎ", "gào", "sù", "bié", "rén", "", "yě", "bú", "yào", "suí", "biàn", "dǎ", "kāi", "bú", "rèn", "shí", "de", "wǎng", "zhàn", "", "shì", "fǒu", "ān", "quán", "", "guān", "jiàn", "zài", "yú", "wǒ", "men", "zì", "jǐ", "shì", "fǒu", "xiǎo", "xīn", ""], "vi": "Bây giờ thanh toán bằng điện thoại ngày càng phổ biến. Mua đồ, đi xe, ăn uống, chỉ cần nhập mật khẩu, vài giây là xong. Công nghệ này mang lại rất nhiều tiện lợi cho cuộc sống. Ngoài ra, trên trang web còn có thể mua vé tàu, trả tiền điện. Tuy nhiên, chúng ta cũng phải chú ý an toàn, đừng nói mật khẩu cho người khác, cũng đừng tùy tiện mở những trang web lạ. An toàn hay không, then chốt là ở chỗ bản thân chúng ta có cẩn thận hay không.", "en": "Paying by phone is becoming more and more common. Shopping, taking a ride, eating out — just enter your password and it's done in a few seconds. This technology brings a lot of convenience. Besides that, you can buy train tickets and pay electricity bills on websites. But we must stay safe: don't tell anyone your password, and don't casually open unfamiliar websites. Whether it's safe or not depends on whether we ourselves are careful."}]}]}, {"l": 19, "texts": [{"n": 1, "zh": "阿玲找房子", "vi": "A Linh tìm nhà", "en": "A Linh looks for a flat", "kw": [], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "我想租一个离学校近的房子，你有什么好主意吗？", "p": ["wǒ", "xiǎng", "zū", "yí", "gè", "lí", "xué", "xiào", "jìn", "de", "fáng", "zi", "", "nǐ", "yǒu", "shén", "me", "hǎo", "zhǔ", "yi", "ma", ""], "vi": "Mình muốn thuê một căn nhà gần trường, cậu có ý gì hay không?", "en": "I want to rent a place near school. Any good ideas?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你可以在网上找找，或者直接给房东打电话。", "p": ["nǐ", "kě", "yǐ", "zài", "wǎng", "shàng", "zhǎo", "zhǎo", "", "huò", "zhě", "zhí", "jiē", "gěi", "fáng", "dōng", "dǎ", "diàn", "huà", ""], "vi": "Cậu có thể tìm trên mạng, hoặc gọi thẳng cho chủ nhà.", "en": "You could look online, or phone the landlords directly."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我刚才打了好几次，都占线。", "p": ["wǒ", "gāng", "cái", "dǎ", "le", "hǎo", "jǐ", "cì", "", "dōu", "zhàn", "xiàn", ""], "vi": "Mình vừa gọi mấy lần rồi, đều máy bận.", "en": "I've just called several times, but the line's always busy."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "别急，谁都有忙的时候。这个房子的厨房大不大？", "p": ["bié", "jí", "", "shéi", "dōu", "yǒu", "máng", "de", "shí", "hòu", "", "zhè", "ge", "fáng", "zi", "de", "chú", "fáng", "dà", "bú", "dà", ""], "vi": "Đừng vội, ai cũng có lúc bận. Căn này bếp có rộng không?", "en": "Don't worry, everyone's busy sometimes. Is the kitchen in this one big?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "挺大的，我可以在里面包饺子！总的来说，我很满意。", "p": ["tǐng", "dà", "de", "", "wǒ", "kě", "yǐ", "zài", "lǐ", "miàn", "bāo", "jiǎo", "zi", "", "zǒng", "de", "lái", "shuō", "", "wǒ", "hěn", "mǎn", "yì", ""], "vi": "Khá rộng, mình có thể gói sủi cảo trong đó! Nói chung là mình rất hài lòng.", "en": "Pretty big — I could make dumplings in there! Overall, I'm very happy with it."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "那就快去看看吧，好房子可不等人。", "p": ["nà", "jiù", "kuài", "qù", "kàn", "kàn", "ba", "", "hǎo", "fáng", "zi", "kě", "bù", "děng", "rén", ""], "vi": "Vậy mau đi xem đi, nhà đẹp không chờ người đâu.", "en": "Then go and see it quickly — good flats don't wait for anyone."}]}, {"n": 2, "zh": "短文：学一门功夫", "vi": "Đoạn văn: Học một môn võ", "en": "Passage: Learning a martial art", "kw": [], "lines": [{"s": "", "sp": [], "t": "阿玲这个学期报名学中国功夫。第一节课，老师先教大家打招呼，然后让大家抬胳膊、转身。阿玲觉得很难，可是老师说：“学功夫的关键在于坚持，谁都是从不会到会的。”现在，阿玲每天早上都练习半个小时。她说，功夫不仅让她身体更好，还让她更有耐心了。", "p": ["ā", "líng", "zhè", "ge", "xué", "qī", "bào", "míng", "xué", "zhōng", "guó", "gōng", "fu", "", "dì", "yī", "jié", "kè", "", "lǎo", "shī", "xiān", "jiāo", "dà", "jiā", "dǎ", "zhāo", "hu", "", "rán", "hòu", "ràng", "dà", "jiā", "tái", "gē", "bó", "", "zhuǎn", "shēn", "", "ā", "líng", "jué", "de", "hěn", "nán", "", "kě", "shì", "lǎo", "shī", "shuō", "", "", "xué", "gōng", "fu", "de", "guān", "jiàn", "zài", "yú", "jiān", "chí", "", "shéi", "dōu", "shì", "cóng", "bú", "huì", "dào", "huì", "de", "", "", "xiàn", "zài", "", "ā", "líng", "měi", "tiān", "zǎo", "shàng", "dōu", "liàn", "xí", "bàn", "gè", "xiǎo", "shí", "", "tā", "shuō", "", "gōng", "fu", "bù", "jǐn", "ràng", "tā", "shēn", "tǐ", "gèng", "hǎo", "", "hái", "ràng", "tā", "gèng", "yǒu", "nài", "xīn", "le", ""], "vi": "Học kỳ này A Linh đăng ký học võ Trung Quốc. Buổi học đầu tiên, thầy dạy mọi người chào hỏi trước, sau đó cho mọi người nâng tay, xoay người. A Linh thấy rất khó, nhưng thầy nói: \"Mấu chốt của việc học võ là ở sự kiên trì, ai cũng từ không biết đến biết.\" Bây giờ sáng nào A Linh cũng luyện tập nửa tiếng. Cô nói, võ thuật không chỉ giúp cô khỏe hơn mà còn giúp cô kiên nhẫn hơn.", "en": "This term A Linh signed up for Chinese kung fu. In the first class the teacher taught everyone how to greet, then had them raise their arms and turn around. A Linh found it hard, but the teacher said, \"The key to learning kung fu is persistence — everyone goes from not knowing to knowing.\" Now A Linh practises for half an hour every morning. She says kung fu has not only made her healthier but also more patient."}]}]}, {"l": 20, "texts": [{"n": 1, "zh": "阿玲和小雪去旅行", "vi": "A Linh và Tiểu Tuyết đi du lịch", "en": "A Linh and Xiaoxue go travelling", "kw": [], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "航班推迟了一个小时，我们究竟几点出发？", "p": ["háng", "bān", "tuī", "chí", "le", "yí", "gè", "xiǎo", "shí", "", "wǒ", "men", "jiū", "jìng", "jǐ", "diǎn", "chū", "fā", ""], "vi": "Chuyến bay hoãn một tiếng rồi, rốt cuộc mấy giờ mình xuất phát?", "en": "The flight's been delayed an hour. So what time are we actually leaving?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "别着急，我们先去换登机牌，然后吃点儿东西。", "p": ["bié", "zháo", "jí", "", "wǒ", "men", "xiān", "qù", "huàn", "dēng", "jī", "pái", "", "rán", "hòu", "chī", "diǎn", "r", "dōng", "xi", ""], "vi": "Đừng vội, mình đi đổi thẻ lên máy bay trước, rồi ăn chút gì đó.", "en": "Don't worry, let's get our boarding passes first and then grab something to eat."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "好。这次去成都，你最想吃什么？", "p": ["hǎo", "", "zhè", "cì", "qù", "chéng", "dū", "", "nǐ", "zuì", "xiǎng", "chī", "shén", "me", ""], "vi": "Được. Lần này đi Thành Đô, cậu muốn ăn gì nhất?", "en": "OK. On this trip to Chengdu, what do you most want to eat?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "当然是小吃！听说那儿的菜又香又辣。", "p": ["dāng", "rán", "shì", "xiǎo", "chī", "", "tīng", "shuō", "nà", "r", "de", "cài", "yòu", "xiāng", "yòu", "là", ""], "vi": "Tất nhiên là đồ ăn vặt! Nghe nói món ăn ở đó vừa thơm vừa cay.", "en": "Street food, of course! I hear the food there is fragrant and spicy."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你一到那儿就会爱上它的。来，为我们的旅行干杯！", "p": ["nǐ", "yí", "dào", "nà", "r", "jiù", "huì", "ài", "shàng", "tā", "de", "", "lái", "", "wèi", "wǒ", "men", "de", "lǚ", "xíng", "gān", "bēi", ""], "vi": "Cậu vừa đến đó là sẽ yêu nó ngay. Nào, cạn ly cho chuyến du lịch của chúng mình!", "en": "You'll fall in love with it the moment you arrive. Come on — cheers to our trip!"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "干杯！说着说着，我都饿了。", "p": ["gān", "bēi", "", "shuō", "zhe", "shuō", "zhe", "", "wǒ", "dōu", "è", "le", ""], "vi": "Cạn ly! Nói mãi nói mãi, mình đói luôn rồi.", "en": "Cheers! All this talking is making me hungry."}]}, {"n": 2, "zh": "短文：旅行的意义", "vi": "Đoạn văn: Ý nghĩa của du lịch", "en": "Passage: Why we travel", "kw": [], "lines": [{"s": "", "sp": [], "t": "旅行可以让我们看到不同的风景，认识不同的民族，尝到各地的小吃。阿玲第一次来中国时，普通话说得不太好，常常闹笑话。现在她不但能和当地人对话，还能帮朋友收拾行李、安排路线。她说，旅行最大的收获不是照片，而是在路上成长起来的自己。", "p": ["lǚ", "xíng", "kě", "yǐ", "ràng", "wǒ", "men", "kàn", "dào", "bù", "tóng", "de", "fēng", "jǐng", "", "rèn", "shí", "bù", "tóng", "de", "mín", "zú", "", "cháng", "dào", "gè", "dì", "de", "xiǎo", "chī", "", "ā", "líng", "dì", "yī", "cì", "lái", "zhōng", "guó", "shí", "", "pǔ", "tōng", "huà", "shuō", "de", "bú", "tài", "hǎo", "", "cháng", "cháng", "nào", "xiào", "huà", "", "xiàn", "zài", "tā", "bú", "dàn", "néng", "hé", "dāng", "dì", "rén", "duì", "huà", "", "hái", "néng", "bāng", "péng", "you", "shōu", "shí", "xíng", "li", "", "ān", "pái", "lù", "xiàn", "", "tā", "shuō", "", "lǚ", "xíng", "zuì", "dà", "de", "shōu", "huò", "bú", "shì", "zhào", "piān", "", "ér", "shì", "zài", "lù", "shàng", "chéng", "zhǎng", "qǐ", "lái", "de", "zì", "jǐ", ""], "vi": "Du lịch giúp chúng ta ngắm những cảnh sắc khác nhau, làm quen với những dân tộc khác nhau, nếm thử món ăn vặt ở khắp nơi. Lần đầu tiên A Linh đến Trung Quốc, tiếng phổ thông nói chưa tốt lắm, thường xuyên nói nhầm gây cười. Bây giờ cô không những có thể trò chuyện với người địa phương mà còn giúp bạn bè thu dọn hành lý, sắp xếp lộ trình. Cô nói, thu hoạch lớn nhất của du lịch không phải là những tấm ảnh, mà là bản thân đã trưởng thành trên đường đi.", "en": "Travel lets us see different scenery, meet different peoples and taste snacks from all over. When A Linh first came to China, her Mandarin wasn't very good and she often made funny mistakes. Now she can not only chat with locals but also help friends pack and plan their routes. She says the greatest reward of travel isn't the photos but the person you grow into along the way."}]}]}];
